let highestCyberWindowZ = 30;

function bringCyberWindowToFront(dock) {
  if (!dock) return;
  highestCyberWindowZ++;
  dock.style.setProperty("z-index", `${highestCyberWindowZ}`, "important");
}


// ==========================================================================
// CYBER EDGE PANELS DOCK & EXPAND SYSTEM
// ==========================================================================

function checkDropOnEdgePanel(clientX, clientY) {
  const winW = window.innerWidth;
  const winH = window.innerHeight;
  const panelLeft = document.getElementById("home-edge-panel-left");
  const panelRight = document.getElementById("home-edge-panel-right");

  const leftZoneWidth = (panelLeft && panelLeft.classList.contains("is-visible"))
    ? Math.max(60, panelLeft.offsetWidth)
    : 20;
  const rightZoneWidth = (panelRight && panelRight.classList.contains("is-visible"))
    ? Math.max(60, panelRight.offsetWidth)
    : 20;

  // Left panel zone
  if (clientX <= leftZoneWidth && clientY >= 0 && clientY <= winH) {
    return "left";
  }

  // Right panel zone
  if (clientX >= winW - rightZoneWidth && clientY >= 0 && clientY <= winH) {
    return "right";
  }

  return null;
}

function updateEdgePanelsDragOver(clientX, clientY) {
  const zoneLeft = document.getElementById("edge-dock-zone-left");
  const zoneRight = document.getElementById("edge-dock-zone-right");
  const panelLeft = document.getElementById("home-edge-panel-left");
  const panelRight = document.getElementById("home-edge-panel-right");

  // Only open panel while dragging if cursor actually touches the narrow edge perimetral zone (within 20px)
  if (clientX <= 20) {
    if (panelLeft) panelLeft.classList.add("is-visible");
  }
  if (clientX >= window.innerWidth - 20) {
    if (panelRight) panelRight.classList.add("is-visible");
  }

  const dropSide = checkDropOnEdgePanel(clientX, clientY);
  if (zoneLeft) zoneLeft.classList.toggle("is-drag-over", dropSide === "left");
  if (zoneRight) zoneRight.classList.toggle("is-drag-over", dropSide === "right");
}

function clearEdgePanelsDragOver() {
  const zoneLeft = document.getElementById("edge-dock-zone-left");
  const zoneRight = document.getElementById("edge-dock-zone-right");
  if (zoneLeft) zoneLeft.classList.remove("is-drag-over");
  if (zoneRight) zoneRight.classList.remove("is-drag-over");
}

function dockWindowIntoPanel(dock, side = "left", targetIndex = -1) {
  if (!dock) return;
  const targetZone = side === "left"
    ? document.getElementById("edge-dock-zone-left")
    : document.getElementById("edge-dock-zone-right");
  if (!targetZone) return;

  // Capture open geometry if docked from window mode
  if (!dock.classList.contains("is-minimized") && !dock.classList.contains("is-docked-in-panel")) {
    if (dock.dataset.customFloatingWidth) {
      dock.dataset.openWidth = dock.dataset.customFloatingWidth;
    } else if (dock.offsetWidth > 100) {
      dock.dataset.openWidth = `${dock.offsetWidth}`;
      dock.dataset.customFloatingWidth = `${dock.offsetWidth}`;
    }
    if (dock.dataset.customFloatingHeight) {
      dock.dataset.openHeight = dock.dataset.customFloatingHeight;
    } else if (dock.offsetHeight > 100) {
      dock.dataset.openHeight = `${dock.offsetHeight}`;
      dock.dataset.customFloatingHeight = `${dock.offsetHeight}`;
    }
    const curL = parseFloat(dock.style.left) || dock.offsetLeft;
    const curT = parseFloat(dock.style.top) || dock.offsetTop;
    if (!isNaN(curL)) dock.dataset.openLeft = `${curL}`;
    if (!isNaN(curT)) dock.dataset.openTop = `${curT}`;
  }

  if (dock._physicsAnimId) {
    cancelAnimationFrame(dock._physicsAnimId);
    dock._physicsAnimId = null;
  }
  dock.classList.remove("is-falling-physics");
  dock.classList.remove("is-holding-minimized");
  dock.classList.remove("is-dragging");

  // Remove is-minimized so 48px square styles do not fight flexbox
  dock.classList.remove("is-minimized");
  dock.classList.remove("is-docked-expanded");
  dock.classList.add("is-docked-in-panel");
  dock.dataset.dockedSide = side;

  // Clear all inline position & geometry styles
  dock.style.removeProperty("position");
  dock.style.removeProperty("left");
  dock.style.removeProperty("top");
  dock.style.removeProperty("right");
  dock.style.removeProperty("bottom");
  dock.style.removeProperty("width");
  dock.style.removeProperty("height");
  dock.style.removeProperty("min-width");
  dock.style.removeProperty("max-width");
  dock.style.removeProperty("min-height");
  dock.style.removeProperty("max-height");
  dock.style.removeProperty("transform");
  dock.style.removeProperty("margin");
  dock.style.cssText = "";
  dock.removeAttribute("title");

  if (targetIndex >= 0 && targetIndex < targetZone.children.length) {
    targetZone.insertBefore(dock, targetZone.children[targetIndex]);
  } else {
    targetZone.appendChild(dock);
  }

  const panel = side === "left"
    ? document.getElementById("home-edge-panel-left")
    : document.getElementById("home-edge-panel-right");
  if (panel) {
    panel.classList.add("is-visible");
  }

  setupDockedWindowInteractions(dock);
  saveWindowsLayout();
}

function expandDockedWindowInPanel(dock) {
  if (!dock) return;
  const dropzone = dock.parentElement;
  if (!dropzone) return;
  const panel = dock.closest(".home-edge-panel");

  // User requirement: multiple options can be open simultaneously, distributing height!
  dock.classList.add("is-docked-expanded");
  dock.classList.remove("is-minimized");
  dock.classList.add("no-minimize-btn");
  dock.dataset.noMinimize = "true";

  // Restore remembered flex dimension if previously resized
  if (dock.dataset.dockedFlex) {
    dock.style.setProperty("flex", dock.dataset.dockedFlex, "important");
  } else {
    dock.style.setProperty("flex", "1 1 0px", "important");
  }
  dock.style.removeProperty("height");
  delete dock.dataset.dockedHeight;

  dropzone.classList.add("has-expanded");

  // Balance open siblings so all open cards share vertical space proportionally without overflow
  const allOpen = Array.from(dropzone.querySelectorAll(".is-docked-in-panel.is-docked-expanded"));
  const hasPixelFlex = allOpen.some(d => d.dataset.dockedFlex && parseFloat(d.dataset.dockedFlex) > 10);
  if (hasPixelFlex) {
    allOpen.forEach(d => {
      if (!d.dataset.dockedFlex || parseFloat(d.dataset.dockedFlex) <= 10) {
        const defFlex = Math.max(100, Math.floor(dropzone.clientHeight / allOpen.length));
        d.style.setProperty("flex", `${defFlex} 1 0px`, "important");
        d.dataset.dockedFlex = `${defFlex} 1 0px`;
      }
    });
  }

  // User requested: remove collapse button from cards
  dock.querySelectorAll(".hw-btn-collapse").forEach(btn => btn.remove());

  // Clean up any old separator element if present
  dock.querySelectorAll(".docked-window-resizer-v").forEach(el => el.remove());

  // Refresh contents if needed (e.g. Colección grid or timeline)
  if (dock.id === "home-coleccion-dock" && typeof renderMiColeccionGrid === "function") {
    renderMiColeccionGrid();
  }
  saveWindowsLayout();
}

function collapseDockedWindowInPanel(dock) {
  if (!dock) return;
  // Remember its resized flex before removing inline flex style
  if (dock.style.flex && dock.style.flex !== "none") {
    dock.dataset.dockedFlex = dock.style.flex;
  }
  dock.classList.remove("is-docked-expanded");
  dock.style.removeProperty("flex");
  dock.style.removeProperty("height");
  delete dock.dataset.dockedHeight;

  const dropzone = dock.parentElement;
  if (!dropzone) return;
  const panel = dock.closest(".home-edge-panel");

  const otherExpanded = dropzone.querySelectorAll(".is-docked-in-panel.is-docked-expanded");
  if (otherExpanded.length === 0) {
    dropzone.classList.remove("has-expanded");
  }
  saveWindowsLayout();
}

function expandDockedWindow(dock) {
  expandDockedWindowInPanel(dock);
}

function setupDockedWindowInteractions(dock) {
  if (dock._hasDockedListeners) return;
  dock._hasDockedListeners = true;

  let startX = 0;
  let startY = 0;
  let isDraggingDocked = false;
  let hasMoved = false;

  dock.addEventListener("pointerdown", (e) => {
    if (!dock.classList.contains("is-docked-in-panel")) return;
    if (e.button !== 0) return;

    // Never interfere with interactive controls, click targets, or resize handles
    if (e.target.closest("button, a, input, select, textarea, .hw-btn-collapse, .hcp-win-btn, .accesos-item, .actividad-timeline, .coleccion-card, .cyber-resize-handle")) {
      return;
    }

    if (document.body.classList.contains("cyber-resizing-active") || dock.classList.contains("is-resizing")) {
      return;
    }

    const isExpanded = dock.classList.contains("is-docked-expanded");
    // If expanded, dragging/undocking is only initiated from the header
    if (isExpanded && !e.target.closest(".hcp-header")) {
      return;
    }

    startX = e.clientX;
    startY = e.clientY;
    isDraggingDocked = true;
    hasMoved = false;

    const currentSide = dock.dataset.dockedSide || "left";
    const currentZone = dock.parentElement;

    const onPointerMove = (ev) => {
      if (!isDraggingDocked) return;
      if (document.body.classList.contains("cyber-resizing-active") || dock.classList.contains("is-resizing")) {
        return;
      }
      const dx = ev.clientX - startX;
      const dy = ev.clientY - startY;

      if (Math.abs(dx) > 6 || Math.abs(dy) > 6) {
        hasMoved = true;
        dock.classList.add("is-docked-dragging");
      }

      if (!hasMoved) return;

      const panel = currentSide === "left"
        ? document.getElementById("home-edge-panel-left")
        : document.getElementById("home-edge-panel-right");
      const panelRect = panel ? panel.getBoundingClientRect() : null;

      const isOutOfPanel = currentSide === "left"
        ? (panelRect && ev.clientX > panelRect.right + 30)
        : (panelRect && ev.clientX < panelRect.left - 30);

      if (isOutOfPanel) {
        if (document.body.classList.contains("cyber-resizing-active") || dock.classList.contains("is-resizing")) {
          return;
        }
        cleanup();
        if (dock.classList.contains("is-docked-expanded")) {
          collapseDockedWindowInPanel(dock);
        }
        undockToCursor(dock, ev);
        return;
      }

      // Reorder items inside panel (works both when open and when collapsed!): the card goes
      // before the first one whose middle is below the pointer.
      if (currentZone) {
        const next =
          Array.from(currentZone.children)
            .filter((c) => c !== dock)
            .find((c) => {
              const r = c.getBoundingClientRect();
              return ev.clientY < r.top + r.height / 2;
            }) || null;
        if (dock.nextElementSibling !== next) currentZone.insertBefore(dock, next);
      }
    };

    const onPointerUp = (ev) => {
      if (!isDraggingDocked) return;
      cleanup();

      if (!hasMoved) {
        // Click on collapsed window -> expand it inside panel
        if (!dock.classList.contains("is-docked-expanded")) {
          expandDockedWindowInPanel(dock);
        }
      } else {
        saveWindowsLayout();
      }
    };

    const cleanup = () => {
      isDraggingDocked = false;
      dock.classList.remove("is-docked-dragging");
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointercancel", onPointerUp);
    };

    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointercancel", onPointerUp);
  });
}

function undockToCursor(dock, ev) {
  const stage = document.querySelector(".home-stage-content") || document.getElementById("view-inicio");
  if (stage && dock.parentElement !== stage) {
    stage.appendChild(dock);
  }

  dock.classList.remove("is-docked-in-panel");
  dock.classList.remove("is-docked-expanded");
  dock.classList.remove("no-minimize-btn");
  delete dock.dataset.noMinimize;
  delete dock.dataset.dockedSide;

  dock.style.flex = "";
  dock.style.removeProperty("flex");
  delete dock.dataset.dockedFlex;
  delete dock.dataset.dockedHeight;

  let savedW = dock.dataset.customFloatingWidth;
  let savedH = dock.dataset.customFloatingHeight;
  if (!savedW || parseFloat(savedW) <= 100) {
    try {
      const stored = JSON.parse(localStorage.getItem(`modcomparer_float_size_${dock.id}`) || "{}");
      if (stored.width) savedW = stored.width;
      if (stored.height) savedH = stored.height;
    } catch (_) {}
  }
  dock.dataset.openWidth = savedW || (dock.id === "home-coleccion-dock" ? "520" : (dock.id === "home-accesos-dock" ? "280" : "510"));
  dock.dataset.openHeight = savedH || (dock.id === "home-coleccion-dock" ? "420" : (dock.id === "home-accesos-dock" ? "320" : "380"));
  dock.dataset.customFloatingWidth = dock.dataset.openWidth;
  dock.dataset.customFloatingHeight = dock.dataset.openHeight;

  dock.classList.add("is-minimized");

  // Remove collapse button so floating window displays minimize button
  const colBtn = dock.querySelector(".hw-btn-collapse");
  if (colBtn) {
    colBtn.remove();
  }

  // Clean up any edge panels if empty or had expanded
  ["edge-dock-zone-left", "edge-dock-zone-right"].forEach((zoneId) => {
    const z = document.getElementById(zoneId);
    if (z && !z.querySelector(".is-docked-expanded")) {
      z.classList.remove("has-expanded");
    }
  });

  const title = dock.querySelector(".hcp-title")?.textContent || "Ventana";
  startHoldingAndBouncingCyberWindow(dock, null, title, ev);
}

function makeDraggable(element, handle, options = {}) {
  if (!element || !handle) return;
  handle.style.cursor = "grab";
  handle.style.userSelect = "none";
  handle.style.webkitUserSelect = "none";

  let isDragging = false;
  let startX = 0;
  let startY = 0;
  let initialLeft = 0;
  let initialTop = 0;

  const onPointerDown = (e) => {
    if (e.button !== 0) return;
    if (isDragging) return;
    // Docked windows inside panel are managed exclusively by setupDockedWindowInteractions
    if (element.classList.contains("is-docked-in-panel")) return;

    bringCyberWindowToFront(element);

    const isMin = element.classList.contains("is-minimized");
    // If not minimized, only start drag if pointerdown is inside the handle
    if (!isMin && !handle.contains(e.target)) return;

    if (e.target.closest("button, input, select, textarea, a, .hcp-win-btn, .modal-close")) {
      if (!isMin) return;
    }

    const captureTarget = isMin ? element : handle;
    const container = options.container || element.offsetParent || document.body;
    const containerRect = container.getBoundingClientRect();
    const elemRect = element.getBoundingClientRect();

    isDragging = true;
    try {
      captureTarget.setPointerCapture(e.pointerId);
    } catch (_) {}

    element.classList.add("is-dragging");
    handle.style.cursor = "grabbing";

    const currentLeft = elemRect.left - containerRect.left;
    const currentTop = elemRect.top - containerRect.top;

    element.style.position = "absolute";
    element.style.right = "auto";
    element.style.bottom = "auto";
    element.style.transform = "none";
    element.style.margin = "0";
    element.style.left = `${currentLeft}px`;
    element.style.top = `${currentTop}px`;

    startX = e.clientX;
    startY = e.clientY;
    initialLeft = currentLeft;
    initialTop = currentTop;
    let dragMoved = false;

    const onPointerMove = (ev) => {
      if (!isDragging) return;
      const dx = ev.clientX - startX;
      const dy = ev.clientY - startY;
      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
        dragMoved = true;
      }

      let newLeft = initialLeft + dx;
      let newTop = initialTop + dy;

      const cWidth = container.clientWidth || window.innerWidth;
      const cHeight = container.clientHeight || window.innerHeight;
      const eWidth = element.offsetWidth;
      const eHeight = element.offsetHeight;

      const topBarHeight = 60; // Minimum Y to avoid custom titlebar (52px + 8px margin)
      const bottomBarHeight = 168; // Minimum margin to avoid bottom cyber play dock (150px + margin)

      const isCyberWin = element.classList.contains("home-cyber-window") || element.classList.contains("home-console-preview-dock");
      const isModal = element.classList.contains("modal-box");
      const maxLeft = (isCyberWin || isModal) ? (cWidth - 80) : Math.max(10, cWidth - eWidth - 10);
      const minLeft = (isCyberWin || isModal) ? (-eWidth + 80) : 10;
      const minTop = isModal ? 6 : topBarHeight;
      const maxTop = isModal ? Math.max(minTop, cHeight - 56) : Math.max(minTop, cHeight - eHeight - bottomBarHeight);

      newLeft = Math.max(minLeft, Math.min(newLeft, maxLeft));
      newTop = Math.max(minTop, Math.min(newTop, maxTop));

      element.style.left = `${newLeft}px`;
      element.style.top = `${newTop}px`;
      if (isCyberWin || element.classList.contains("is-minimized")) {
        updateEdgePanelsDragOver(ev.clientX, ev.clientY);
      }
    };

    const onPointerUp = (ev) => {
      if (!isDragging) return;
      isDragging = false;
      clearEdgePanelsDragOver();
      const isCyberWin = element.classList.contains("home-cyber-window") || element.classList.contains("home-console-preview-dock");
      if (element.classList.contains("is-minimized") || isCyberWin) {
        const dropSide = checkDropOnEdgePanel(ev.clientX, ev.clientY);
        if (dropSide) {
          try { captureTarget.releasePointerCapture(ev.pointerId); } catch (_) {}
          handle.style.cursor = "grab";
          element.classList.remove("is-dragging");
          window.removeEventListener("pointermove", onPointerMove);
          window.removeEventListener("pointerup", onPointerUp);
          window.removeEventListener("pointercancel", onPointerUp);
          dockWindowIntoPanel(element, dropSide);
          return;
        }
      }
      if (dragMoved) {
        element.dataset.justDragged = "true";
        setTimeout(() => { element.dataset.justDragged = "false"; }, 250);
        if (isCyberWin) saveWindowsLayout();
      }
      try {
        captureTarget.releasePointerCapture(ev.pointerId);
      } catch (_) {}
      handle.style.cursor = "grab";
      element.classList.remove("is-dragging");
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointercancel", onPointerUp);
    };

    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointercancel", onPointerUp);
  };

  handle.addEventListener("pointerdown", onPointerDown);
  element.addEventListener("pointerdown", (e) => {
    if (element.classList.contains("is-minimized")) {
      onPointerDown(e);
    }
  });
}

function makeResizable(element, options = {}) {
  if (!element) return;
  if (element.querySelector(".cyber-resize-handle")) return; // Prevent duplicate setup

  const isModal = element.classList.contains("modal-box");
  const minWidth = options.minWidth || 220;
  const minHeight = options.minHeight || 160;
  const topBarHeight = options.topMargin ?? (isModal ? 6 : 60); // Titlebar clearance
  const bottomBarHeight = options.bottomMargin ?? (isModal ? 6 : 168); // Bottom dock clearance

  const directions = [
    { dir: "se", cursor: "nwse-resize", className: "cyber-resize-se" },
    { dir: "s", cursor: "ns-resize", className: "cyber-resize-s" },
    { dir: "e", cursor: "ew-resize", className: "cyber-resize-e" },
    { dir: "sw", cursor: "nesw-resize", className: "cyber-resize-sw" },
    { dir: "w", cursor: "ew-resize", className: "cyber-resize-w" },
    { dir: "ne", cursor: "nesw-resize", className: "cyber-resize-ne" },
    { dir: "nw", cursor: "nwse-resize", className: "cyber-resize-nw" },
    { dir: "n", cursor: "ns-resize", className: "cyber-resize-n" }
  ];

  directions.forEach(({ dir, cursor, className }) => {
    const handle = document.createElement("div");
    handle.className = `cyber-resize-handle ${className}`;
    handle.dataset.dir = dir;

    if (dir === "se") {
      handle.title = "Redimensionar ventana (diagonal)";
    }

    const onPointerDown = (e) => {
      if (e.button !== 0) return;
      if (element.classList.contains("is-minimized")) return;
      if (!isModal) bringCyberWindowToFront(element);
      e.preventDefault();
      e.stopPropagation();

      // In-panel edge resizing: only the height. The width is the panel's, and that is fixed.
      if (element.classList.contains("is-docked-in-panel")) {
        if (!element.classList.contains("is-docked-expanded")) return;
        if (!dir.includes("s") && !dir.includes("n")) return;
        const panel = element.closest(".home-edge-panel");
        const dropzone = element.parentElement;

        const startY = e.clientY;
        const startH = element.offsetHeight;

        const openSiblings = dropzone ? Array.from(dropzone.children).filter(c => c.classList.contains("is-docked-in-panel") && c.classList.contains("is-docked-expanded")) : [];
        const dockIndex = openSiblings.indexOf(element);
        const nextDock = dockIndex >= 0 && dockIndex < openSiblings.length - 1 ? openSiblings[dockIndex + 1] : null;
        const prevDock = dockIndex > 0 ? openSiblings[dockIndex - 1] : null;

        // Capture starting heights of all open siblings
        const startHeights = openSiblings.map(s => s.offsetHeight);
        const nextStartH = nextDock ? nextDock.offsetHeight : null;
        const prevStartH = prevDock ? prevDock.offsetHeight : null;

        // Set all open siblings to flex: 0 0 ${h}px so they are sized explicitly from top down
        openSiblings.forEach((s, idx) => {
          s.style.setProperty("flex", `0 0 ${startHeights[idx]}px`, "important");
          s.style.setProperty("height", `${startHeights[idx]}px`, "important");
          s.dataset.dockedFlex = `0 0 ${startHeights[idx]}px`;
          s.dataset.dockedHeight = `${startHeights[idx]}px`;
        });

        element.classList.add("is-resizing");
        if (panel) panel.classList.add("is-resizing");
        if (dropzone) dropzone.classList.add("is-resizing");
        document.body.classList.add("cyber-resizing-active");
        document.body.style.cursor = cursor;

        try {
          handle.setPointerCapture(e.pointerId);
        } catch (_) {}

        const onDockedMove = (ev) => {
          const dy = ev.clientY - startY;

          // Vertical resizing ("alto" / height)
          if (dir.includes("s")) {
            const minH = 60;
            const dropzoneH = dropzone.clientHeight;
            const openCount = openSiblings.length;
            const maxTotalAvail = dropzoneH - 28 - ((openCount - 1) * 12);

            if (nextDock && nextStartH !== null) {
              // Divider between element and nextDock
              const otherH = startHeights.reduce((sum, h, i) => (i !== dockIndex && i !== dockIndex + 1 ? sum + h : sum), 0);
              const maxPair = maxTotalAvail - otherH;
              const pairTotal = Math.min(startH + nextStartH, maxPair);

              let newH = startH + dy;
              let newNextH = nextStartH - dy;

              if (newH < minH) {
                newH = minH;
                newNextH = pairTotal - minH;
              } else if (newNextH < minH) {
                newNextH = minH;
                newH = pairTotal - minH;
              }

              element.style.setProperty("flex", `0 0 ${newH}px`, "important");
              element.style.setProperty("height", `${newH}px`, "important");
              element.dataset.dockedFlex = `0 0 ${newH}px`;
              element.dataset.dockedHeight = `${newH}px`;

              nextDock.style.setProperty("flex", `0 0 ${newNextH}px`, "important");
              nextDock.style.setProperty("height", `${newNextH}px`, "important");
              nextDock.dataset.dockedFlex = `0 0 ${newNextH}px`;
              nextDock.dataset.dockedHeight = `${newNextH}px`;
            } else {
              // Bottom card (e.g. Consola when at bottom):
              // Bottom edge shrinks UPWARDS freely, detaching from bottom edge of panel
              const otherH = startHeights.reduce((sum, h, i) => (i !== dockIndex ? sum + h : sum), 0);
              const maxH = Math.max(minH, maxTotalAvail - otherH);
              let newH = Math.max(minH, Math.min(startH + dy, maxH));

              element.style.setProperty("flex", `0 0 ${newH}px`, "important");
              element.style.setProperty("height", `${newH}px`, "important");
              element.dataset.dockedFlex = `0 0 ${newH}px`;
              element.dataset.dockedHeight = `${newH}px`;
            }
          } else if (dir.includes("n")) {
            const minH = 60;
            const dropzoneH = dropzone.clientHeight;
            const openCount = openSiblings.length;
            const maxTotalAvail = dropzoneH - 28 - ((openCount - 1) * 12);

            if (prevDock && prevStartH !== null) {
              // Divider between prevDock and element
              const otherH = startHeights.reduce((sum, h, i) => (i !== dockIndex && i !== dockIndex - 1 ? sum + h : sum), 0);
              const maxPair = maxTotalAvail - otherH;
              const pairTotal = Math.min(startH + prevStartH, maxPair);

              let newH = startH - dy;
              let newPrevH = prevStartH + dy;

              if (newH < minH) {
                newH = minH;
                newPrevH = pairTotal - minH;
              } else if (newPrevH < minH) {
                newPrevH = minH;
                newH = pairTotal - minH;
              }

              element.style.setProperty("flex", `0 0 ${newH}px`, "important");
              element.style.setProperty("height", `${newH}px`, "important");
              element.dataset.dockedFlex = `0 0 ${newH}px`;
              element.dataset.dockedHeight = `${newH}px`;

              prevDock.style.setProperty("flex", `0 0 ${newPrevH}px`, "important");
              prevDock.style.setProperty("height", `${newPrevH}px`, "important");
              prevDock.dataset.dockedFlex = `0 0 ${newPrevH}px`;
              prevDock.dataset.dockedHeight = `${newPrevH}px`;
            }
          }
        };

        const onDockedUp = (ev) => {
          try {
            handle.releasePointerCapture(ev.pointerId);
          } catch (_) {}
          element.classList.remove("is-resizing");
          if (panel) panel.classList.remove("is-resizing");
          if (dropzone) dropzone.classList.remove("is-resizing");
          document.body.classList.remove("cyber-resizing-active");
          document.body.style.cursor = "";
          window.removeEventListener("pointermove", onDockedMove);
          window.removeEventListener("pointerup", onDockedUp);
          window.removeEventListener("pointercancel", onDockedUp);
          saveWindowsLayout();
        };

        window.addEventListener("pointermove", onDockedMove);
        window.addEventListener("pointerup", onDockedUp);
        window.addEventListener("pointercancel", onDockedUp);
        return;
      }

      const container = options.container || element.offsetParent || document.body;
      const containerRect = container.getBoundingClientRect();
      const elemRect = element.getBoundingClientRect();

      const startX = e.clientX;
      const startY = e.clientY;
      const startLeft = elemRect.left - containerRect.left;
      const startTop = elemRect.top - containerRect.top;
      const startWidth = elemRect.width;
      const startHeight = elemRect.height;

      // Anchor position so resizing from any edge keeps the opposite edge fixed
      element.style.position = "absolute";
      element.style.right = "auto";
      element.style.bottom = "auto";
      element.style.transform = "none";
      element.style.margin = "0";
      element.style.left = `${startLeft}px`;
      element.style.top = `${startTop}px`;

      const cWidth = container.clientWidth || window.innerWidth;
      const cHeight = container.clientHeight || window.innerHeight;
      const maxBottom = cHeight - bottomBarHeight;

      element.classList.add("is-resizing");
      document.body.classList.add("cyber-resizing-active");
      document.body.style.cursor = cursor;

      try {
        handle.setPointerCapture(e.pointerId);
      } catch (_) {}

      const onPointerMove = (ev) => {
        const dx = ev.clientX - startX;
        const dy = ev.clientY - startY;

        let newWidth = startWidth;
        let newHeight = startHeight;
        let newLeft = startLeft;
        let newTop = startTop;

        // Horizontal resizing
        if (dir.includes("e")) {
          newWidth = Math.max(minWidth, Math.min(startWidth + dx, cWidth - startLeft - 6));
        } else if (dir.includes("w")) {
          const rawW = startWidth - dx;
          newWidth = Math.max(minWidth, Math.min(rawW, startLeft + startWidth - 6));
          newLeft = startLeft + (startWidth - newWidth);
        }

        // Vertical resizing
        if (dir.includes("s")) {
          const maxH = Math.max(minHeight, maxBottom - startTop);
          newHeight = Math.max(minHeight, Math.min(startHeight + dy, maxH));
        } else if (dir.includes("n")) {
          const clampedTop = Math.max(topBarHeight, Math.min(startTop + dy, startTop + startHeight - minHeight));
          newHeight = (startTop + startHeight) - clampedTop;
          newTop = clampedTop;
        }

        element.style.setProperty("width", `${newWidth}px`, "important");
        element.style.setProperty("height", `${newHeight}px`, "important");
        if (dir.includes("w")) element.style.left = `${newLeft}px`;
        if (dir.includes("n")) element.style.top = `${newTop}px`;

        element.dataset.openWidth = `${newWidth}`;
        element.dataset.openHeight = `${newHeight}`;
        element.dataset.customFloatingWidth = `${newWidth}`;
        element.dataset.customFloatingHeight = `${newHeight}`;
      };

      const onPointerUp = (ev) => {
        try {
          handle.releasePointerCapture(ev.pointerId);
        } catch (_) {}
        element.classList.remove("is-resizing");
        document.body.classList.remove("cyber-resizing-active");
        document.body.style.cursor = "";
        element.dataset.justDragged = "true";
        setTimeout(() => { element.dataset.justDragged = "false"; }, 250);
        window.removeEventListener("pointermove", onPointerMove);
        window.removeEventListener("pointerup", onPointerUp);
        window.removeEventListener("pointercancel", onPointerUp);
        if (!isModal) {
          saveWindowsLayout();
          if (element.dataset.customFloatingWidth && element.id) {
            try {
              localStorage.setItem(`modcomparer_float_size_${element.id}`, JSON.stringify({
                width: element.dataset.customFloatingWidth,
                height: element.dataset.customFloatingHeight
              }));
            } catch (_) {}
          }
        }
      };

      window.addEventListener("pointermove", onPointerMove);
      window.addEventListener("pointerup", onPointerUp);
      window.addEventListener("pointercancel", onPointerUp);
    };

    handle.addEventListener("pointerdown", onPointerDown);
    element.appendChild(handle);
  });
}

// ==========================================================================
// PERSISTENT CYBER WINDOWS LAYOUT (Saves positions & dimensions in localStorage)
// ==========================================================================
const STORAGE_WINDOWS_LAYOUT_KEY = "modcomparer_cyber_windows_layout_v1";

// Everything the user arranges in Inicio (floating windows, what is docked in the edge panels and
// how, the welcome message, the clock) is kept in localStorage, which belongs to the page's
// origin: `tauri dev` and a compiled launcher don't share it, and it goes away with the WebView
// data. A copy lives in ika_root/home-layout.json: it is loaded into localStorage before the page
// initializes, and rewritten whenever one of these keys is saved.
const HOME_LAYOUT_KEYS = /^(modcomparer_cyber_windows_layout_v1|modcomparer_float_size_.+|ika_welcome_dock_pos|ika_pixel_clock_pos)$/;

let homeLayoutFileTimer = 0;
function saveHomeLayoutFile() {
  clearTimeout(homeLayoutFileTimer);
  homeLayoutFileTimer = setTimeout(() => {
    const data = {};
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (HOME_LAYOUT_KEYS.test(key)) data[key] = localStorage.getItem(key);
    }
    invoke("home_layout_save", { data: JSON.stringify(data) }).catch(() => {});
  }, 300);
}

const DEFAULT_HOME_LAYOUT = {
  "ika_pixel_clock_pos": "{\"left\":2104,\"top\":872}",
  "ika_welcome_dock_pos": "{\"left\":175,\"top\":310,\"dockedSide\":null,\"dockedIndex\":-1}",
  "modcomparer_float_size_home-console-preview-dock": "{\"width\":\"533\",\"height\":\"327\"}",
  "modcomparer_cyber_windows_layout_v1": "{\"home-console-preview-dock\":{\"left\":\"1935px\",\"top\":\"407px\",\"width\":\"533px\",\"height\":\"327px\",\"customFloatingWidth\":\"533\",\"customFloatingHeight\":\"327\",\"zIndex\":\"93\",\"isMinimized\":false,\"isDockedInPanel\":false,\"dockedSide\":null,\"dockedIndex\":-1,\"isDockedExpanded\":false,\"dockedFlex\":\"\",\"dockedHeight\":\"327px\"},\"home-novedades-dock\":{\"left\":\"12px\",\"top\":\"12px\",\"width\":\"395px\",\"height\":\"381px\",\"customFloatingWidth\":\"380\",\"customFloatingHeight\":\"669\",\"zIndex\":\"10\",\"isMinimized\":false,\"isDockedInPanel\":true,\"dockedSide\":\"right\",\"dockedIndex\":0,\"isDockedExpanded\":true,\"dockedFlex\":\"0 0 381px\",\"dockedHeight\":\"381px\"},\"home-coleccion-dock\":{\"left\":\"12px\",\"top\":\"398px\",\"width\":\"392px\",\"height\":\"468px\",\"customFloatingWidth\":\"500\",\"customFloatingHeight\":\"1146\",\"zIndex\":\"10\",\"isMinimized\":false,\"isDockedInPanel\":true,\"dockedSide\":\"left\",\"dockedIndex\":1,\"isDockedExpanded\":true,\"dockedFlex\":\"0 0 468px\",\"dockedHeight\":\"468px\"},\"home-accesos-dock\":{\"left\":\"165px\",\"top\":\"717px\",\"width\":\"275px\",\"height\":\"296px\",\"customFloatingWidth\":\"275\",\"customFloatingHeight\":\"296\",\"zIndex\":\"87\",\"isMinimized\":false,\"isDockedInPanel\":false,\"dockedSide\":null,\"dockedIndex\":-1,\"isDockedExpanded\":false,\"dockedFlex\":\"\",\"dockedHeight\":\"296px\"},\"home-actividad-dock\":{\"left\":\"12px\",\"top\":\"12px\",\"width\":\"392px\",\"height\":\"374px\",\"customFloatingWidth\":\"430\",\"customFloatingHeight\":\"404\",\"zIndex\":\"10\",\"isMinimized\":false,\"isDockedInPanel\":true,\"dockedSide\":\"left\",\"dockedIndex\":0,\"isDockedExpanded\":true,\"dockedFlex\":\"0 0 374px\",\"dockedHeight\":\"374px\"}}"
};

async function loadHomeLayoutFile() {
  const TIMED_OUT = {};
  let layoutData = null;
  try {
    const text = await Promise.race([
      invoke("home_layout_load"),
      new Promise((resolve) => setTimeout(() => resolve(TIMED_OUT), 1500)),
    ]);
    if (text && text !== TIMED_OUT) {
      layoutData = JSON.parse(text);
    }
  } catch (err) {
    console.warn("Could not load the Inicio layout file:", err);
  }

  // Si no hay layout guardado en disco ni en localStorage, aplicar la plantilla exacta por defecto
  const hasLocal = localStorage.getItem(STORAGE_WINDOWS_LAYOUT_KEY);
  const source = layoutData || (!hasLocal ? DEFAULT_HOME_LAYOUT : null);

  if (source) {
    for (const [key, value] of Object.entries(source)) {
      if (HOME_LAYOUT_KEYS.test(key) && typeof value === "string") {
        if (!localStorage.getItem(key) || layoutData) {
          localStorage.setItem(key, value);
        }
      }
    }
    if (!layoutData) {
      saveHomeLayoutFile();
    }
  }
}

// Docking and expanding save the layout themselves; while the saved layout is being applied that
// would overwrite it with a half-restored one (the last docked window lost its size every start).
let restoringWindowsLayout = false;

// Where the user left each floating window: id -> { left, top, shownLeft, shownTop } (px).
// When the launcher window is smaller than it was when the layout was saved, a window is pulled
// inside it (shown*) without forgetting where it belongs (left/top): that position comes back
// when the launcher window grows again, and it is what gets saved unless the user moved the window.
const cyberWindowHomes = new Map();

function clampCyberWindowPosition(left, top, width, height) {
  const topBarHeight = 60;
  const bottomBarHeight = 168;
  return {
    left: Math.max(10, Math.min(left, window.innerWidth - width - 10)),
    top: Math.max(topBarHeight, Math.min(top, window.innerHeight - height - bottomBarHeight)),
  };
}

function isCyberWindowAt(dock, home) {
  const isMin = dock.classList.contains("is-minimized");
  const left = parseFloat(isMin ? dock.dataset.openLeft : dock.style.left);
  const top = parseFloat(isMin ? dock.dataset.openTop : dock.style.top);
  return Math.abs(left - home.shownLeft) < 0.5 && Math.abs(top - home.shownTop) < 0.5;
}

// The launcher window changed size (e.g. maximized after starting small): every floating window
// goes back to where the user left it, as far as it fits now.
function refitCyberWindows() {
  cyberWindowHomes.forEach((home, id) => {
    const dock = document.getElementById(id);
    if (!dock || dock.classList.contains("is-docked-in-panel")) return;
    if (dock.classList.contains("is-dragging") || dock.classList.contains("is-holding-minimized") || dock.classList.contains("is-falling-physics")) return;
    if (!isCyberWindowAt(dock, home)) return; // moved since: it stays where it is
    const width = parseFloat(dock.dataset.openWidth) || dock.offsetWidth;
    const height = parseFloat(dock.dataset.openHeight) || dock.offsetHeight;
    const pos = clampCyberWindowPosition(home.left, home.top, width, height);
    home.shownLeft = pos.left;
    home.shownTop = pos.top;
    dock.dataset.openLeft = `${pos.left}`;
    dock.dataset.openTop = `${pos.top}`;
    if (!dock.classList.contains("is-minimized")) {
      dock.style.left = `${pos.left}px`;
      dock.style.top = `${pos.top}px`;
    }
  });
}

function saveWindowsLayout() {
  if (restoringWindowsLayout) return;
  const windowIds = [
    "home-console-preview-dock",
    "home-novedades-dock",
    "home-coleccion-dock",
    "home-accesos-dock",
    "home-actividad-dock"
  ];
  const layout = {};
  windowIds.forEach((id) => {
    const dock = document.getElementById(id);
    if (!dock) return;
    const isMin = dock.classList.contains("is-minimized");
    let left = isMin ? (dock.dataset.openLeft || dock.style.left) : (dock.style.left || dock.offsetLeft + "px");
    let top = isMin ? (dock.dataset.openTop || dock.style.top) : (dock.style.top || dock.offsetTop + "px");
    const width = isMin ? (dock.dataset.openWidth || dock.style.width) : (dock.style.width || dock.offsetWidth + "px");
    const height = isMin ? (dock.dataset.openHeight || dock.style.height) : (dock.style.height || dock.offsetHeight + "px");
    const zIndex = dock.style.zIndex || window.getComputedStyle(dock).zIndex;

    const isDocked = dock.classList.contains("is-docked-in-panel");
    const dockedSide = dock.dataset.dockedSide || null;
    const isDockedExpanded = dock.classList.contains("is-docked-expanded");
    // order inside its panel
    const dockedIndex = isDocked ? Array.from(dock.parentElement.children).indexOf(dock) : -1;

    if (!isDocked) {
      const home = cyberWindowHomes.get(id);
      if (home && isCyberWindowAt(dock, home)) {
        left = `${home.left}px`;
        top = `${home.top}px`;
      } else if (!isNaN(parseFloat(left)) && !isNaN(parseFloat(top))) {
        const cur = { left: parseFloat(left), top: parseFloat(top) };
        cyberWindowHomes.set(id, { left: cur.left, top: cur.top, shownLeft: cur.left, shownTop: cur.top });
      }
    }

    const customFW = dock.dataset.customFloatingWidth || (!isMin && !isDocked ? width : dock.dataset.openWidth);
    const customFH = dock.dataset.customFloatingHeight || (!isMin && !isDocked ? height : dock.dataset.openHeight);

    layout[id] = {
      left,
      top,
      width,
      height,
      customFloatingWidth: customFW,
      customFloatingHeight: customFH,
      zIndex: zIndex && zIndex !== "auto" ? zIndex : "20",
      isMinimized: isMin,
      sqLeft: dock.dataset.sqLeft,
      sqTop: dock.dataset.sqTop,
      isDockedInPanel: isDocked,
      dockedSide: dockedSide,
      dockedIndex: dockedIndex,
      isDockedExpanded: isDockedExpanded,
      dockedFlex: dock.dataset.dockedFlex || dock.style.flex || "",
      dockedHeight: dock.dataset.dockedHeight || dock.style.height || ""
    };
  });
  try {
    localStorage.setItem(STORAGE_WINDOWS_LAYOUT_KEY, JSON.stringify(layout));
  } catch (_) {}
  saveHomeLayoutFile();
}

function restoreWindowsLayout() {
  try {
    const raw = localStorage.getItem(STORAGE_WINDOWS_LAYOUT_KEY);
    if (!raw) return;
    const layout = JSON.parse(raw);
    restoringWindowsLayout = true;
    // docked windows go back into their panel in the order they had there
    const ids = Object.keys(layout).sort((a, b) => (layout[a]?.dockedIndex ?? 0) - (layout[b]?.dockedIndex ?? 0));

    ids.forEach((id) => {
      const dock = document.getElementById(id);
      const conf = layout[id];
      if (!dock || !conf) return;

      let l = parseFloat(conf.left);
      let t = parseFloat(conf.top);
      let w = parseFloat(conf.customFloatingWidth || conf.width);
      let h = parseFloat(conf.customFloatingHeight || conf.height);

      if (isNaN(w) || w < 220) w = dock.offsetWidth || 300;
      if (isNaN(h) || h < 150) h = dock.offsetHeight || 250;
      if (isNaN(l)) l = 28;
      if (isNaN(t)) t = 60;

      const home = { left: l, top: t };
      ({ left: l, top: t } = clampCyberWindowPosition(l, t, w, h));
      if (conf.isDockedInPanel && conf.dockedSide) cyberWindowHomes.delete(id);
      else cyberWindowHomes.set(id, { ...home, shownLeft: l, shownTop: t });

      dock.dataset.openLeft = `${l}`;
      dock.dataset.openTop = `${t}`;
      dock.dataset.openWidth = `${w}`;
      dock.dataset.openHeight = `${h}`;
      dock.dataset.customFloatingWidth = `${w}`;
      dock.dataset.customFloatingHeight = `${h}`;
      if (conf.sqLeft) dock.dataset.sqLeft = conf.sqLeft;
      if (conf.sqTop) dock.dataset.sqTop = conf.sqTop;

      dock.style.position = "absolute";
      dock.style.transform = "none";
      dock.style.margin = "0";
      dock.style.right = "auto";
      dock.style.bottom = "auto";

      if (conf.zIndex) {
        dock.style.setProperty("z-index", conf.zIndex, "important");
        const zNum = parseInt(conf.zIndex, 10);
        if (!isNaN(zNum) && zNum > highestCyberWindowZ) {
          highestCyberWindowZ = zNum;
        }
      }

      if (conf.isDockedInPanel && conf.dockedSide) {
        dockWindowIntoPanel(dock, conf.dockedSide);
        if (conf.isDockedExpanded) {
          expandDockedWindowInPanel(dock);
          if (conf.dockedFlex) {
            dock.dataset.dockedFlex = conf.dockedFlex;
            dock.style.setProperty("flex", conf.dockedFlex, "important");
          }
          if (conf.dockedHeight) {
            dock.dataset.dockedHeight = conf.dockedHeight;
            dock.style.setProperty("height", conf.dockedHeight, "important");
          }
        }
      } else if (conf.isMinimized) {
        dock.classList.add("is-minimized");
        dock.style.left = conf.sqLeft ? `${conf.sqLeft}px` : `${l}px`;
        dock.style.top = conf.sqTop ? `${conf.sqTop}px` : `${t}px`;
        dock.style.width = "48px";
        dock.style.height = "48px";
      } else {
        dock.classList.remove("is-minimized");
        dock.style.left = `${l}px`;
        dock.style.top = `${t}px`;
        dock.style.setProperty("width", `${w}px`, "important");
        dock.style.setProperty("height", `${h}px`, "important");
      }
    });
  } catch (_) {}
  restoringWindowsLayout = false;
  placeDockedWelcome?.();
}

let refitCyberWindowsFrame = 0;
window.addEventListener("resize", () => {
  cancelAnimationFrame(refitCyberWindowsFrame);
  refitCyberWindowsFrame = requestAnimationFrame(refitCyberWindows);
});

// ==========================================================================
// RAGDOLL BOUNCE PHYSICS & CURSOR HOLD FOR MINIMIZED CYBER WINDOWS
// ==========================================================================
function startHoldingAndBouncingCyberWindow(dock, minBtn, windowTitle, initialEvent) {
  if (!dock) return;

  bringCyberWindowToFront(dock);

  // 1. Capture current open geometry
  const container = dock.offsetParent || document.body;
  const cRect = container.getBoundingClientRect();
  const dRect = dock.getBoundingClientRect();

  const dockLeft = dRect.left - cRect.left;
  const dockTop = dRect.top - cRect.top;

  if (!dock.classList.contains("is-minimized")) {
    dock.dataset.openLeft = `${dockLeft}`;
    dock.dataset.openTop = `${dockTop}`;
    const targetW = dock.dataset.customFloatingWidth || (dRect.width > 120 ? dRect.width : (dock.dataset.openWidth || 510));
    const targetH = dock.dataset.customFloatingHeight || (dRect.height > 120 ? dRect.height : (dock.dataset.openHeight || 380));
    dock.dataset.openWidth = `${targetW}`;
    dock.dataset.openHeight = `${targetH}`;
  } else {
    if (!dock.dataset.openWidth || parseFloat(dock.dataset.openWidth) <= 100) {
      dock.dataset.openWidth = dock.dataset.customFloatingWidth || "510";
    }
    if (!dock.dataset.openHeight || parseFloat(dock.dataset.openHeight) <= 100) {
      dock.dataset.openHeight = dock.dataset.customFloatingHeight || "380";
    }
  }

  // 2. Minimize to 48x48 cube & attach to cursor
  dock.classList.add("is-minimized");
  dock.classList.add("is-holding-minimized");
  dock.style.position = "absolute";
  dock.style.right = "auto";
  dock.style.bottom = "auto";
  dock.style.margin = "0";
  dock.style.setProperty("width", "48px", "important");
  dock.style.setProperty("height", "48px", "important");
  dock.setAttribute("title", `${windowTitle} (arrastra o haz clic para abrir)`);

  const mouseX = initialEvent && typeof initialEvent.clientX === "number" ? initialEvent.clientX : (dRect.left + 24);
  const mouseY = initialEvent && typeof initialEvent.clientY === "number" ? initialEvent.clientY : (dRect.top + 24);

  // Center exactly under cursor inside container coordinates
  let curX = (mouseX - cRect.left) - 24;
  let curY = (mouseY - cRect.top) - 24;

  dock.style.left = `${curX}px`;
  dock.style.top = `${curY}px`;
    updateEdgePanelsDragOver(ev.clientX, ev.clientY);
    updateEdgePanelsDragOver(ev.clientX, ev.clientY);
  document.body.style.cursor = "grabbing";

  // Velocity tracking while moving cursor
  let lastX = mouseX;
  let lastY = mouseY;
  let lastTime = performance.now();
  let vx = 0;
  let vy = 0;

  const onPointerMove = (ev) => {
    const now = performance.now();
    const dt = Math.max(1, now - lastTime);
    vx = ((ev.clientX - lastX) / dt) * 16;
    vy = ((ev.clientY - lastY) / dt) * 16;
    lastX = ev.clientX;
    lastY = ev.clientY;
    lastTime = now;

    const currentCRect = (dock.offsetParent || document.body).getBoundingClientRect();
    curX = (ev.clientX - currentCRect.left) - 24;
    curY = (ev.clientY - currentCRect.top) - 24;
    dock.style.left = `${curX}px`;
    dock.style.top = `${curY}px`;
    updateEdgePanelsDragOver(ev.clientX, ev.clientY);
  };

  window.addEventListener("pointermove", onPointerMove);

  const releaseReadyAt = Date.now() + 100;

  const onRelease = (ev) => {
    if (Date.now() < releaseReadyAt) return;
    ev.preventDefault();
    ev.stopPropagation();

    window.removeEventListener("pointermove", onPointerMove);
    window.removeEventListener("pointerdown", onRelease, true);
    window.removeEventListener("click", onRelease, true);

    document.body.style.cursor = "";
    dock.classList.remove("is-holding-minimized");
    clearEdgePanelsDragOver();
    const dropSide = checkDropOnEdgePanel(ev.clientX, ev.clientY);
    if (dropSide) {
      dockWindowIntoPanel(dock, dropSide);
      return;
    }

    dock.dataset.justDragged = "true";
    setTimeout(() => { dock.dataset.justDragged = "false"; }, 350);

    let finalVx = Math.max(-8, Math.min(8, vx * 0.5));
    let finalVy = Math.max(-8, Math.min(8, vy * 0.5));

    // Dynamic initial spin impulse on release
    let initialRotSpeed = (Math.random() > 0.5 ? 1 : -1) * (10 + Math.random() * 8);
    if (Math.abs(finalVx) > 0.5) {
      initialRotSpeed += finalVx * 1.8;
    } else {
      finalVx = (Math.random() > 0.5 ? 1 : -1) * (1.8 + Math.random() * 1.8);
    }

    if (finalVy < 0) {
      finalVy = Math.max(-6, finalVy);
    } else {
      finalVy = Math.max(1.8, Math.min(5, finalVy));
    }

    launchBouncePhysics(dock, curX, curY, finalVx, finalVy, initialRotSpeed);
  };

  setTimeout(() => {
    window.addEventListener("pointerdown", onRelease, true);
    window.addEventListener("click", onRelease, true);
  }, 40);
}

function launchBouncePhysics(dock, startX, startY, initVx, initVy, initRotSpeed) {
  if (dock._physicsAnimId) {
    cancelAnimationFrame(dock._physicsAnimId);
    dock._physicsAnimId = null;
  }

  dock.classList.add("is-falling-physics");
  bringCyberWindowToFront(dock);

  let x = startX;
  let y = startY;
  let vx = initVx;
  let vy = initVy;

  // Strict decaying physics: each bounce loses significant energy
  const gravity = 0.42;
  const bounceRestitutionY = 0.56; // 44% energy loss on each vertical bounce
  const bounceRestitutionX = 0.48; // 52% energy loss on each horizontal bounce
  const groundFriction = 0.80;     // 20% loss per frame on surface contact
  const airDrag = 0.992;           // Air resistance
  const rotDamping = 0.95;         // Rotational decay

  let rotation = 0;
  let rotSpeed = typeof initRotSpeed === "number" ? initRotSpeed : (initVx * 2.0) + (Math.random() - 0.5) * 8;

  let settleTicks = 0;

  function step() {
    vy += gravity;
    vx *= airDrag;

    // Cap velocities
    vx = Math.max(-14, Math.min(14, vx));
    vy = Math.max(-14, Math.min(14, vy));

    x += vx;
    y += vy;
    rotation += rotSpeed;
    rotSpeed *= rotDamping;

    const container = dock.offsetParent || document.body;
    const cRect = container.getBoundingClientRect();
    const cWidth = container.clientWidth || window.innerWidth;
    const cHeight = container.clientHeight || window.innerHeight;

    const leftMin = 10;
    const rightMax = cWidth - 58;
    const topMin = 8;

    // 1. OBSTACLES: Open cyber windows, carousel cards, navigation buttons, category pills, details
    const obstacles = [];

    // A. Open cyber windows (except the minimized one)
    const openWindows = Array.from(document.querySelectorAll(".home-cyber-window:not(.is-minimized):not(.hidden)"))
      .filter((w) => w !== dock && w.offsetParent !== null);
    openWindows.forEach((w) => obstacles.push({ elem: w, isRound: false }));

    // B. Carousel Cards (.carousel-card-item)
    const carouselCards = Array.from(document.querySelectorAll(".carousel-card-item"));
    if (carouselCards.length > 0) {
      carouselCards.forEach((c) => {
        if (c.offsetParent !== null) obstacles.push({ elem: c, isRound: false });
      });
    } else {
      const track = document.getElementById("instance-carousel-track");
      if (track && track.offsetParent !== null) obstacles.push({ elem: track, isRound: false });
    }

    // C. Carousel Navigation Buttons (< and >) - ROUND BUTTONS (slip & roll off!)
    const navBtns = Array.from(document.querySelectorAll(".instance-nav-btn"));
    navBtns.forEach((btn) => {
      if (btn.offsetParent !== null) obstacles.push({ elem: btn, isRound: true });
    });

    // D. Only visible Category Pills bar and Search Box (NOT the full-width invisible wrapper!)
    const categoryPills = document.getElementById("instance-category-pills");
    if (categoryPills && categoryPills.offsetParent !== null) {
      obstacles.push({ elem: categoryPills, isRound: false });
    }
    const searchBox = document.getElementById("instance-search-box");
    if (searchBox && searchBox.offsetParent !== null) {
      obstacles.push({ elem: searchBox, isRound: false });
    }

    // E. Active Instance Details Box (below active card)
    const activeDetails = document.getElementById("instance-active-details");
    if (activeDetails && activeDetails.offsetParent !== null) {
      obstacles.push({ elem: activeDetails, isRound: false });
    }

    // Check collision against each obstacle
    obstacles.forEach((obs) => {
      const obsElem = obs.elem;
      const oRect = obsElem.getBoundingClientRect();
      if (oRect.width < 10 || oRect.height < 10) return;

      const obsLeft = oRect.left - cRect.left;
      const obsTop = oRect.top - cRect.top;
      const obsRight = oRect.right - cRect.left;
      const obsBottom = oRect.bottom - cRect.top;

      // Check AABB intersection with 48x48 cube
      if (x + 48 > obsLeft && x < obsRight && y + 48 > obsTop && y < obsBottom) {
        const penTop = (y + 48) - obsTop;
        const penBottom = obsBottom - y;
        const penLeft = (x + 48) - obsLeft;
        const penRight = obsRight - x;

        const minPen = Math.min(penTop, penBottom, penLeft, penRight);

        // If it's a round button (< and >), roll and tumble off naturally
        if (obs.isRound) {
          const obsCenterX = obsLeft + oRect.width / 2;
          const cubeCenterX = x + 24;
          const dir = cubeCenterX <= obsCenterX ? -1 : 1;

          y = obsTop - 46;
          vx = dir * Math.max(3.0, Math.abs(vx) * 0.8 + 2.2);
          vy = -Math.abs(vy) * 0.45;
          rotSpeed = dir * (10 + Math.random() * 6);
          settleTicks = 0; // Can never settle on a round button!
          return;
        }

        if (minPen === penTop && vy >= 0) {
          // Landed on top of obstacle (card, window, pill bar)
          y = obsTop - 48;
          vy = -Math.abs(vy) * bounceRestitutionY;
          vx *= groundFriction;
          rotSpeed = -rotSpeed * 0.4 + (vx * 1.2);

          const cubeCenterX = x + 24;
          // If balancing on the edge of the card/window, roll off!
          if (cubeCenterX < obsLeft + 16) {
            vx = -Math.max(2.6, Math.abs(vx) * 0.8 + 1.8);
            rotSpeed -= 8;
            settleTicks = 0;
          } else if (cubeCenterX > obsRight - 16) {
            vx = Math.max(2.6, Math.abs(vx) * 0.8 + 1.8);
            rotSpeed += 8;
            settleTicks = 0;
          } else {
            if (Math.abs(vy) < 0.8 && Math.abs(vx) < 0.6) {
              settleTicks++;
              rotation *= 0.82;
              rotSpeed *= 0.75;
            }
          }
        } else if (minPen === penBottom && vy <= 0) {
          // Bounced from underneath
          y = obsBottom;
          vy = Math.abs(vy) * bounceRestitutionY;
          rotSpeed = -rotSpeed * 0.4;
        } else if (minPen === penLeft && vx >= 0) {
          // Hit left side of obstacle: STRICTLY DECAYS HORIZONTAL MOMENTUM
          x = obsLeft - 48;
          vx = -Math.abs(vx) * bounceRestitutionX;
          rotSpeed = -rotSpeed * 0.4;
        } else if (minPen === penRight && vx <= 0) {
          // Hit right side of obstacle: STRICTLY DECAYS HORIZONTAL MOMENTUM
          x = obsRight;
          vx = Math.abs(vx) * bounceRestitutionX;
          rotSpeed = -rotSpeed * 0.4;
        }
      }
    });

    // 2. FLOOR: Circuit Hairline and Cyber Dock Boundary (media_1790457087184.png, media_1790458038697.png)
    const svgElem = document.querySelector(".cyber-dock-svg");
    let floorY = cHeight - 64;

    if (svgElem) {
      const svgRect = svgElem.getBoundingClientRect();
      const scale = svgRect.height / 148;
      const cubeScreenCenterX = x + cRect.left + 24;

      const leftNode = document.getElementById("hairline-left-node-core");
      const rightNode = document.getElementById("hairline-right-node-core");
      const playBtn = document.getElementById("btn-play-game");

      if (svgElem) {
        let leftDotX = svgRect.left - 20 * scale;
        let leftDotY = svgRect.top + 74 * scale;
        let rightDotX = svgRect.left + 1115 * scale;
        let rightDotY = svgRect.top + 74 * scale;

        if (leftNode && rightNode) {
          const leftNodeRect = leftNode.getBoundingClientRect();
          const rightNodeRect = rightNode.getBoundingClientRect();
          if (leftNodeRect.width > 0 || leftNodeRect.left > 0) {
            leftDotX = leftNodeRect.left + leftNodeRect.width / 2;
            leftDotY = leftNodeRect.top + leftNodeRect.height / 2;
          }
          if (rightNodeRect.width > 0 || rightNodeRect.left > 0) {
            rightDotX = rightNodeRect.left + rightNodeRect.width / 2;
            rightDotY = rightNodeRect.top + rightNodeRect.height / 2;
          }
        }

        // Visual telemetry from SVG:
        // Left slope is 42 units wide (dx=42), 36 units high (dy=36)
        const slopeDx = 42 * scale;
        const slopeDy = 36 * scale;

        const leftSlopeStartX = leftDotX - slopeDx;
        const leftUpperLineY = leftDotY - slopeDy;
        const leftLowerLineY = leftDotY;

        const rightSlopeEndX = rightDotX + slopeDx;
        const rightUpperLineY = rightDotY - slopeDy;
        const rightLowerLineY = rightDotY;

        let lineScreenY;

        if (cubeScreenCenterX <= leftSlopeStartX) {
          // Left upper horizontal line (Actividad, Accesos)
          lineScreenY = leftUpperLineY;
        } else if (cubeScreenCenterX < leftDotX) {
          // Left 45-degree slope down to glowing dot
          const t = (cubeScreenCenterX - leftSlopeStartX) / (leftDotX - leftSlopeStartX);
          lineScreenY = leftUpperLineY + t * slopeDy;
        } else if (cubeScreenCenterX <= rightDotX) {
          // Between left dot and right dot
          if (playBtn) {
            const pRect = playBtn.getBoundingClientRect();
            if (cubeScreenCenterX >= pRect.left && cubeScreenCenterX <= pRect.right) {
              lineScreenY = pRect.top + 6; // Center JUGAR button top rim
            } else {
              lineScreenY = leftLowerLineY; // Lower horizontal line (Instancias / Mi Colección)
            }
          } else {
            lineScreenY = leftLowerLineY;
          }
        } else if (cubeScreenCenterX < rightSlopeEndX) {
          // Right 45-degree slope up from glowing dot
          const t = (cubeScreenCenterX - rightDotX) / (rightSlopeEndX - rightDotX);
          lineScreenY = rightLowerLineY - t * slopeDy;
        } else {
          // Right upper horizontal line
          lineScreenY = rightUpperLineY;
        }

        // Place the 48x48 cube so its bottom rests precisely on top of the line
        floorY = (lineScreenY - cRect.top) - 48;
      } else {
        // Fallback using SVG bounding box if node elements are not found
        const upperLineScreenY = svgRect.top + 38 * scale;
        floorY = (upperLineScreenY - cRect.top) - 48;
      }
    }

    if (y >= floorY) {
      y = floorY;
      vy = -Math.abs(vy) * bounceRestitutionY;
      vx *= groundFriction;
      rotSpeed = -rotSpeed * 0.4 + (vx * 1.2);

      if (Math.abs(vy) < 0.8 && Math.abs(vx) < 0.6) {
        settleTicks++;
        rotation *= 0.82;
        rotSpeed *= 0.75;
      } else {
        settleTicks = 0;
      }
    }

    // 3. WALLS & CEILING: STRICTLY DECAYS
    if (x <= leftMin) {
      x = leftMin;
      vx = Math.abs(vx) * bounceRestitutionX;
      rotSpeed = -rotSpeed * 0.4;
    } else if (x >= rightMax) {
      x = rightMax;
      vx = -Math.abs(vx) * bounceRestitutionX;
      rotSpeed = -rotSpeed * 0.4;
    }

    if (y <= topMin) {
      y = topMin;
      vy = Math.abs(vy) * bounceRestitutionY;
      rotSpeed = -rotSpeed * 0.4;
    }

    // Cutoff tiny micro-velocities
    if (Math.abs(vx) < 0.15) vx = 0;
    if (Math.abs(vy) < 0.2) vy = 0;
    if (Math.abs(rotSpeed) < 0.15) rotSpeed = 0;

    dock.style.left = `${Math.round(x)}px`;
    dock.style.top = `${Math.round(y)}px`;
    dock.style.transform = `rotate(${rotation.toFixed(1)}deg)`;

    // Settle into rest once bounce energy has dissipated
    if (settleTicks > 8) {
      dock.classList.remove("is-falling-physics");
      dock.style.transform = "none";
      dock.style.left = `${Math.round(x)}px`;
      dock.style.top = `${Math.round(y)}px`;
      dock.dataset.sqLeft = `${Math.round(x)}`;
      dock.dataset.sqTop = `${Math.round(y)}`;
      dock._physicsAnimId = null;
      dock.dataset.justDragged = "true";
      setTimeout(() => { dock.dataset.justDragged = "false"; }, 300);
      saveWindowsLayout();
      return;
    }

    dock._physicsAnimId = requestAnimationFrame(step);
  }

  dock._physicsAnimId = requestAnimationFrame(step);
}

// ==========================================================================
// HOME CYBER WINDOWS MANAGER (Consola, Novedades, Mi Colección, Accesos, Actividad)
// ==========================================================================

function setupCyberWindow(dock, minBtn, closeBtn, windowTitle) {
  if (!dock) return;

  // Bring to front whenever clicked anywhere on window or its children
  dock.addEventListener("pointerdown", () => {
    if (dock._physicsAnimId) {
      cancelAnimationFrame(dock._physicsAnimId);
      dock._physicsAnimId = null;
      dock.classList.remove("is-falling-physics");
      dock.style.transform = "none";
    }
    bringCyberWindowToFront(dock);
  }, { capture: true });

  const header = dock.querySelector(".hcp-header");
  if (header) {
    makeDraggable(dock, header);
  }
  makeResizable(dock);

  // Minimize to 48x48 floating cyber square with cursor hold & bouncing physics!
  if (minBtn) {
    minBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      startHoldingAndBouncingCyberWindow(dock, minBtn, windowTitle, e);
    });
  }

  // Restore on clicking minimized square
  dock.addEventListener("click", (e) => {
    if (!dock.classList.contains("is-minimized")) return;
    if (dock.dataset.justDragged === "true") {
      dock.dataset.justDragged = "false";
      return;
    }
    restoreCyberWindow(dock);
  });
}

function restoreCyberWindow(dock) {
  if (!dock) return;
  bringCyberWindowToFront(dock);

  const currentLeft = parseFloat(dock.style.left) || 0;
  const currentTop = parseFloat(dock.style.top) || 0;
  const originalSqLeft = parseFloat(dock.dataset.sqLeft);
  const originalSqTop = parseFloat(dock.dataset.sqTop);

  let savedW = dock.dataset.customFloatingWidth || dock.dataset.openWidth;
  let savedH = dock.dataset.customFloatingHeight || dock.dataset.openHeight;

  if (!savedW || parseFloat(savedW) <= 100) {
    try {
      const stored = JSON.parse(localStorage.getItem(`modcomparer_float_size_${dock.id}`) || "{}");
      if (stored.width) savedW = stored.width;
      if (stored.height) savedH = stored.height;
    } catch (_) {}
  }

  const openWidth = Math.max(220, parseFloat(savedW) || 510);
  const openHeight = Math.max(160, parseFloat(savedH) || 380);

  const cWidth = window.innerWidth;
  const cHeight = window.innerHeight;
  const topBarHeight = 60;
  const bottomBarHeight = 168;

  let targetLeft, targetTop;
  if (!isNaN(originalSqLeft) && Math.abs(currentLeft - originalSqLeft) < 5 &&
      !isNaN(originalSqTop) && Math.abs(currentTop - originalSqTop) < 5) {
    targetLeft = parseFloat(dock.dataset.openLeft);
    targetTop = parseFloat(dock.dataset.openTop);
  } else {
    targetLeft = currentLeft + 24 - (openWidth - 40);
    targetTop = currentTop - 10;
  }

  if (isNaN(targetLeft)) targetLeft = currentLeft;
  if (isNaN(targetTop)) targetTop = currentTop;

  targetLeft = Math.max(16, Math.min(targetLeft, cWidth - openWidth - 16));
  targetTop = Math.max(topBarHeight, Math.min(targetTop, cHeight - openHeight - bottomBarHeight));

  dock.classList.remove("is-minimized");
  dock.classList.remove("hidden");
  dock.classList.remove("no-minimize-btn");
  delete dock.dataset.noMinimize;
  const colBtn = dock.querySelector(".hw-btn-collapse");
  if (colBtn) {
    colBtn.remove();
  }
  dock.removeAttribute("title");
  dock.style.left = `${targetLeft}px`;
  dock.style.top = `${targetTop}px`;
  dock.style.setProperty("width", `${openWidth}px`, "important");
  dock.style.setProperty("height", `${openHeight}px`, "important");
  dock.dataset.openWidth = `${openWidth}`;
  dock.dataset.openHeight = `${openHeight}`;
  dock.dataset.customFloatingWidth = `${openWidth}`;
  dock.dataset.customFloatingHeight = `${openHeight}`;
  dock.style.right = "auto";
  dock.style.bottom = "auto";
  saveWindowsLayout();
}

const coleccionFilterState = {
  tab: "all",      // "all", "instances", "modpacks", "favorites"
  version: "all",  // "all" or specific version string like "1.20.1"
  loader: "all",   // "all", "forge", "neoforge", "fabric", "quilt", "vanilla"
  java: "all",     // "all", "adoptium", "mojang", "zulu", etc.
  search: "",
  sidebarCollapsed: true
};

function isColeccionInstanceModpack(inst) {
  const count = typeof inst.mod_count === "number" ? inst.mod_count : 0;
  const n = (inst.name || "").toLowerCase();
  const f = (inst.folder_name || "").toLowerCase();
  return count >= 15 || n.includes("pack") || n.includes("modpack") || n.includes("all the mods") || n.includes("better") || f.includes("pack");
}

function populateColeccionFilterOptions() {
  const selectVer = document.getElementById("coleccion-filter-version");
  if (!selectVer) return;
  const all = homeInstancesAll && homeInstancesAll.length > 0 ? homeInstancesAll : (homeInstancesList || []);
  const versions = Array.from(new Set(all.map((it) => it.mc_version).filter(Boolean))).sort((a, b) => {
    return b.localeCompare(a, undefined, { numeric: true, sensitivity: "base" });
  });

  const curr = coleccionFilterState.version;
  selectVer.innerHTML = `<option value="all">Todas</option>`;
  versions.forEach((ver) => {
    const opt = document.createElement("option");
    opt.value = ver;
    opt.textContent = ver;
    if (ver === curr) opt.selected = true;
    selectVer.appendChild(opt);
  });
}

function setupMiColeccionFilters() {
  // 1. Subnav Text Tabs: Todas | Instancias | Modpacks | Favoritos |
  const tabsContainer = document.getElementById("coleccion-tabs-row");
  if (tabsContainer) {
    tabsContainer.querySelectorAll(".coleccion-text-tab").forEach((tabBtn) => {
      tabBtn.onclick = (e) => {
        e.preventDefault();
        const tab = tabBtn.dataset.tab || "all";
        coleccionFilterState.tab = tab;
        tabsContainer.querySelectorAll(".coleccion-text-tab").forEach((b) => {
          b.classList.toggle("active", b === tabBtn);
        });
        renderMiColeccionGrid();
      };
    });
  }

  // 2. Horizontal Filters Toggle (Icon to the left of Todas)
  const hFilters = document.getElementById("coleccion-horizontal-filters");
  const toggleBtn = document.getElementById("btn-toggle-coleccion-filters");
  if (hFilters && toggleBtn) {
    const saved = localStorage.getItem("modcomparer_coleccion_hfilters_collapsed");
    const isCollapsed = saved !== "0"; // default collapsed
    coleccionFilterState.sidebarCollapsed = isCollapsed;
    hFilters.classList.toggle("is-collapsed", isCollapsed);
    toggleBtn.classList.toggle("is-open", !isCollapsed);

    toggleBtn.onclick = (e) => {
      e.stopPropagation();
      hFilters.classList.toggle("is-collapsed");
      const nowCollapsed = hFilters.classList.contains("is-collapsed");
      coleccionFilterState.sidebarCollapsed = nowCollapsed;
      toggleBtn.classList.toggle("is-open", !nowCollapsed);
      try {
        localStorage.setItem("modcomparer_coleccion_hfilters_collapsed", nowCollapsed ? "1" : "0");
      } catch (_) {}
    };
  }

  // 3. Dropdowns
  const selectVer = document.getElementById("coleccion-filter-version");
  if (selectVer) {
    selectVer.onchange = () => {
      coleccionFilterState.version = selectVer.value;
      renderMiColeccionGrid();
    };
  }

  const selectLoader = document.getElementById("coleccion-filter-loader");
  if (selectLoader) {
    selectLoader.onchange = () => {
      coleccionFilterState.loader = selectLoader.value;
      renderMiColeccionGrid();
    };
  }

  const selectJava = document.getElementById("coleccion-filter-java");
  if (selectJava) {
    selectJava.onchange = () => {
      coleccionFilterState.java = selectJava.value;
      renderMiColeccionGrid();
    };
  }

  // 3.5. Search by Name Toggle & Input
  const searchDropdown = document.getElementById("coleccion-search-dropdown");
  const btnToggleSearch = document.getElementById("btn-toggle-coleccion-search");
  const searchInput = document.getElementById("coleccion-search-input");
  const searchClear = document.getElementById("coleccion-search-clear");

  if (searchDropdown && btnToggleSearch) {
    btnToggleSearch.onclick = (e) => {
      e.stopPropagation();
      searchDropdown.classList.toggle("is-collapsed");
      const isCollapsed = searchDropdown.classList.contains("is-collapsed");
      btnToggleSearch.classList.toggle("is-open", !isCollapsed);
      if (!isCollapsed && searchInput) {
        setTimeout(() => searchInput.focus(), 60);
      }
    };
  }

  if (searchInput) {
    searchInput.oninput = () => {
      coleccionFilterState.search = searchInput.value;
      if (searchClear) {
        searchClear.classList.toggle("hidden", !searchInput.value);
      }
      if (btnToggleSearch) {
        btnToggleSearch.classList.toggle("has-search", !!searchInput.value.trim());
      }
      renderMiColeccionGrid();
    };
  }

  if (searchClear) {
    searchClear.onclick = (e) => {
      e.stopPropagation();
      if (searchInput) searchInput.value = "";
      coleccionFilterState.search = "";
      searchClear.classList.add("hidden");
      if (btnToggleSearch) btnToggleSearch.classList.remove("has-search");
      renderMiColeccionGrid();
      if (searchInput) searchInput.focus();
    };
  }

  // 4. Reset Filters Button
  const btnReset = document.getElementById("coleccion-filter-reset");
  if (btnReset) {
    btnReset.onclick = () => {
      coleccionFilterState.version = "all";
      coleccionFilterState.loader = "all";
      coleccionFilterState.java = "all";
      coleccionFilterState.search = "";
      if (searchInput) searchInput.value = "";
      if (searchClear) searchClear.classList.add("hidden");
      if (btnToggleSearch) btnToggleSearch.classList.remove("has-search");
      if (selectVer) selectVer.value = "all";
      if (selectLoader) selectLoader.value = "all";
      if (selectJava) selectJava.value = "all";
      renderMiColeccionGrid();
    };
  }
}

function updateColeccionSelectedFooter(inst) {
  const nameEl = document.getElementById("coleccion-selected-name");
  const pathEl = document.getElementById("coleccion-selected-path-val");
  const cardEl = document.getElementById("coleccion-selected-card");
  if (!nameEl || !pathEl) return;

  if (!inst) {
    nameEl.textContent = "Ninguna seleccionada";
    pathEl.textContent = "Ruta no disponible";
    if (cardEl) {
      cardEl.title = "No hay instancia seleccionada";
      cardEl.dataset.instPath = "";
      cardEl.dataset.instName = "";
    }
    return;
  }

  const customNames = getCustomInstanceNamesMap();
  const rawCustom = customNames[inst.path];
  const displayName = rawCustom ? rawCustom.toUpperCase() : formatInstanceDisplayName(inst.name);

  nameEl.textContent = displayName;

  const rawPath = inst.path || "";
  const rootPath = rawPath.replace(/[/\\]mods[/\\]?$/i, "");
  pathEl.textContent = rootPath || rawPath || "Ruta no disponible";

  if (cardEl) {
    cardEl.title = `${displayName}\n${rootPath}\n(Click derecho para abrir en el explorador)`;
    cardEl.dataset.instPath = rootPath;
    cardEl.dataset.instName = displayName;
  }
}

// Opens the edit window for the instance shown on the home screen.
function openEditActiveInstance() {
  const inst = (homeInstancesList && homeInstancesList[homeCurrentInstanceIndex]) || (homeInstancesAll && homeInstancesAll[0]);
  if (!inst || !inst.path) {
    showToast("Selecciona una instancia primero");
    return;
  }
  window.ikaOpenEditInstance?.(inst.path);
}

function openColeccionContextMenu(x, y, path, name) {
  const menu = document.getElementById("coleccion-context-menu");
  if (!menu) return;

  const targetPath = path || (homeInstancesList[homeCurrentInstanceIndex] ? homeInstancesList[homeCurrentInstanceIndex].path : "");
  const targetFolder = targetPath ? targetPath.replace(/[/\\]mods[/\\]?$/i, "") : "";
  const targetName = name || (homeInstancesList[homeCurrentInstanceIndex] ? homeInstancesList[homeCurrentInstanceIndex].name : "Instancia");

  const titleEl = document.getElementById("ctx-coleccion-title");
  const pathPrevEl = document.getElementById("ctx-coleccion-path-preview");
  if (titleEl) titleEl.textContent = targetName;
  if (pathPrevEl) pathPrevEl.textContent = targetFolder || "Ruta no disponible";

  menu.dataset.targetPath = targetFolder;
  menu.classList.remove("hidden");

  // Adjust for viewport boundaries
  const rect = menu.getBoundingClientRect();
  const winWidth = window.innerWidth;
  const winHeight = window.innerHeight;

  let left = x;
  let top = y;

  if (left + rect.width > winWidth - 10) {
    left = Math.max(10, x - rect.width);
  }
  if (top + rect.height > winHeight - 10) {
    top = Math.max(10, winHeight - rect.height - 10);
  }

  menu.style.left = `${left}px`;
  menu.style.top = `${top}px`;
}

function closeColeccionContextMenu() {
  const menu = document.getElementById("coleccion-context-menu");
  if (menu && !menu.classList.contains("hidden")) {
    menu.classList.add("hidden");
  }
}

function renderMiColeccionGrid() {
  const grid = document.getElementById("coleccion-grid-5x4");
  if (!grid) return;

  populateColeccionFilterOptions();

  const allInstances = homeInstancesAll && homeInstancesAll.length > 0 
    ? homeInstancesAll 
    : (homeInstancesList || []);

  const total = allInstances.length;

  const instances = allInstances.filter((inst) => {
    // 1. Subnav Tab filter
    if (coleccionFilterState.tab === "instances") {
      if (isColeccionInstanceModpack(inst)) return false;
    } else if (coleccionFilterState.tab === "modpacks") {
      if (!isColeccionInstanceModpack(inst)) return false;
    } else if (coleccionFilterState.tab === "favorites") {
      if (!favoriteInstances.has(inst.path)) return false;
    }

    // 2. Version filter
    if (coleccionFilterState.version !== "all") {
      const v = (inst.mc_version || "").toLowerCase();
      if (v !== coleccionFilterState.version.toLowerCase()) return false;
    }

    // 3. Loader filter
    if (coleccionFilterState.loader !== "all") {
      const l = (inst.loader || "").toLowerCase();
      if (coleccionFilterState.loader === "forge") {
        if (!l.includes("forge") || l.includes("neoforge")) return false;
      } else {
        if (!l.includes(coleccionFilterState.loader)) return false;
      }
    }

    // 4. Java filter
    if (coleccionFilterState.java !== "all") {
      const jDist = detectJavaDistribution(inst);
      if (jDist.key !== coleccionFilterState.java) return false;
    }

    // 5. Search by name filter
    if (coleccionFilterState.search && coleccionFilterState.search.trim()) {
      const q = coleccionFilterState.search.trim().toLowerCase();
      const customNames = getCustomInstanceNamesMap();
      const rawCustom = (customNames[inst.path] || "").toLowerCase();
      const formatted = (formatInstanceDisplayName(inst.name) || "").toLowerCase();
      const rawName = (inst.name || "").toLowerCase();
      if (!rawCustom.includes(q) && !formatted.includes(q) && !rawName.includes(q)) {
        return false;
      }
    }

    return true;
  });

  const headerBadge = document.getElementById("coleccion-counter-badge");
  if (headerBadge) {
    if (instances.length === total) {
      headerBadge.textContent = `${total} Instancia${total === 1 ? "" : "s"}`;
    } else {
      headerBadge.textContent = `${instances.length} / ${total}`;
    }
  }

  const hasSecondaryFilters = coleccionFilterState.version !== "all" ||
                               coleccionFilterState.loader !== "all" ||
                               coleccionFilterState.java !== "all" ||
                               Boolean(coleccionFilterState.search && coleccionFilterState.search.trim());

  const btnReset = document.getElementById("coleccion-filter-reset");
  if (btnReset) btnReset.classList.toggle("hidden", !hasSecondaryFilters);

  const toggleBtn = document.getElementById("btn-toggle-coleccion-filters");
  if (toggleBtn) toggleBtn.classList.toggle("has-filters", hasSecondaryFilters);

  const emptyState = document.getElementById("coleccion-empty-state");
  if (emptyState) emptyState.classList.toggle("hidden", instances.length > 0);

  grid.innerHTML = "";

  const activeInst = (homeInstancesList && homeInstancesList[homeCurrentInstanceIndex]) || allInstances[0];
  const activePath = activeInst ? activeInst.path : "";
  updateColeccionSelectedFooter(activeInst);

  instances.forEach((inst) => {
    const slot = document.createElement("div");
    slot.className = "coleccion-slot";

    const customNames = getCustomInstanceNamesMap();
    const rawCustom = customNames[inst.path];
    const displayName = rawCustom ? rawCustom.toUpperCase() : formatInstanceDisplayName(inst.name);
    const mcVer = inst.mc_version || "1.20.1";
    const loader = (inst.loader || "Forge").trim();
    const loaderClass = `loader-${loader.toLowerCase().replace(/[^a-z0-9]/g, "")}`;

    const isActive = inst.path === activePath;
    if (isActive) {
      slot.classList.add("is-active");
      const svgNS = "http://www.w3.org/2000/svg";
      const svg = document.createElementNS(svgNS, "svg");
      svg.setAttribute("class", "coleccion-slot-border-svg");
      svg.setAttribute("viewBox", "0 0 100 100");
      svg.setAttribute("preserveAspectRatio", "none");
      svg.setAttribute("fill", "none");
      svg.setAttribute("aria-hidden", "true");
      svg.innerHTML = `
        <rect x="1.5" y="1.5" width="97" height="97" rx="0" ry="0"
              fill="none"
              stroke="url(#coleccionGodStrokeGrad)"
              stroke-width="3"
              vector-effect="non-scaling-stroke" />
      `;
      slot.appendChild(svg);
    }

    const uniqueBlockFace = getUniqueBlockFaceForInstance(inst.path, inst.name);

    // Only the instance icon or authentic Minecraft block texture (No hover overlay)
    const img = document.createElement("img");
    img.className = "coleccion-slot-img";
    img.alt = displayName;
    img.loading = "eager";

    const customIcons = getCustomInstanceIconsMap();
    const customIcon = customIcons[inst.path] || customIcons[inst.folder_name] || customIcons[inst.name];

    if (customIcon) {
      img.src = customIcon;
    } else if (inst.icon_path) {
      img.src = convertFileSrc(inst.icon_path);
      img.onerror = () => {
        img.src = uniqueBlockFace;
        img.classList.add("is-block-face");
      };
    } else {
      img.src = uniqueBlockFace;
      img.classList.add("is-block-face");
    }
    slot.appendChild(img);

    slot.addEventListener("click", () => {
      const idx = homeInstancesList.findIndex((it) => it.path === inst.path);
      if (idx !== -1) {
        homeCurrentInstanceIndex = idx;
        applyActiveHomeInstance(idx);
        renderHomeInstanceCarousel();
      } else {
        const allIdx = homeInstancesAll.findIndex((it) => it.path === inst.path);
        if (allIdx !== -1) {
          homeInstancesList = [...homeInstancesAll];
          homeCurrentInstanceIndex = allIdx;
          applyActiveHomeInstance(allIdx);
          renderHomeInstanceCarousel();
        }
      }
      renderMiColeccionGrid();
    });

    slot.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      e.stopPropagation();
      const idx = homeInstancesList.findIndex((it) => it.path === inst.path);
      if (idx !== -1) {
        homeCurrentInstanceIndex = idx;
        applyActiveHomeInstance(idx);
        renderHomeInstanceCarousel();
      } else {
        const allIdx = homeInstancesAll.findIndex((it) => it.path === inst.path);
        if (allIdx !== -1) {
          homeInstancesList = [...homeInstancesAll];
          homeCurrentInstanceIndex = allIdx;
          applyActiveHomeInstance(allIdx);
          renderHomeInstanceCarousel();
        }
      }
      renderMiColeccionGrid();
      openColeccionContextMenu(e.clientX, e.clientY, inst.path, displayName);
    });

    grid.appendChild(slot);
  });

  // Always at least one "+ Crear" slot at the end
  const addSlot = document.createElement("div");
  addSlot.className = "coleccion-slot-add";
  addSlot.title = "Crear nueva instancia";
  addSlot.innerHTML = `
    <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
      <line x1="12" y1="5" x2="12" y2="19"></line>
      <line x1="5" y1="12" x2="19" y2="12"></line>
    </svg>
    <span>Crear</span>
  `;
  addSlot.addEventListener("click", () => {
    const btnCreate = document.getElementById("btn-create-instance-pill");
    if (btnCreate) btnCreate.click();
  });
  grid.appendChild(addSlot);
}

