const DEFAULT_PATH_2 = "C:\\Users\\Aly\\AppData\\Roaming\\ElyPrismLauncher\\instances\\Keo optimized 1.21.1 neoforge\\minecraft\\mods";

// ==========================================
// User Management System
// ==========================================
const STORAGE_USERS_KEY = "modcomparer_users";
const STORAGE_ACTIVE_USER_KEY = "modcomparer_active_user";

function loadUsersFromStorage() {
  try {
    const raw = localStorage.getItem(STORAGE_USERS_KEY);
    state.users = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(state.users)) state.users = [];
    const active = localStorage.getItem(STORAGE_ACTIVE_USER_KEY);
    if (active && state.users.some((u) => u.username.toLowerCase() === active.toLowerCase())) {
      state.activeUser = state.users.find((u) => u.username.toLowerCase() === active.toLowerCase());
    } else {
      state.activeUser = null;
    }
  } catch (err) {
    console.error("Error loading users from localStorage:", err);
    state.users = [];
    state.activeUser = null;
  }
}

function saveUsersToStorage() {
  try {
    localStorage.setItem(STORAGE_USERS_KEY, JSON.stringify(state.users));
    if (state.activeUser) {
      localStorage.setItem(STORAGE_ACTIVE_USER_KEY, state.activeUser.username);
    } else {
      localStorage.removeItem(STORAGE_ACTIVE_USER_KEY);
    }
  } catch (err) {
    console.error("Error saving users to localStorage:", err);
  }
}

// ==========================================
// Draggable Welcome Greeting Dock (Doble Clic para Activar)
// ==========================================
// Set by initDraggableWelcomeDock: puts the welcome message back in its edge panel, at its place
// among the windows docked there (called again once those are back, see restoreWindowsLayout).
let placeDockedWelcome = null;

// The welcome message can be dragged anywhere in Inicio and, like the windows, dropped on an edge
// panel: there it is one more card of the panel's column (the docked windows can be reordered
// around it, they only look at .is-docked-in-panel) until it is dragged out again.
function initDraggableWelcomeDock() {
  const dock = document.getElementById("home-welcome-dock");
  if (!dock) return;
  const STORAGE_KEY = "ika_welcome_dock_pos";

  // its place in the stage, to come back to when it leaves a panel
  const stageSlot = document.createComment("home-welcome-dock");
  dock.after(stageSlot);

  const zoneOf = (side) => document.getElementById(side === "right" ? "edge-dock-zone-right" : "edge-dock-zone-left");
  const dockedSide = () => (dock.classList.contains("is-docked-in-panel") ? dock.dataset.dockedSide : null);
  const readSaved = () => {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}") || {};
    } catch (err) {
      console.warn("Could not restore welcome dock position:", err);
      return {};
    }
  };

  // last position as a floating block (kept while it is docked)
  let floatPos = null;

  function save() {
    const side = dockedSide();
    const state = {
      ...(floatPos || {}),
      dockedSide: side,
      dockedIndex: side ? Array.from(dock.parentElement.children).indexOf(dock) : -1,
    };
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (_) {}
    saveHomeLayoutFile();
  }

  function dockIntoPanel(side, before = null) {
    const zone = zoneOf(side);
    if (!zone) return;
    dock.classList.add("is-docked-in-panel");
    dock.dataset.dockedSide = side;
    dock.style.left = "";
    dock.style.top = "";
    dock.style.right = "";
    zone.insertBefore(dock, before);
  }

  function undock() {
    dock.classList.remove("is-docked-in-panel");
    delete dock.dataset.dockedSide;
    stageSlot.before(dock);
  }

  // The card the pointer is above, among the others in the panel (null = after the last one).
  const cardBelowPointer = (zone, clientY) =>
    Array.from(zone.children)
      .filter((c) => c !== dock)
      .find((c) => {
        const r = c.getBoundingClientRect();
        return clientY < r.top + r.height / 2;
      }) || null;

  const saved = readSaved();
  if (typeof saved.left === "number" && typeof saved.top === "number") {
    floatPos = { left: saved.left, top: saved.top };
    dock.style.left = `${floatPos.left}px`;
    dock.style.top = `${floatPos.top}px`;
    dock.style.right = "auto";
  }
  placeDockedWelcome = () => {
    const state = readSaved();
    const zone = state.dockedSide ? zoneOf(state.dockedSide) : null;
    if (!zone) return;
    const others = Array.from(zone.children).filter((c) => c !== dock);
    dockIntoPanel(state.dockedSide, others[state.dockedIndex] || null);
  };
  placeDockedWelcome();

  dock.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    if (e.target.closest("button, a, input, select, textarea")) return;

    const startX = e.clientX;
    const startY = e.clientY;
    let moved = false;
    // where inside the block the pointer holds it while it floats
    let grabX = 0;
    let grabY = 0;
    if (!dockedSide()) {
      const rect = dock.getBoundingClientRect();
      grabX = e.clientX - rect.left;
      grabY = e.clientY - rect.top;
    }
    dock.classList.add("is-dragging");

    const onPointerMove = (ev) => {
      if (!moved && Math.abs(ev.clientX - startX) <= 3 && Math.abs(ev.clientY - startY) <= 3) return;
      moved = true;

      if (dockedSide()) {
        const panelRect = dock.closest(".home-edge-panel").getBoundingClientRect();
        const pulledOut = dockedSide() === "left" ? ev.clientX > panelRect.right + 30 : ev.clientX < panelRect.left - 30;
        if (!pulledOut) {
          // reorder inside the panel
          const zone = dock.parentElement;
          const next = cardBelowPointer(zone, ev.clientY);
          if (dock.nextElementSibling !== next) zone.insertBefore(dock, next);
          return;
        }
        undock();
        grabX = 36;
        grabY = 24;
      }

      const parentRect = dock.offsetParent ? dock.offsetParent.getBoundingClientRect() : { left: 0, top: 0 };
      const style = getComputedStyle(dock);
      let newLeft = Math.round(ev.clientX - grabX - parentRect.left - parseFloat(style.marginLeft));
      let newTop = Math.round(ev.clientY - grabY - parentRect.top - parseFloat(style.marginTop));

      // Keep comfortably inside viewport
      const maxLeft = Math.max(10, window.innerWidth - dock.offsetWidth - 20);
      const maxTop = Math.max(56, window.innerHeight - dock.offsetHeight - 140);
      newLeft = Math.max(10, Math.min(newLeft, maxLeft));
      newTop = Math.max(56, Math.min(newTop, maxTop));

      dock.style.left = `${newLeft}px`;
      dock.style.top = `${newTop}px`;
      dock.style.right = "auto";
      updateEdgePanelsDragOver(ev.clientX, ev.clientY);
    };

    const onPointerUp = (ev) => {
      window.removeEventListener("pointermove", onPointerMove);
      window.removeEventListener("pointerup", onPointerUp);
      window.removeEventListener("pointercancel", onPointerUp);
      dock.classList.remove("is-dragging");
      clearEdgePanelsDragOver();
      if (!moved) return;

      if (!dockedSide()) {
        const dropSide = ev.type === "pointerup" ? checkDropOnEdgePanel(ev.clientX, ev.clientY) : null;
        if (dropSide) {
          dockIntoPanel(dropSide, cardBelowPointer(zoneOf(dropSide), ev.clientY));
          document.getElementById(`home-edge-panel-${dropSide}`)?.classList.add("is-visible");
        } else {
          const curLeft = parseInt(dock.style.left, 10);
          const curTop = parseInt(dock.style.top, 10);
          if (!isNaN(curLeft) && !isNaN(curTop)) floatPos = { left: curLeft, top: curTop };
        }
      }
      save();
      // the windows docked in that panel may have a new place in it
      saveWindowsLayout();
    };

    // On the window, not with pointer capture: moving the block between the stage and a panel
    // (or inside the panel) releases a capture.
    window.addEventListener("pointermove", onPointerMove);
    window.addEventListener("pointerup", onPointerUp);
    window.addEventListener("pointercancel", onPointerUp);
  });
}

// ==========================================
// Floating Pixel Art HUD Clock (Reloj Flotante Retro Pixel)
// ==========================================
function initFloatingPixelClock() {
  const clock = document.getElementById("home-pixel-clock");
  const timeEl = document.getElementById("pixel-clock-time");
  const secEl = document.getElementById("pixel-clock-seconds");
  const ampmEl = document.getElementById("pixel-clock-ampm");
  const dateEl = document.getElementById("pixel-clock-date");
  const modeBtn = document.getElementById("pixel-clock-mode-btn");
  if (!clock || !timeEl) return;

  // Restore saved position
  try {
    const savedPos = localStorage.getItem("ika_pixel_clock_pos");
    if (savedPos) {
      const pos = JSON.parse(savedPos);
      if (typeof pos.left === "number" && typeof pos.top === "number") {
        clock.style.left = `${pos.left}px`;
        clock.style.top = `${pos.top}px`;
        clock.style.right = "auto";
      }
    }
  } catch (err) {
    console.warn("Could not restore pixel clock position:", err);
  }

  let use24h = localStorage.getItem("ika_clock_24h") === "true";

  function updateClock() {
    const now = new Date();
    let hours = now.getHours();
    const minutes = String(now.getMinutes()).padStart(2, "0");
    const seconds = String(now.getSeconds()).padStart(2, "0");
    let ampm = "";

    if (!use24h) {
      ampm = hours >= 12 ? "PM" : "AM";
      hours = hours % 12 || 12;
    }
    const hoursStr = String(hours).padStart(2, "0");

    // Colon blink: dim for the first half second, like the old step-start animation,
    // but only 2 repaints per second instead of one per monitor frame.
    timeEl.innerHTML = `${hoursStr}<span class="pixel-clock-colon is-dim">:</span>${minutes}`;
    setTimeout(() => {
      const colon = timeEl.querySelector(".pixel-clock-colon");
      if (colon) colon.classList.remove("is-dim");
    }, 500);
    if (secEl) secEl.textContent = seconds;
    if (ampmEl) {
      ampmEl.textContent = ampm;
      ampmEl.style.display = use24h ? "none" : "inline-block";
    }

    if (dateEl) {
      const days = ["DOM", "LUN", "MAR", "MIÉ", "JUE", "VIE", "SÁB"];
      const months = ["ENE", "FEB", "MAR", "ABR", "MAY", "JUN", "JUL", "AGO", "SEP", "OCT", "NOV", "DIC"];
      const dayName = days[now.getDay()];
      const dayNum = now.getDate();
      const monthName = months[now.getMonth()];
      const year = now.getFullYear();
      dateEl.textContent = `${dayName}, ${dayNum} ${monthName} ${year}`;
    }
  }

  updateClock();
  setInterval(updateClock, 1000);

  const statusDot = document.querySelector(".pixel-clock-status-dot");
  if (statusDot) {
    setInterval(() => statusDot.classList.toggle("is-dim"), 900);
  }

  let isDragging = false;
  let dragMoved = false;
  let startX = 0;
  let startY = 0;
  let initialLeft = 0;
  let initialTop = 0;

  // Toggle 12h / 24h on click
  const toggleTimeFormat = (e) => {
    if (dragMoved) return;
    e.stopPropagation();
    use24h = !use24h;
    localStorage.setItem("ika_clock_24h", String(use24h));
    updateClock();
    showToast(use24h ? "Formato de reloj: 24 Horas" : "Formato de reloj: 12 Horas (AM/PM)");
  };

  if (modeBtn) modeBtn.addEventListener("click", toggleTimeFormat);
  timeEl.addEventListener("click", toggleTimeFormat);

  // Directly draggable on click and drag
  clock.addEventListener("pointerdown", (e) => {
    if (e.button !== 0) return;
    // Don't drag if clicking mode button
    if (e.target.closest("#pixel-clock-mode-btn")) return;

    isDragging = true;
    dragMoved = false;
    clock.classList.add("is-dragging");
    try {
      clock.setPointerCapture(e.pointerId);
    } catch (_) {}

    const rect = clock.getBoundingClientRect();
    const parentRect = clock.offsetParent ? clock.offsetParent.getBoundingClientRect() : { left: 0, top: 0 };
    initialLeft = rect.left - parentRect.left;
    initialTop = rect.top - parentRect.top;
    startX = e.clientX;
    startY = e.clientY;
  });

  clock.addEventListener("pointermove", (e) => {
    if (!isDragging) return;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;

    if (Math.abs(dx) > 3 || Math.abs(dy) > 3) {
      dragMoved = true;
    }

    let newLeft = Math.round(initialLeft + dx);
    let newTop = Math.round(initialTop + dy);

    const maxLeft = Math.max(10, window.innerWidth - clock.offsetWidth - 20);
    const maxTop = Math.max(56, window.innerHeight - clock.offsetHeight - 140);
    newLeft = Math.max(10, Math.min(newLeft, maxLeft));
    newTop = Math.max(56, Math.min(newTop, maxTop));

    clock.style.left = `${newLeft}px`;
    clock.style.top = `${newTop}px`;
    clock.style.right = "auto";
  });

  const onClockPointerUp = (e) => {
    if (!isDragging) return;
    isDragging = false;
    clock.classList.remove("is-dragging");
    try {
      clock.releasePointerCapture(e.pointerId);
    } catch (_) {}

    if (dragMoved) {
      const curLeft = parseInt(clock.style.left, 10);
      const curTop = parseInt(clock.style.top, 10);
      if (!isNaN(curLeft) && !isNaN(curTop)) {
        localStorage.setItem("ika_pixel_clock_pos", JSON.stringify({ left: curLeft, top: curTop }));
        saveHomeLayoutFile();
      }
    }
  };

  clock.addEventListener("pointerup", onClockPointerUp);
  clock.addEventListener("pointercancel", onClockPointerUp);
}

