const STORAGE_CUSTOM_INSTANCE_COVERS_KEY = "modcomparer_custom_instance_covers";
const STORAGE_CUSTOM_INSTANCE_ICONS_KEY = "modcomparer_custom_instance_icons";

function getCustomInstanceCoversMap() {
  try {
    const raw = localStorage.getItem(STORAGE_CUSTOM_INSTANCE_COVERS_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveCustomInstanceCover(instanceKey, coverUrl) {
  try {
    const map = getCustomInstanceCoversMap();
    map[instanceKey] = coverUrl;
    localStorage.setItem(STORAGE_CUSTOM_INSTANCE_COVERS_KEY, JSON.stringify(map));
  } catch (err) {
    console.error("Error saving custom instance cover:", err);
  }
}

function getCustomInstanceIconsMap() {
  try {
    const raw = localStorage.getItem(STORAGE_CUSTOM_INSTANCE_ICONS_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveCustomInstanceIcon(instanceKey, iconUrl) {
  try {
    const map = getCustomInstanceIconsMap();
    map[instanceKey] = iconUrl;
    localStorage.setItem(STORAGE_CUSTOM_INSTANCE_ICONS_KEY, JSON.stringify(map));
  } catch (err) {
    console.error("Error saving custom instance icon:", err);
  }
}

