const instanceBlockFaceMap = new Map();
let availableBlockIndices = [];
let dynamicBlockTextures = [];

async function refreshAvailableBlockTextures() {
  try {
    const filePaths = await invoke("get_minecraft_block_textures");
    if (Array.isArray(filePaths) && filePaths.length > 0) {
      dynamicBlockTextures = filePaths.map((fp) => convertFileSrc(fp));
      // Invalidate any instance cached texture that was deleted from disk
      for (const [key, cachedUrl] of instanceBlockFaceMap.entries()) {
        if (!dynamicBlockTextures.includes(cachedUrl)) {
          instanceBlockFaceMap.delete(key);
        }
      }
      return;
    }
  } catch (err) {
    console.warn("Could not load dynamic block textures:", err);
  }
  dynamicBlockTextures = [...MINECRAFT_BLOCK_SIDE_TEXTURES];
}

async function openBlockTexturesFolder() {
  try {
    await invoke("open_block_textures_folder");
  } catch (err) {
    console.error("Error opening block textures folder:", err);
  }
}

function getUniqueBlockFaceForInstance(instPath, instName) {
  const textures = (dynamicBlockTextures && dynamicBlockTextures.length > 0)
    ? dynamicBlockTextures
    : MINECRAFT_BLOCK_SIDE_TEXTURES;
  const key = (instPath || instName || "default").toLowerCase();

  // If already mapped and still present in current textures, keep it
  if (instanceBlockFaceMap.has(key)) {
    const cached = instanceBlockFaceMap.get(key);
    if (textures.includes(cached)) {
      return cached;
    }
    instanceBlockFaceMap.delete(key);
  }

  // Ensure available indices are within current bounds
  availableBlockIndices = availableBlockIndices.filter((i) => i < textures.length);

  if (availableBlockIndices.length === 0) {
    availableBlockIndices = Array.from({ length: textures.length }, (_, i) => i);
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
      hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
    }
    for (let i = availableBlockIndices.length - 1; i > 0; i--) {
      const j = (hash + i) % (i + 1);
      [availableBlockIndices[i], availableBlockIndices[j]] = [availableBlockIndices[j], availableBlockIndices[i]];
    }
  }

  const chosenIndex = availableBlockIndices.shift();
  const chosenTexture = textures[chosenIndex % textures.length];
  instanceBlockFaceMap.set(key, chosenTexture);
  return chosenTexture;
}

function getInstanceCoverUrl(inst, idx = -1) {
  if (!inst) return COZY_COVERS_POOL[0];
  const customCovers = getCustomInstanceCoversMap();
  const key = inst.path || inst.folder_name || inst.name;
  if (key && (customCovers[key] || customCovers[inst.name])) {
    const chosen = customCovers[key] || customCovers[inst.name];
    inst.coverUrl = chosen;
    return chosen;
  }
  if (inst.coverUrl) return inst.coverUrl;

  let index = idx;
  if (index < 0 && Array.isArray(homeInstancesList)) {
    index = homeInstancesList.indexOf(inst);
  }

  if (index < 0) {
    const key = (inst.path || inst.folder_name || inst.name || "").toLowerCase();
    let hash = 0;
    for (let i = 0; i < key.length; i++) {
      hash = (hash * 31 + key.charCodeAt(i)) >>> 0;
    }
    index = hash % COZY_COVERS_POOL.length;
  }

  const chosen = COZY_COVERS_POOL[index % COZY_COVERS_POOL.length];
  inst.coverUrl = chosen;
  return chosen;
}

function getCustomInstanceNamesMap() {
  try {
    const raw = localStorage.getItem(STORAGE_CUSTOM_INSTANCE_NAMES_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}

function saveCustomInstanceName(instancePath, newName) {
  try {
    const map = getCustomInstanceNamesMap();
    map[instancePath] = newName;
    localStorage.setItem(STORAGE_CUSTOM_INSTANCE_NAMES_KEY, JSON.stringify(map));
  } catch (err) {
    console.error("Error saving custom instance name:", err);
  }
}

function formatInstanceDisplayName(rawName) {
  if (!rawName) return "INSTANCIA";
  let clean = rawName.trim();
  // Strip version patterns (e.g., 2.0.0, 1.20.1, 1.21.1)
  clean = clean.replace(/\b\d+(\.\d+)+(\s+\d+(\.\d+)+)*\b/gi, "");
  // Strip mod loader keywords
  clean = clean.replace(/\b(neoforge|forge|fabric|quilt|vanilla)\b/gi, "");
  // Strip trailing/leading spaces, dashes, underscores
  clean = clean.replace(/[\s\-_]+$/g, "").replace(/^[\s\-_]+/g, "").replace(/\s{2,}/g, " ");
  return clean.toUpperCase() || rawName.toUpperCase();
}

function applyHomeFilter() {
  const q = (homeSearchQuery || "").toLowerCase().trim();
  const cat = homeFilterCategory || "all";
  const customNames = getCustomInstanceNamesMap();

  homeInstancesList = homeInstancesAll.filter((inst) => {
    // 1. Search Query Filter
    if (q) {
      const rawCustom = customNames[inst.path] || "";
      const name = (inst.name || "").toLowerCase();
      const folder = (inst.folder_name || "").toLowerCase();
      const ver = (inst.mc_version || "").toLowerCase();
      const loader = (inst.loader || "").toLowerCase();
      const matches = name.includes(q) || folder.includes(q) || rawCustom.toLowerCase().includes(q) || ver.includes(q) || loader.includes(q);
      if (!matches) return false;
    }

    // 2. Category Filter
    if (cat === "all") return true;
    if (cat === "favorites") {
      return favoriteInstances.has(inst.path);
    }
    if (cat === "recent") {
      return recentInstances.has(inst.path);
    }
    if (cat === "modpacks") {
      const count = typeof inst.mod_count === "number" ? inst.mod_count : 0;
      const n = (inst.name || "").toLowerCase();
      return count >= 15 || n.includes("pack") || n.includes("modpack") || n.includes("all the mods") || n.includes("better");
    }
    if (cat === "optimized") {
      const n = (inst.name || "").toLowerCase();
      return n.includes("optimiz") || n.includes("fps") || n.includes("perf") || n.includes("boost") || n.includes("sodium") || n.includes("simply") || n.includes("fabulously");
    }
    return true;
  });

  if (homeInstancesList.length === 0) {
    homeCurrentInstanceIndex = 0;
    if (el.homeInstanceTitle) el.homeInstanceTitle.textContent = "SIN RESULTADOS";
    if (el.homeActiveVersion) el.homeActiveVersion.textContent = "-";
    if (el.homeActiveLoader) el.homeActiveLoader.textContent = "-";
    if (el.homeActiveMods) el.homeActiveMods.textContent = "0 mods";
  } else {
    const activePath = localStorage.getItem(STORAGE_ACTIVE_INSTANCE_PATH_KEY);
    let idx = homeInstancesList.findIndex((i) => i.path === activePath);
    if (idx === -1) idx = 0;
    homeCurrentInstanceIndex = idx;
    applyActiveHomeInstance(homeCurrentInstanceIndex);
  }

  renderHomeInstanceCarousel();
  refreshAvailableBlockTextures().then(() => renderHomeInstanceCarousel()).catch(() => {});
}

async function reloadAllHomeInstances(selectName = null) {
  try {
    const list = await invoke("get_all_instances");
    if (Array.isArray(list) && list.length > 0) {
      const seenPaths = new Set();
      const seenNames = new Set();
      homeInstancesList = list.filter((item) => {
        const pathKey = (item.path || item.folder_name || item.name || "").trim().toLowerCase();
        const nameKey = (item.name || item.folder_name || "").trim().toLowerCase().replace(/\s+/g, " ");
        if (!pathKey || seenPaths.has(pathKey) || (nameKey && seenNames.has(nameKey))) return false;
        seenPaths.add(pathKey);
        if (nameKey) seenNames.add(nameKey);
        return true;
      });
      homeInstancesList.forEach((item, i) => {
        item.coverUrl = COZY_COVERS_POOL[i % COZY_COVERS_POOL.length];
      });
    }
  } catch (err) {
    console.error("Error reloading instances:", err);
  }
  homeInstancesAll = [...homeInstancesList];

  if (selectName) {
    const target = homeInstancesList.findIndex((i) =>
      (i.path || "").toLowerCase() === selectName.toLowerCase() ||
      (i.name || "").toLowerCase() === selectName.toLowerCase() ||
      (i.folder_name || "").toLowerCase() === selectName.toLowerCase()
    );
    if (target !== -1) {
      homeCurrentInstanceIndex = target;
    }
  } else {
    if (homeCurrentInstanceIndex >= homeInstancesList.length) {
      homeCurrentInstanceIndex = 0;
    }
  }

  await refreshAvailableBlockTextures();
  applyActiveHomeInstance(homeCurrentInstanceIndex);
  renderHomeInstanceCarousel();
}

