function detectJavaDistribution(inst) {
  const vendorStr = String(inst?.java_vendor || "").toLowerCase();
  const pathStr = String(inst?.java_path || "").toLowerCase();
  const verStr = String(inst?.java_version || "").toLowerCase();
  const combined = `${vendorStr} ${pathStr} ${verStr}`;

  let vendorKey = "openjdk";

  if (combined.includes("zulu") || combined.includes("azul")) {
    vendorKey = "zulu";
  } else if (combined.includes("adoptium") || combined.includes("temurin") || combined.includes("eclipse")) {
    vendorKey = "adoptium";
  } else if (combined.includes("microsoft") || combined.includes("mojang") || combined.includes("java-runtime-")) {
    vendorKey = "mojang";
  } else if (combined.includes("semeru") || combined.includes("openj9") || vendorStr.includes("ibm")) {
    vendorKey = "semeru";
  } else if (combined.includes("jetbrains") || combined.includes("jbr") || combined.includes("jvmika")) {
    vendorKey = "jetbrains";
  } else if (combined.includes("corretto") || combined.includes("amazon")) {
    vendorKey = "corretto";
  } else if (combined.includes("liberica") || combined.includes("bellsoft")) {
    vendorKey = "liberica";
  } else if (combined.includes("graalvm") || combined.includes("graal")) {
    vendorKey = "graalvm";
  } else if (combined.includes("oracle") || combined.includes("jre-legacy")) {
    vendorKey = "oracle";
  }

  // Determine clean Java major version
  let cleanVer = "Java 21";
  const rawVer = inst?.java_version || "";
  const mcVer = inst?.mc_version || "1.20.1";

  if (rawVer) {
    if (rawVer.startsWith("1.8") || rawVer === "8") {
      cleanVer = "Java 8";
    } else {
      const match = rawVer.match(/\b(21|17|16|15|11|8)\b/) || rawVer.match(/^(\d+)/);
      if (match) {
        cleanVer = `Java ${match[1]}`;
      } else {
        cleanVer = rawVer.startsWith("Java") ? rawVer : `Java ${rawVer}`;
      }
    }
  } else {
    if (mcVer.startsWith("1.20.5") || mcVer.startsWith("1.21") || mcVer.startsWith("1.22")) {
      cleanVer = "Java 21";
    } else if (mcVer.startsWith("1.18") || mcVer.startsWith("1.19") || mcVer.startsWith("1.20")) {
      cleanVer = "Java 17";
    } else if (mcVer.startsWith("1.17")) {
      cleanVer = "Java 16";
    } else {
      cleanVer = "Java 8";
    }
  }

  const cfg = JAVA_VENDOR_CONFIGS[vendorKey] || JAVA_VENDOR_CONFIGS.openjdk;
  return {
    key: vendorKey,
    version: cleanVer,
    vendorName: cfg.name,
    vendorTitle: cfg.title,
    color: cfg.color,
    iconHtml: javaVendorIconHtml(vendorKey, 22),
  };
}

// Icon of a Java distribution at the given size: its logo if it has one, else its drawn icon.
function javaVendorIconHtml(vendorKey, size) {
  const cfg = JAVA_VENDOR_CONFIGS[vendorKey] || JAVA_VENDOR_CONFIGS.openjdk;
  if (cfg.icon) return `<img class="java-vendor-logo" src="${cfg.icon}" alt="" width="${size}" height="${size}" />`;
  return cfg.svg.replace('width="22"', `width="${size}"`).replace('height="22"', `height="${size}"`);
}

function getModsIconSvg() {
  return `<svg class="meta-badge-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
    <path d="M12 3.5L3 8.5v11h18v-11L12 3.5z"></path>
    <rect x="9.5" y="12.5" width="5" height="3" rx="0.5" fill="currentColor"></rect>
  </svg>`;
}

function createCarouselGhostCard() {
  const cardItem = document.createElement("div");
  cardItem.className = "carousel-card-item is-side is-ghost";
  cardItem.title = "Crear nueva instancia";
  cardItem.innerHTML = `
    <div class="carousel-card-body">
      <div class="card-content-wrap carousel-ghost-wrap">
        <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true">
          <line x1="12" y1="5" x2="12" y2="19"></line>
          <line x1="5" y1="12" x2="19" y2="12"></line>
        </svg>
        <span class="carousel-ghost-label">Nueva instancia</span>
      </div>
    </div>
  `;
  cardItem.addEventListener("click", () => el.btnCreateInstancePill?.click());
  return cardItem;
}

function renderHomeInstanceCarousel() {
  if (!el.instanceCarouselTrack) return;
  el.instanceCarouselTrack.innerHTML = "";

  const total = homeInstancesList.length;
  if (total === 0) {
    const emptyNotice = document.createElement("div");
    emptyNotice.className = "carousel-empty-notice";
    emptyNotice.innerHTML = `
      <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#64748b" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <circle cx="11" cy="11" r="8"></circle>
        <line x1="21" y1="21" x2="16.65" y2="16.65"></line>
      </svg>
      <p style="margin:0;font-size:12.5px;color:#94a3b8;">No se encontraron instancias coincidentes</p>
    `;
    el.instanceCarouselTrack.appendChild(emptyNotice);
    return;
  }

  const customNames = getCustomInstanceNamesMap();

  // Always symmetric around the active card: 3 cards, or 5 when there are 5+ instances.
  // Missing neighbours become "+" ghost cards that open the create-instance modal.
  let offsets;
  if (total === 1) {
    offsets = ["ghost", 0, "ghost"];
  } else if (total === 2) {
    offsets = [-1, 0, "ghost"];
  } else if (total <= 4) {
    offsets = [-1, 0, 1];
  } else {
    offsets = [-2, -1, 0, 1, 2]; // Max 5: 2 left, 1 active center, 2 right
  }

  offsets.forEach((offset) => {
    if (offset === "ghost") {
      el.instanceCarouselTrack.appendChild(createCarouselGhostCard());
      return;
    }
    const idx = (homeCurrentInstanceIndex + offset + total * 1000) % total;
    const inst = homeInstancesList[idx];
    if (!inst) return;

    const rawCustom = customNames[inst.path];
    const displayName = rawCustom ? rawCustom.toUpperCase() : formatInstanceDisplayName(inst.name);
    const mcVer = inst.mc_version || "1.20.1";
    const loader = inst.loader || "Forge";
    const modCount = typeof inst.mod_count === "number" ? inst.mod_count : 0;
    const javaInfo = detectJavaDistribution(inst);
    const javaVer = javaInfo.version;
    const coverUrl = getInstanceCoverUrl(inst, idx);
    const isActive = offset === 0;
    const isFav = favoriteInstances.has(inst.path);

    const cardItem = document.createElement("div");
    cardItem.className = `carousel-card-item ${isActive ? "is-active" : "is-side"}`;
    cardItem.dataset.instanceIndex = idx;
    cardItem.title = isActive ? `${displayName} (Activa)` : `Seleccionar: ${displayName}`;

    const cardBody = document.createElement("div");
    cardBody.className = "carousel-card-body";

    // Inner content wrap for card rounding & containment
    const contentWrap = document.createElement("div");
    contentWrap.className = "card-content-wrap";

    // 1. Top Cover Image Container
    const coverContainer = document.createElement("div");
    coverContainer.className = "card-cover-container";

    const img = document.createElement("img");
    img.className = "carousel-card-img";
    img.src = coverUrl;
    img.alt = displayName;
    img.loading = "eager";
    img.onerror = () => {
      img.src = COZY_COVERS_POOL[0];
    };
    coverContainer.appendChild(img);
    contentWrap.appendChild(coverContainer);

    // 2. Bottom Rectangular Info Zone
    const infoFooter = document.createElement("div");
    infoFooter.className = "card-info-footer";

    // Left Slot: Modpack Icon or unique Minecraft block face
    const iconSlot = document.createElement("div");
    iconSlot.className = "card-icon-slot";

    const uniqueBlockFace = getUniqueBlockFaceForInstance(inst.path, inst.name);

    const customIcons = getCustomInstanceIconsMap();
    const customIcon = customIcons[inst.path] || customIcons[inst.folder_name] || customIcons[inst.name];

    if (customIcon) {
      const packImg = document.createElement("img");
      packImg.className = "card-pack-icon";
      packImg.src = customIcon;
      packImg.alt = displayName;
      packImg.loading = "eager";
      iconSlot.appendChild(packImg);
    } else if (inst.icon_path) {
      const packImg = document.createElement("img");
      packImg.className = "card-pack-icon";
      packImg.src = convertFileSrc(inst.icon_path);
      packImg.alt = displayName;
      packImg.loading = "eager";
      packImg.onerror = () => {
        packImg.src = uniqueBlockFace;
        packImg.classList.add("is-block-face");
      };
      iconSlot.appendChild(packImg);
    } else {
      const blockImg = document.createElement("img");
      blockImg.className = "card-pack-icon is-block-face";
      blockImg.src = uniqueBlockFace;
      blockImg.alt = displayName;
      iconSlot.appendChild(blockImg);
    }
    infoFooter.appendChild(iconSlot);

    // Right Slot: Title, Meta, and Favorite Star
    const metaSlot = document.createElement("div");
    metaSlot.className = "card-meta-slot";

    // Row 1: Instance Title & Star Button
    const titleRow = document.createElement("div");
    titleRow.className = "card-title-row";

    const titleText = document.createElement("span");
    titleText.className = "card-title-text";
    titleText.textContent = displayName;
    titleText.title = displayName;
    titleRow.appendChild(titleText);

    const favBtn = document.createElement("button");
    favBtn.className = `card-fav-btn ${isFav ? "is-fav" : ""}`;
    favBtn.title = isFav ? "Quitar de favoritas" : "Marcar como favorita";
    favBtn.innerHTML = `
      <svg class="star-icon" viewBox="0 0 24 24" width="${isActive ? 16 : 13}" height="${isActive ? 16 : 13}" fill="${isFav ? "#fbbf24" : "none"}" stroke="${isFav ? "#fbbf24" : "#94a3b8"}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"></path>
      </svg>
    `;

    favBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      const isCurrentlyFav = favoriteInstances.has(inst.path);
      if (isCurrentlyFav) {
        favoriteInstances.delete(inst.path);
        favBtn.classList.remove("is-fav");
        const svg = favBtn.querySelector("svg");
        if (svg) {
          svg.setAttribute("fill", "none");
          svg.setAttribute("stroke", "#94a3b8");
        }
      } else {
        favoriteInstances.add(inst.path);
        favBtn.classList.add("is-fav");
        const svg = favBtn.querySelector("svg");
        if (svg) {
          svg.setAttribute("fill", "#fbbf24");
          svg.setAttribute("stroke", "#fbbf24");
        }
      }
      try {
        localStorage.setItem("modcomparer_favorites", JSON.stringify([...favoriteInstances]));
      } catch {}
      showToast(!isCurrentlyFav ? "Añadida a Favoritas ⭐" : "Eliminada de Favoritas");
      if (homeFilterCategory === "favorites") {
        applyHomeFilter();
      }
    });

    titleRow.appendChild(favBtn);
    metaSlot.appendChild(titleRow);

    // Row 2: Badges (Version, Loader, Mods count, Java version)
    const badgesRow = document.createElement("div");
    badgesRow.className = "card-badges-row";

    if (isActive) {
      badgesRow.innerHTML = `
        <span class="card-badge-item badge-mc-ver">${mcVer}</span>
        <span class="card-badge-item badge-loader">
          ${getLoaderIconSvg(loader)}
          <span>${loader}</span>
        </span>
        <span class="card-badge-item badge-mods">
          ${getModsIconSvg()}
          <span>${modCount} mods</span>
        </span>
        <span class="card-badge-item badge-java" title="${javaInfo.version} (${javaInfo.vendorTitle})">
          ${javaVendorIconHtml(javaInfo.key, 12)}
          <span>${javaInfo.version}</span>
        </span>
      `;
    } else {
      badgesRow.innerHTML = `
        <span class="card-badge-item badge-mc-ver">${mcVer}</span>
        <span class="card-badge-sep">•</span>
        <span class="card-badge-item badge-loader">${loader}</span>
        <span class="card-badge-sep">•</span>
        <span class="card-badge-item badge-java">${javaInfo.version}</span>
      `;
    }

    metaSlot.appendChild(badgesRow);
    infoFooter.appendChild(metaSlot);
    contentWrap.appendChild(infoFooter);
    cardBody.appendChild(contentWrap);

    // Active center card: exact stroke & TopRosao gradient with angle dial rotation
    if (isActive) {
      const svgNS = "http://www.w3.org/2000/svg";
      const svg = document.createElementNS(svgNS, "svg");
      svg.setAttribute("class", "card-border-svg");
      svg.setAttribute("viewBox", "0 0 320 192");
      svg.setAttribute("preserveAspectRatio", "none");
      svg.setAttribute("fill", "none");
      svg.setAttribute("aria-hidden", "true");
      svg.innerHTML = `
        <rect x="1" y="1" width="318" height="190" rx="16" ry="16"
              fill="none"
              stroke="url(#cardGodStrokeGrad)"
              stroke-width="2"
              vector-effect="non-scaling-stroke" />
      `;
      cardBody.appendChild(svg);
    }

    cardItem.appendChild(cardBody);

    if (isActive) {
      if (el.homeInstanceTitle) el.homeInstanceTitle.textContent = displayName;
      if (el.homeActiveVersion) el.homeActiveVersion.textContent = mcVer;
      if (el.homeActiveLoader) el.homeActiveLoader.textContent = loader;
      if (el.homeActiveMods) el.homeActiveMods.textContent = `${modCount} mods`;
    } else {
      // Clicking flanking card triggers smooth switch animation
      cardItem.addEventListener("click", () => {
        const dir = offset > 0 ? "next" : "prev";
        switchHomeInstance(idx, dir);
      });
    }

    el.instanceCarouselTrack.appendChild(cardItem);
  });

  if (typeof renderMiColeccionGrid === "function") {
    renderMiColeccionGrid();
  }
}

function applyActiveHomeInstance(index) {
  if (homeInstancesList.length === 0) return;
  const inst = homeInstancesList[index];
  if (!inst) return;

  const customNames = getCustomInstanceNamesMap();
  const rawCustom = customNames[inst.path];
  const displayName = rawCustom ? rawCustom.toUpperCase() : formatInstanceDisplayName(inst.name);

  if (el.homeInstanceTitle) {
    el.homeInstanceTitle.textContent = displayName;
  }
  if (el.homeChipName) {
    el.homeChipName.textContent = displayName;
    el.homeChipName.title = inst.path;
  }

  const count = typeof inst.mod_count === "number" ? inst.mod_count : 0;
  if (el.homeStatMods) {
    el.homeStatMods.textContent = `${count} mods activos`;
  }
  if (el.homeActiveVersion) {
    el.homeActiveVersion.textContent = inst.mc_version || "1.20.1";
  }
  if (el.homeActiveLoader) {
    el.homeActiveLoader.textContent = inst.loader || "Forge";
  }
  if (el.homeActiveMods) {
    el.homeActiveMods.textContent = `${count} mods`;
  }

  // Update Favorite Star button state
  if (el.btnHomeToggleFav) {
    const isFav = favoriteInstances.has(inst.path);
    el.btnHomeToggleFav.classList.toggle("is-favorite", isFav);
    el.btnHomeToggleFav.title = isFav ? "Quitar de favoritas" : "Marcar como favorita";
  }

  localStorage.setItem(STORAGE_ACTIVE_INSTANCE_PATH_KEY, inst.path);
  state.path1 = inst.mods_path;
  localStorage.setItem("modcomparer_path1", inst.mods_path);
  updateConsoleBadge();
  syncPlayButtonLock();
  logToConsole("INST", `Instancia seleccionada: ${displayName} [${inst.mc_version || "1.20.1"}] - ${count} mods`, "info");
  updateHomeConsolePreview();
  updateInstanceSpecsBar(inst);
  updateColeccionSelectedFooter(inst);
  window.ikaManager?.syncFromHome?.(inst.path);
}

function syncHomeInstanceByPath(instancePath) {
  if (!instancePath) return;
  let idx = homeInstancesList.findIndex((x) => x.path === instancePath);
  if (idx === -1 && homeInstancesAll.some((x) => x.path === instancePath)) {
    homeFilterCategory = "all";
    homeSearchQuery = "";
    if (el.inputSearchInstance) el.inputSearchInstance.value = "";
    if (el.btnClearInstanceSearch) el.btnClearInstanceSearch.classList.add("hidden");
    if (el.instanceCategoryPills) {
      el.instanceCategoryPills.querySelectorAll(".inst-pill").forEach((p) => {
        p.classList.toggle("active", (p.dataset.filter || "all") === "all");
      });
    }
    homeInstancesList = [...homeInstancesAll];
    idx = homeInstancesList.findIndex((x) => x.path === instancePath);
  }
  if (idx !== -1 && idx !== homeCurrentInstanceIndex) {
    homeCurrentInstanceIndex = idx;
    applyActiveHomeInstance(homeCurrentInstanceIndex);
    renderHomeInstanceCarousel();
  } else if (idx !== -1) {
    updateInstanceSpecsBar(homeInstancesList[idx]);
    syncPlayButtonLock();
  }
}

function formatPlayTime(seconds) {
  if (!seconds || seconds <= 0) return "0 hrs";
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const mins = Math.floor((seconds % 3600) / 60);

  if (days > 0) {
    return hours > 0 ? `${days}d ${hours}h` : `${days}d`;
  }
  if (hours > 0) {
    return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
  }
  return `${mins} min`;
}

function formatPlayTimeTooltip(seconds) {
  if (!seconds || seconds <= 0) return "Sin tiempo de juego registrado en esta instancia";
  const days = Math.floor(seconds / 86400);
  const hours = Math.floor((seconds % 86400) / 3600);
  const mins = Math.floor((seconds % 3600) / 60);
  const totalHours = (seconds / 3600).toFixed(1);

  let parts = [];
  if (days > 0) parts.push(`${days} ${days === 1 ? "día" : "días"}`);
  if (hours > 0) parts.push(`${hours} ${hours === 1 ? "hora" : "horas"}`);
  if (mins > 0) parts.push(`${mins} min`);

  return `${parts.join(", ")} jugados (${totalHours} hrs totales)`;
}

function formatInstanceRamLabel(inst) {
  const mb = Number(inst?.max_mem_mb) || 0;
  if (mb > 0) {
    const gb = (mb / 1024).toFixed(1).replace(/\.0$/, "");
    return `${gb} GB`;
  }
  let ram = inst?.ram || inst?.allocated_ram || "8.4 GB";
  if (typeof ram === "number") ram = `${ram} GB`;
  return ram;
}

function updateInstanceSpecsBar(inst, skipLiveFetch = false) {
  if (!inst) return;
  const count = typeof inst.mod_count === "number" ? inst.mod_count : 0;
  const loader = inst.loader || "Fabric";

  // Java distribution & version determination
  const javaInfo = detectJavaDistribution(inst);

  // RAM determination
  const ram = formatInstanceRamLabel(inst);

  // Shaders count
  const shaderCount = typeof inst.shader_count === "number" ? inst.shader_count : 0;
  const shaderText = shaderCount === 1 ? "1 shader" : `${shaderCount} shaders`;

  // Resource packs count
  const rpCount = typeof inst.resourcepack_count === "number" ? inst.resourcepack_count : 0;
  const rpText = rpCount === 1 ? "1 pack" : `${rpCount} packs`;

  // Play time
  const totalSecs = typeof inst.total_time_played === "number" ? inst.total_time_played : 0;
  const playtimeText = formatPlayTime(totalSecs);
  const playtimeTooltip = formatPlayTimeTooltip(totalSecs);

  const elMods = document.getElementById("spec-mods-count");
  if (elMods) elMods.textContent = `${count} mods`;

  const elRam = document.getElementById("spec-ram-allocated");
  if (elRam) elRam.textContent = ram;

  const elLoader = document.getElementById("spec-loader-type");
  if (elLoader) elLoader.textContent = loader;

  const elJvm = document.getElementById("spec-java-ver");
  if (elJvm) elJvm.textContent = javaInfo.version;

  const elVendor = document.getElementById("spec-java-vendor");
  if (elVendor) elVendor.textContent = javaInfo.vendorName;

  const elIconContainer = document.getElementById("spec-jvm-icon-container");
  if (elIconContainer) {
    elIconContainer.innerHTML = javaInfo.iconHtml;
    elIconContainer.style.filter = `drop-shadow(0 0 7px ${javaInfo.color}88)`;
  }

  const specItemJvm = document.getElementById("spec-item-jvm");
  if (specItemJvm) {
    specItemJvm.title = `${javaInfo.version} (${javaInfo.vendorTitle}) - JVM`;
  }

  const elShader = document.getElementById("spec-shaders-count");
  if (elShader) elShader.textContent = shaderText;
  const specItemShaders = document.getElementById("spec-item-shaders");
  if (specItemShaders) {
    specItemShaders.title = `${shaderCount} ${shaderCount === 1 ? "shader instalado" : "shaders instalados"}`;
  }

  const elRps = document.getElementById("spec-resourcepacks-count");
  if (elRps) elRps.textContent = rpText;
  const specItemRps = document.getElementById("spec-item-resourcepacks");
  if (specItemRps) {
    specItemRps.title = `${rpCount} ${rpCount === 1 ? "resource pack instalado" : "resource packs instalados"}`;
  }

  const elPlaytime = document.getElementById("spec-playtime");
  if (elPlaytime) elPlaytime.textContent = playtimeText;
  const specItemPlaytime = document.getElementById("spec-item-playtime");
  if (specItemPlaytime) {
    specItemPlaytime.title = playtimeTooltip;
  }

  if (!skipLiveFetch && inst.path) {
    const targetPath = inst.path;
    Promise.allSettled([
      invoke("list_instance_packs", { instancePath: targetPath }),
      invoke("get_instance_details", { instancePath: targetPath }),
    ]).then(([packsRes, detailsRes]) => {
      let changed = false;
      if (packsRes.status === "fulfilled" && packsRes.value) {
        const nextShaders = Array.isArray(packsRes.value.shaders) ? packsRes.value.shaders.length : 0;
        const nextRps = Array.isArray(packsRes.value.resourcepacks) ? packsRes.value.resourcepacks.length : 0;
        if (inst.shader_count !== nextShaders) {
          inst.shader_count = nextShaders;
          changed = true;
        }
        if (inst.resourcepack_count !== nextRps) {
          inst.resourcepack_count = nextRps;
          changed = true;
        }
      }
      if (detailsRes.status === "fulfilled" && detailsRes.value) {
        const d = detailsRes.value;
        if (typeof d.mods_count === "number" && inst.mod_count !== d.mods_count) {
          inst.mod_count = d.mods_count;
          changed = true;
        }
        if (d.max_mem_mb && inst.max_mem_mb !== d.max_mem_mb) {
          inst.max_mem_mb = d.max_mem_mb;
          changed = true;
        }
        if (d.loader && inst.loader !== d.loader) {
          inst.loader = d.loader;
          changed = true;
        }
      }
      const currentActive = homeInstancesList && homeInstancesList[homeCurrentInstanceIndex];
      if (changed && currentActive && currentActive.path === targetPath) {
        updateInstanceSpecsBar(inst, true);
        if (el.homeStatMods) el.homeStatMods.textContent = `${inst.mod_count} mods activos`;
        if (el.homeActiveMods) el.homeActiveMods.textContent = `${inst.mod_count} mods`;
        const activeCardMods = document.querySelector(".carousel-card-item.is-active .badge-mods span");
        if (activeCardMods) activeCardMods.textContent = `${inst.mod_count} mods`;
      }
    }).catch(() => {});
  }
}

// =========================================================
// LIVE GAME CONSOLE PREVIEW DOCK (INICIO VIEW)
// =========================================================
let homeConsolePollInterval = null;

// Live output of games launched from here (filled by the "mc-game-log" listener).
const GAME_LOG_BUFFER_LINES = 400;
const gameLogBuffers = new Map(); // normalized instance path -> [{ level, text, ts }]
const gameLogTotals = new Map(); // normalized instance path -> lines received so far

// Launch state of each instance, shown in the console window header.
const gameStates = new Map(); // normalized instance path -> { state, detail }
const HCP_STATE_TEXT = {
  idle: "Listo para jugar",
  preparing: "Preparando",
  running: "Cargando Minecraft",
  menu: "Listo",
  world: "Cargando el mundo",
  connecting: "Conectando",
  ingame: "Jugando",
  closed: "Cierre correcto",
  crashed: "Crasheó",
  failed: "No se pudo iniciar",
};

function currentHomeInstance() {
  return (homeInstancesList && homeInstancesList[homeCurrentInstanceIndex]) || null;
}

function resolveDockActiveInstance() {
  const sharePath = window.ikaShare?.activeInstancePath?.();
  if (sharePath) {
    const found = (homeInstancesAll || homeInstancesList || []).find(
      (i) => normInstancePath(i.path) === normInstancePath(sharePath)
    );
    if (found) return found;
    return { path: sharePath, mods_path: `${sharePath}\\.minecraft\\mods` };
  }
  if (state.currentView === "manager") {
    const mgrInst = window.ikaManager?.activeInstance?.();
    if (mgrInst) return mgrInst;
  }
  return currentHomeInstance();
}

let setGameStateHook = null; // set by the console section

function setGameState(instance, state, detail = "") {
  const wasRunning = isAnyGameRunning();
  gameStates.set(normInstancePath(instance), { state, detail });
  renderHcpState();
  syncPlayButtonLock();
  setGameStateHook?.(instance, state);
  // A game starting or closing pauses/resumes the animated background.
  if (isAnyGameRunning() !== wasRunning) onLauncherActivityChange();
}

// States in which the Minecraft process started from here is alive. They follow the process
// the launcher itself spawned, so the Java that runs it (Mojang, Adoptium, a custom one...)
// makes no difference.
const GAME_PROCESS_STATES = new Set(["running", "menu", "world", "connecting", "ingame"]);

function isAnyGameRunning() {
  for (const { state } of gameStates.values()) {
    if (GAME_PROCESS_STATES.has(state)) return true;
  }
  return false;
}

// From "Jugar" until the game closes (or fails), that instance can't be launched again.
const GAME_ACTIVE_STATES = new Set(["preparing", "running", "menu", "world", "connecting", "ingame"]);

function isInstanceGameActive(instancePath) {
  return GAME_ACTIVE_STATES.has(gameStates.get(normInstancePath(instancePath))?.state);
}

// The play button follows the instance selected in Inicio with choreographed state transitions.
let playBtnMorphTimer = null;

function syncPlayButtonLock() {
  const btn = el.btnPlayGame;
  if (!btn) return;
  const inst = currentHomeInstance();
  const st = inst ? gameStates.get(normInstancePath(inst.path))?.state : null;
  const locked = GAME_ACTIVE_STATES.has(st);
  const visualState = !locked ? "idle" : st === "preparing" ? "preparing" : "running";
  const prevState = btn.dataset.playState || "idle";

  btn.classList.toggle("is-locked", locked);
  btn.classList.toggle("is-state-idle", visualState === "idle");
  btn.classList.toggle("is-state-preparing", visualState === "preparing");
  btn.classList.toggle("is-state-running", visualState === "running");
  btn.dataset.playState = visualState;
  btn.setAttribute("aria-disabled", locked ? "true" : "false");

  if (prevState !== visualState) {
    btn.classList.remove("is-shockwave", "is-state-morph");
    void btn.getBoundingClientRect();
    btn.classList.add("is-shockwave", "is-state-morph");
    if (playBtnMorphTimer) clearTimeout(playBtnMorphTimer);
    playBtnMorphTimer = setTimeout(() => {
      btn.classList.remove("is-state-morph");
    }, 680);
  }
}

function renderHcpState(fileState) {
  const box = document.getElementById("hcp-state");
  const inst = currentHomeInstance();
  const st = inst ? gameStates.get(normInstancePath(inst.path)) : null;
  const state = st?.state || (fileState === "running" ? "running" : (fileState === "closed" ? "closed" : "idle"));
  const text = st?.detail ? `${HCP_STATE_TEXT[state]} · ${st.detail}` : (HCP_STATE_TEXT[state] || "Cierre correcto");
  if (box) {
    box.dataset.state = state;
    box.title = text;
    const label = box.querySelector(".hcp-state-text");
    if (label) label.textContent = text;
  }

  // Update new cyber footer status and runtime (Ref: media_1791969222409)
  const footerStatus = document.getElementById("hcp-footer-status");
  const footerText = document.getElementById("hcp-footer-text");
  const footerIcon = document.getElementById("hcp-footer-icon");
  const footerRuntime = document.getElementById("hcp-footer-runtime");
  
  if (footerStatus) {
    footerStatus.dataset.state = state;
  }
  if (footerText) {
    footerText.textContent = text;
  }
  if (footerIcon) {
    if (state === "closed" || state === "idle") {
      footerIcon.innerHTML = `<svg viewBox="0 0 24 24" width="22" height="22" fill="none">
        <circle cx="12" cy="12" r="10" stroke="#34d399" stroke-width="2.2" />
        <polyline points="7.5 12 10.5 15 16.5 9" stroke="#34d399" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" />
      </svg>`;
    } else if (state === "crashed" || state === "failed") {
      footerIcon.innerHTML = `<svg viewBox="0 0 24 24" width="22" height="22" fill="none">
        <circle cx="12" cy="12" r="10" stroke="#ef4444" stroke-width="2.2" />
        <line x1="12" y1="8" x2="12" y2="13" stroke="#ef4444" stroke-width="2.2" stroke-linecap="round"/>
        <circle cx="12" cy="16.5" r="1" fill="#ef4444" />
      </svg>`;
    } else if (state === "running" || state === "world" || state === "connecting" || state === "menu" || state === "ingame") {
      footerIcon.innerHTML = `<svg viewBox="0 0 24 24" width="22" height="22" fill="none">
        <circle cx="12" cy="12" r="10" stroke="#38bdf8" stroke-width="2.2" stroke-dasharray="16 8" class="hcp-spin" />
        <polygon points="10 8 16 12 10 16" fill="#38bdf8" />
      </svg>`;
    } else {
      footerIcon.innerHTML = `<svg viewBox="0 0 24 24" width="22" height="22" fill="none">
        <circle cx="12" cy="12" r="10" stroke="#34d399" stroke-width="2.2" />
        <polyline points="7.5 12 10.5 15 16.5 9" stroke="#34d399" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" />
      </svg>`;
    }
  }
  if (footerRuntime) {
    footerRuntime.textContent = `Runtime: ${inst?.version || "1.20.1"}`;
  }
}

// Console window terminal: up to HCP_MAX_LINES lines (exactly 4 lines requested for clean preview), new ones appended (no full
// re-render), auto-scroll only while the view is at the bottom, so it can be scrolled
// and its text selected while the game writes.
const HCP_MAX_LINES = 4;
let hcpRenderedKey = "";
let hcpRenderedTotal = 0;
let hcpRenderedFileSig = "";

const HCP_LEVEL_LABEL = { INFO: "INFO", WARN: "AVISO", ERROR: "ERROR", FATAL: "ERROR", DEBUG: "DEBUG" };

// One log entry: dim time, colored level badge, thread in small grey, then the message.
// Launcher steps get their own badge and milestones (game ready, in world...) a green
// banner. Spaces between the parts keep copied text readable.
function hcpLineElement(text, level, ts) {
  const line = document.createElement("div");
  let lvl = String(level || "").toUpperCase();
  let rest = String(text || "");

  let time = ts ? new Date(ts).toTimeString().split(" ")[0] : "";
  const tm = rest.match(/^\[(\d{2}:\d{2}:\d{2})\]\s*/);
  if (tm) {
    if (!time) time = tm[1];
    rest = rest.slice(tm[0].length);
  }

  let thread = "";
  let kind = "game";
  if (lvl === "MILESTONE") {
    kind = "milestone";
  } else if (rest.startsWith("[Launcher] ")) {
    kind = "launcher";
    rest = rest.slice("[Launcher] ".length);
  } else {
    // "[Client thread/INFO] msg" or "[Client thread/INFO]: msg"
    const th = rest.match(/^\[([^\]\/]+)\/([A-Z]+)\]:?\s*/);
    if (th) {
      thread = th[1];
      if (!lvl) lvl = th[2];
      rest = rest.slice(th[0].length);
    }
  }
  if (!lvl) {
    const lower = rest.toLowerCase();
    lvl = lower.includes("exception") || lower.includes("error") ? "ERROR" : lower.includes("warn") ? "WARN" : "INFO";
  }
  const sev = lvl === "ERROR" || lvl === "FATAL" ? "error" : lvl === "WARN" ? "warn" : "info";
  line.className = `hcp-log-line kind-${kind} sev-${sev}`;

  const add = (cls, txt) => {
    const sp = document.createElement("span");
    sp.className = cls;
    sp.textContent = txt;
    line.append(sp, " ");
  };
  if (time) add("hcp-time", time);
  if (kind === "milestone") add("hcp-badge badge-milestone", "✓");
  else if (kind === "launcher") add("hcp-badge badge-launcher", "IKA");
  else add(`hcp-badge badge-${sev}`, HCP_LEVEL_LABEL[lvl] || lvl);
  if (thread) add("hcp-thread", thread);
  const msg = document.createElement("span");
  msg.className = "hcp-msg";
  msg.textContent = rest;
  line.appendChild(msg);
  return line;
}

// Milestones of a running game, recognised from its log (same markers in every version):
// game ready at the title screen, loading/creating a world, connecting to a server,
// in game, back to the menu.
const gameMilestoneState = new Map(); // normalized instance path -> { sound, gfx, ready, timer, phase }

function detectGameMilestones(instance, lines) {
  const key = normInstancePath(instance);
  const st = gameMilestoneState.get(key) || { sound: false, gfx: false, ready: false, timer: null, phase: "loading" };
  gameMilestoneState.set(key, st);
  const milestone = (text, state, detail = "") => {
    setGameState(instance, state, detail);
    pushGameLog(instance, [{ level: "MILESTONE", text, ts: Date.now() }]);
    appendGameLinesToConsole([{ level: "MILESTONE", text, ts: Date.now() }]);
  };

  for (const l of lines) {
    const t = l.text || "";
    if (/Sound engine started|OpenAL initialized|SoundSystem Starting up/.test(t)) st.sound = true;
    if (/textures-atlas|Created: \d+x\d+|Narrator library|Narrator successfully/.test(t)) st.gfx = true;

    if (/Preparing spawn area|Preparing start region/.test(t) && st.phase !== "world" && st.phase !== "ingame") {
      st.phase = "world";
      st.ready = true;
      milestone("Cargando el mundo...", "world");
    } else if (/Connecting to (?!Essential)[^,\s]+, \d+/.test(t) && st.phase !== "ingame") {
      const host = (t.match(/Connecting to ([^,\s]+)/) || [])[1] || "";
      st.phase = "connecting";
      st.ready = true;
      milestone(`Conectando a ${host}...`, "connecting", host);
    } else if (/logged in with entity id|joined the game|Loaded \d+ advancements/.test(t) && st.phase !== "ingame") {
      st.phase = "ingame";
      st.ready = true;
      milestone("Entraste al mundo. ¡A jugar!", "ingame");
    } else if (/Stopping singleplayer server|Stopping server/.test(t) && st.phase === "ingame") {
      st.phase = "menu";
      milestone("Saliste al menú principal", "menu");
    }
  }

  // Title screen: sound and graphics are up and the log has been quiet for a moment.
  if (!st.ready && st.sound && st.gfx) {
    clearTimeout(st.timer);
    st.timer = setTimeout(() => {
      if (st.ready) return;
      st.ready = true;
      st.phase = "menu";
      milestone("Minecraft está listo: ya puedes crear o entrar a un mundo", "menu");
    }, 1500);
  }
}

function renderHcpTerminal(inst, fileLines) {
  const box = el.homeConsolePreviewLogs;
  if (!box || !inst) return;
  const key = normInstancePath(inst.path);
  const atBottom = box.scrollTop + box.clientHeight >= box.scrollHeight - 24;
  const live = gameLogBuffers.get(key);
  const total = gameLogTotals.get(key) || 0;

  if (live && live.length) {
    if (key !== hcpRenderedKey || hcpRenderedFileSig) {
      box.textContent = "";
      hcpRenderedTotal = total - Math.min(live.length, HCP_MAX_LINES);
      hcpRenderedKey = key;
      hcpRenderedFileSig = "";
    }
    const fresh = Math.min(total - hcpRenderedTotal, live.length, HCP_MAX_LINES);
    if (fresh <= 0) return;
    const frag = document.createDocumentFragment();
    for (const l of live.slice(-fresh)) frag.appendChild(hcpLineElement(l.text, l.level, l.ts));
    box.querySelector(".hcp-log-empty")?.remove();
    box.appendChild(frag);
    hcpRenderedTotal = total;
    const extra = box.childElementCount - HCP_MAX_LINES;
    for (let i = 0; i < extra; i++) box.firstElementChild?.remove();
  } else {
    const lines = Array.isArray(fileLines) ? fileLines : [];
    const sig = `${key}\n${lines.join("\n")}`;
    if (key === hcpRenderedKey && sig === hcpRenderedFileSig) return;
    hcpRenderedKey = key;
    hcpRenderedFileSig = sig;
    hcpRenderedTotal = 0;
    box.textContent = "";
    if (!lines.length) {
      const empty = document.createElement("div");
      empty.className = "hcp-log-empty";
      empty.textContent = "Esperando que se lance el juego...";
      box.appendChild(empty);
      return;
    }
    const frag = document.createDocumentFragment();
    for (const l of lines.slice(-HCP_MAX_LINES)) frag.appendChild(hcpLineElement(l, "", 0));
    box.appendChild(frag);
  }
  if (atBottom) box.scrollTop = box.scrollHeight;
}

async function updateHomeConsolePreview() {
  const inst = currentHomeInstance();
  if (!inst || !inst.path) return;
  if (el.homeConsolePreviewDock) el.homeConsolePreviewDock.classList.remove("hidden");
  let status = null;
  // Instances launched from here stream their output live; the others (or a game
  // started from another launcher) fall back to the tail of latest.log.
  if (!gameLogBuffers.has(normInstancePath(inst.path))) {
    try {
      status = await invoke("get_instance_log_status", { instancePath: inst.path });
    } catch {
      status = null;
    }
  }
  renderHcpState(status?.state);
  const showFile = status && (status.state !== "idle" || hasUserTriggeredLaunch);
  renderHcpTerminal(inst, showFile ? status.last_lines : null);
}

