function getServersList() {
  try {
    const custom = JSON.parse(localStorage.getItem("mc_custom_servers") || "[]");
    return [...DEFAULT_SERVERS, ...custom];
  } catch {
    return [...DEFAULT_SERVERS];
  }
}

function saveCustomServers(servers) {
  try {
    localStorage.setItem("mc_custom_servers", JSON.stringify(servers));
  } catch {}
}

function renderServersView() {
  if (!el.servidoresCardsGrid) return;
  const servers = getServersList();
  const q = (el.inputSearchServers?.value || "").toLowerCase().trim();

  const filtered = servers.filter((s) => {
    if (!q) return true;
    return s.name.toLowerCase().includes(q) || s.ip.toLowerCase().includes(q) || s.category.toLowerCase().includes(q);
  });

  if (filtered.length === 0) {
    el.servidoresCardsGrid.innerHTML = `
      <div class="empty-state-large" style="grid-column: 1 / -1; text-align: center; padding: 40px; color: #94a3b8;">
        No se encontraron servidores que coincidan con "${q}".
      </div>
    `;
    return;
  }

  el.servidoresCardsGrid.innerHTML = filtered.map((s) => {
    return `
      <div class="server-card" data-server-id="${s.id}">
        <div class="server-card-top">
          <div class="server-icon">${s.icon || "🌐"}</div>
          <div class="server-info">
            <div class="server-name" title="${s.name}">${s.name}</div>
            <div class="server-tags-row">
              <span class="server-tag">${s.version || "1.20.1"}</span>
              <span class="server-tag">${s.category || "Multijugador"}</span>
            </div>
          </div>
        </div>

        <div class="server-card-meta">
          <div class="server-ip-box">
            <span>${s.ip}</span>
            <button type="button" class="btn-copy-ip" data-ip="${s.ip}" title="Copiar IP del servidor">
              <svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2">
                <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
              </svg>
              <span>Copiar</span>
            </button>
          </div>
          <div class="server-status-pill">
            <span class="server-status-dot"></span>
            <span>${s.online ? `${s.online} jugadores` : "En línea"}</span>
          </div>
        </div>

        <div class="server-card-actions">
          <button type="button" class="btn-server-join" data-ip="${s.ip}">
            <svg viewBox="0 0 24 24" width="13" height="13" fill="currentColor">
              <polygon points="5 3 19 12 5 21 5 3"></polygon>
            </svg>
            <span>Conectar / Jugar</span>
          </button>
          ${s.custom ? `
            <button type="button" class="btn-server-del" data-id="${s.id}" title="Eliminar servidor">
              <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2">
                <polyline points="3 6 5 6 21 6"></polyline>
                <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
              </svg>
            </button>
          ` : ""}
        </div>
      </div>
    `;
  }).join("");

  // Attach event listeners for copy IP
  el.servidoresCardsGrid.querySelectorAll(".btn-copy-ip").forEach((btn) => {
    btn.addEventListener("click", async (e) => {
      e.stopPropagation();
      const ip = btn.dataset.ip;
      if (!ip) return;
      try {
        await navigator.clipboard.writeText(ip);
        showToast(`IP copiada al portapapeles: ${ip}`);
        const span = btn.querySelector("span");
        if (span) {
          const old = span.textContent;
          span.textContent = "¡Copiado!";
          setTimeout(() => { span.textContent = old; }, 1500);
        }
      } catch {
        showToast(`IP: ${ip}`);
      }
    });
  });

  // Attach event listeners for connect/play
  el.servidoresCardsGrid.querySelectorAll(".btn-server-join").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const ip = btn.dataset.ip;
      if (!ip) return;
      try {
        await navigator.clipboard.writeText(ip);
      } catch {}
      showToast(`IP ${ip} copiada. Iniciando Minecraft...`);
      handlePlayGame();
    });
  });

  // Attach event listeners for delete custom server
  el.servidoresCardsGrid.querySelectorAll(".btn-server-del").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const id = btn.dataset.id;
      if (!id) return;
      let custom = [];
      try {
        custom = JSON.parse(localStorage.getItem("mc_custom_servers") || "[]");
      } catch {}
      custom = custom.filter((s) => s.id !== id);
      saveCustomServers(custom);
      showToast("Servidor eliminado");
      renderServersView();
    });
  });
}

// Dock menu (three dots): copy or remove the instance selected in Inicio.
async function duplicateHomeInstance() {
  const inst = currentHomeInstance();
  if (!inst) return;
  const name = inst.name || inst.folder_name || "Instancia";
  showToast(`Duplicando ${name}...`);
  try {
    const copyPath = await invoke("duplicate_instance", { instancePath: inst.path });
    await reloadAllHomeInstances();
    const copyFolder = copyPath.split(/[\\/]/).filter(Boolean).pop().toLowerCase();
    const idx = homeInstancesList.findIndex(
      (i) => normInstancePath(i.path) === normInstancePath(copyPath) || (i.folder_name || "").toLowerCase() === copyFolder,
    );
    if (idx !== -1) switchHomeInstance(idx);
    showToast(`Instancia duplicada: ${idx !== -1 ? homeInstancesList[idx].name : `${name} (copia)`}`);
  } catch (err) {
    showToast(`No se pudo duplicar: ${err}`);
  }
}

async function deleteHomeInstance() {
  const inst = currentHomeInstance();
  if (!inst) return;
  const name = inst.name || inst.folder_name || "Instancia";
  if (isInstanceGameActive(inst.path)) {
    showToast("Cierra el juego antes de eliminar la instancia");
    return;
  }
  const confirmed = await showConfirmDialog({
    title: "ELIMINAR INSTANCIA",
    message: "¿Seguro que quieres eliminar esta instancia? Dejará de aparecer en todo el launcher.",
    itemTitle: name,
    itemImage: getInstanceCoverUrl(inst, homeCurrentInstanceIndex),
    itemDesc: `${inst.loader || "Vanilla"} · Minecraft ${inst.mc_version || "?"}`,
    confirmText: "Eliminar instancia",
    warnText: "Se mueve a la papelera del launcher con sus mundos, mods y configuración: desde esa carpeta se puede recuperar.",
  });
  if (!confirmed) return;
  try {
    await invoke("trash_instance", { instancePath: inst.path });
    await reloadAllHomeInstances();
    showToast(`${name} se movió a la papelera del launcher`);
  } catch (err) {
    showToast(`No se pudo eliminar: ${err}`);
  }
}

// Dock menu: opens one of the game folders of the instance selected in Inicio.
function openHomeInstanceFolder(folder, label) {
  const inst = resolveDockActiveInstance();
  if (!inst || (!inst.mods_path && !inst.path)) return;
  const gameDir = inst.mods_path ? inst.mods_path.replace(/[\\/]mods[\\/]?$/i, "") : inst.path;
  invoke("open_browser", { url: `${gameDir}\\${folder}` }).catch(() =>
    showToast(`La carpeta de ${label} todavía no existe: se crea al jugar una vez`),
  );
}

// Dock menu: force-closes the running game of the instance selected in Inicio.
async function stopHomeInstanceGame() {
  const inst = currentHomeInstance();
  if (!inst) return;
  const confirmed = await showConfirmDialog({
    title: "DETENER JUEGO",
    message: `Se cerrará Minecraft (${inst.name || inst.folder_name || "esta instancia"}) de inmediato.`,
    confirmText: "Detener juego",
    warnText: "Lo que el juego todavía no haya guardado (los últimos avances del mundo) se puede perder.",
  });
  if (!confirmed) return;
  try {
    await invoke("stop_game", { instancePath: inst.path });
    showToast("Juego detenido");
  } catch (err) {
    showToast(`No se pudo detener el juego: ${err}`);
  }
}

function startInstanceRename() {
  if (!el.inputInstanceRename || !el.homeInstanceTitle) return;
  if (el.instanceNameBox) el.instanceNameBox.classList.add("is-renaming");
  el.inputInstanceRename.value = el.homeInstanceTitle.textContent.trim();
  el.homeInstanceTitle.classList.add("hidden");
  el.inputInstanceRename.classList.remove("hidden");
  el.inputInstanceRename.focus();
  el.inputInstanceRename.select();
}

function cancelInstanceRename() {
  if (!el.inputInstanceRename || !el.homeInstanceTitle) return;
  if (el.instanceNameBox) el.instanceNameBox.classList.remove("is-renaming");
  el.inputInstanceRename.classList.add("hidden");
  el.homeInstanceTitle.classList.remove("hidden");
}

async function finishInstanceRename() {
  if (!el.inputInstanceRename || el.inputInstanceRename.classList.contains("hidden")) return;
  if (el.instanceNameBox) el.instanceNameBox.classList.remove("is-renaming");
  const newName = el.inputInstanceRename.value.trim();
  const currentInst = homeInstancesList[homeCurrentInstanceIndex];

  if (newName && currentInst) {
    saveCustomInstanceName(currentInst.path, newName);
    currentInst.name = newName;
    if (el.homeInstanceTitle) el.homeInstanceTitle.textContent = newName;
    if (el.homeChipName) el.homeChipName.textContent = newName;
    renderHomeInstanceCarousel();

    // Call Rust to persist in instance.cfg if available
    invoke("rename_instance", { instancePath: currentInst.path, newName: newName }).catch(() => {});
    showToast(`Nombre cambiado a: ${newName}`);
  }

  el.inputInstanceRename.classList.add("hidden");
  if (el.homeInstanceTitle) el.homeInstanceTitle.classList.remove("hidden");
}

