const CF_API_KEY = "REMOVED_CF_API_KEY";
const onlineInfoCache = new Map();

// Helper to deduplicate dependencies cleanly (e.g. "tctcore" vs "TCT Core")
function addNormalizedDependency(depMap, rawName) {
  if (!rawName) return;
  let trimmed = String(rawName).trim();
  const lower = trimmed.toLowerCase();
  if (lower === "minecraft" || lower === "forge" || lower === "neoforge" || lower === "java" || lower === "fml" || lower === "quilt_loader") {
    return;
  }

  // Known canonical display titles
  if (lower === "tctcore" || lower === "tct-core" || lower === "tct_core") trimmed = "TCT Core";
  else if (lower === "architectury" || lower === "architectury-api" || lower === "architecturyapi") trimmed = "Architectury API";
  else if (lower === "mcpitanlib") trimmed = "MCPitanLib";
  else if (lower === "doapi" || lower === "letsdo") trimmed = "[Let's Do] API";
  else if (lower === "addonslib" || lower === "mcw") trimmed = "Macaw's AddonsLib";
  else if (lower === "yungsapi") trimmed = "YUNG's API";
  else if (lower === "citadel") trimmed = "Citadel";
  else if (lower === "moonlight") trimmed = "Moonlight Lib";
  else if (lower === "sophisticatedcore") trimmed = "Sophisticated Core";
  else if (lower === "balm" || lower === "balm-forge") trimmed = "Balm";
  else if (lower === "creativecore") trimmed = "CreativeCore";
  else if (lower === "framework") trimmed = "Framework";
  else if (lower === "hammerlib") trimmed = "HammerLib";
  else if (lower === "puzzleslib") trimmed = "Puzzles Lib";
  else if (lower === "supermartijn642scorelib") trimmed = "SuperMartijn642's Core Lib";
  else if (lower === "cupboard") trimmed = "Cupboard";
  else if (lower === "bookshelf") trimmed = "Bookshelf";
  else if (lower === "curios") trimmed = "Curios API";
  else if (lower === "cloth_config" || lower === "cloth-config") trimmed = "Cloth Config";
  else if (lower === "geckolib" || lower === "geckolib3") trimmed = "GeckoLib";
  else if (lower === "azurelib" || lower === "azurelibarmor" || lower === "azurelib-neo" || lower === "azurelibneo") trimmed = "AzureLib";

  const normKey = trimmed.toLowerCase().replace(/[^a-z0-9]/g, "");
  if (!normKey) return;

  if (depMap.has(normKey)) {
    const existing = depMap.get(normKey);
    const scoreExisting = (existing.includes(" ") ? 4 : 0) + (/[A-Z]/.test(existing) ? 2 : 0) + existing.length;
    const scoreNew = (trimmed.includes(" ") ? 4 : 0) + (/[A-Z]/.test(trimmed) ? 2 : 0) + trimmed.length;
    if (scoreNew > scoreExisting) {
      depMap.set(normKey, trimmed);
    }
  } else {
    depMap.set(normKey, trimmed);
  }
}

function extractCommandsAndFeaturesFromMarkdown(text) {
  if (!text) return { commands: [], features: [] };
  const commands = [];
  const features = [];
  const lines = text.split("\n");

  const cmdLineRegex = /(?:^|[-*•▸`\s])(\/[a-zA-Z0-9_]{3,}(?:\s+[<\[][^>\]]+[>\]])?)(.*)/;
  const bulletRegex = /^[-*•▸]\s+(.+)/;

  let inFeatureSection = false;

  for (let line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;

    const lower = trimmed.toLowerCase();
    if (lower.includes("# feature") || lower.includes("característica") || lower.includes("features:") || lower.includes("características:")) {
      inFeatureSection = true;
      continue;
    }
    if (lower.startsWith("#") && inFeatureSection && !lower.includes("feature")) {
      inFeatureSection = false;
    }

    if (trimmed.includes("http://") || trimmed.includes("https://") || trimmed.includes(".com/") || trimmed.includes("github.com")) {
      continue;
    }

    const cmdMatch = trimmed.match(cmdLineRegex);
    if (cmdMatch) {
      let cleanCmd = trimmed.replace(/^[-*•▸`\s]+/, "").replace(/[`]+/g, "").trim();
      if (cleanCmd.startsWith("/") && cleanCmd.length > 3) {
        cleanCmd = cleanCmd
          .replace(/–/g, "-")
          .replace(/\s*-\s*Change the interval/i, " - Cambiar el intervalo de tiempo")
          .replace(/\s*-\s*Enable\/disable notifications/i, " - Activar/desactivar notificaciones")
          .replace(/\s*-\s*Enable or disable notifications/i, " - Activar o desactivar notificaciones")
          .replace(/\s*-\s*Clean entities/i, " - Limpiar entidades")
          .replace(/\s*-\s*Open config/i, " - Abrir menú de configuración")
          .replace(/\s*-\s*Opens GUI/i, " - Abre la interfaz gráfica");
        if (!commands.includes(cleanCmd) && commands.length < 8) {
          commands.push(cleanCmd);
        }
      }
    } else if (inFeatureSection && bulletRegex.test(trimmed)) {
      let feat = trimmed.replace(/^[-*•▸`\s]+/, "").replace(/[`]+/g, "").trim();
      if (feat.length > 6 && !features.includes(feat) && features.length < 6) {
        features.push(feat);
      }
    }
  }

  return { commands, features };
}

function getModNormalizedDeps(mod) {
  if (!mod) return [];
  const depMap = new Map();
  const rawDeps = mod.declared_dependencies || [];
  rawDeps.forEach((d) => {
    addNormalizedDependency(depMap, d);
  });

  const fnLower = (mod.filename || "").toLowerCase();
  const nameLower = (mod.display_name || "").toLowerCase();

  // Known hard requirements
  if (nameLower.includes("uncrafting table") || fnLower.includes("uncraftingtable")) {
    addNormalizedDependency(depMap, "Architectury API");
    addNormalizedDependency(depMap, "MCPitanLib");
  }
  if (nameLower.includes("super resolution") || fnLower.includes("super_resolution") || fnLower.includes("superresolution")) {
    addNormalizedDependency(depMap, "Architectury API");
    addNormalizedDependency(depMap, "Cloth Config");
  }
  if (fnLower.startsWith("letsdo-") || nameLower.includes("[let's do]")) {
    addNormalizedDependency(depMap, "Architectury API");
    if (!fnLower.includes("letsdo-api")) {
      addNormalizedDependency(depMap, "[Let's Do] API");
    }
  }
  if (nameLower.includes("clearlag") || fnLower.includes("clearlag")) {
    addNormalizedDependency(depMap, "TCT Core");
  }

  return Array.from(depMap.values());
}

function formatOfflineDeps(mod) {
  const deps = getModNormalizedDeps(mod);
  if (deps.length > 0) {
    return deps.join(", ");
  }
  return "No requiere dependencias adicionales";
}

// Fetch on-demand metadata from Modrinth and CurseForge
async function fetchModOnlineInfo(mod) {
  const cacheKey = (mod.sha1 && mod.sha1.length === 40) ? mod.sha1 : mod.clean_slug;
  if (onlineInfoCache.has(cacheKey)) {
    return onlineInfoCache.get(cacheKey);
  }

  const depMap = new Map();
  const localDeps = getModNormalizedDeps(mod);
  localDeps.forEach((d) => addNormalizedDependency(depMap, d));

  let modrinthCats = [];
  let curseforgeCats = [];
  let onlineCommands = [];
  let onlineFeatures = [];

  // 1. Modrinth Lookup via SHA-1
  if (mod.sha1 && mod.sha1.length === 40) {
    try {
      const resp = await fetch(`https://api.modrinth.com/v2/version_file/${mod.sha1}?algorithm=sha1`, {
        headers: { "User-Agent": "ModComparer/2.0" },
      });

      if (resp.ok) {
        const versionData = await resp.json();
        const requiredDeps = (versionData.dependencies || []).filter(
          (d) => d.dependency_type === "required" && d.project_id
        );

        if (requiredDeps.length > 0) {
          const projectIds = requiredDeps.map((d) => d.project_id);
          try {
            const projResp = await fetch(
              `https://api.modrinth.com/v2/projects?ids=${encodeURIComponent(JSON.stringify(projectIds))}`,
              { headers: { "User-Agent": "ModComparer/2.0" } }
            );
            if (projResp.ok) {
              const projects = await projResp.json();
              projects.forEach((p) => {
                const title = p.title || p.slug;
                if (title) addNormalizedDependency(depMap, title);
              });
            } else {
              projectIds.forEach((id) => addNormalizedDependency(depMap, id));
            }
          } catch (e) {
            projectIds.forEach((id) => addNormalizedDependency(depMap, id));
          }
        }

        if (versionData.project_id) {
          try {
            const pResp = await fetch(`https://api.modrinth.com/v2/project/${versionData.project_id}`, {
              headers: { "User-Agent": "ModComparer/2.0" },
            });
            if (pResp.ok) {
              const pData = await pResp.json();
              const cats = pData.categories || [];
              modrinthCats = cats.map((c) => MODRINTH_CAT_MAP[c] || c);
              if (pData.body) {
                const parsed = extractCommandsAndFeaturesFromMarkdown(pData.body);
                onlineCommands = parsed.commands;
                onlineFeatures = parsed.features;
              }
            }
          } catch (e) {}
        }
      }
    } catch (err) {}
  }

  // 2. CurseForge Lookup via Flame API
  try {
    const cfQuery = encodeURIComponent(mod.clean_slug.replace(/-/g, " "));
    const cfResp = await fetch(`https://api.curseforge.com/v1/mods/search?gameId=432&classId=6&searchFilter=${cfQuery}&pageSize=1`, {
      headers: {
        "x-api-key": CF_API_KEY,
        "Accept": "application/json",
      },
    });
    if (cfResp.ok) {
      const cfData = await cfResp.json();
      const firstMod = (cfData.data || [])[0];
      if (firstMod && firstMod.categories) {
        curseforgeCats = firstMod.categories.map((c) => CURSEFORGE_CAT_MAP[c.name] || c.name);
      }
    }
  } catch (err) {}

  // Format platforms summary
  const parts = [];
  if (modrinthCats.length > 0) {
    parts.push(`Modrinth: ${modrinthCats.slice(0, 3).join(", ")}`);
  }
  if (curseforgeCats.length > 0) {
    parts.push(`CurseForge: ${curseforgeCats.slice(0, 3).join(", ")}`);
  }

  const depText = depMap.size > 0 ? Array.from(depMap.values()).join(", ") : "No requiere dependencias adicionales";
  const platformsText = parts.length > 0 ? parts.join(" | ") : `Clasificación local: ${mod.category}`;
  const result = { deps: depText, platforms: platformsText, commands: onlineCommands, features: onlineFeatures };
  onlineInfoCache.set(cacheKey, result);
  return result;
}

function getCleanSearchQuery(mod) {
  if (!mod) return "";
  let name = (mod.display_name || mod.clean_slug || mod.filename || "").trim();

  // Strip trailing jar extensions
  name = name.replace(/\.jar(?:\.disabled)?$/i, "");
  // Strip trailing "(mod)", " mod", "-mod", "_mod", " addon", " forge", " fabric", " neoforge", " quilt"
  name = name.replace(/[\s\-_]+(?:\(mod\)|mod|addon|forge|fabric|neoforge|quilt)$/i, "").trim();

  const SPECIAL_QUERIES = {
    recipeessentials: "Recipe Essentials",
    "recipe essentials": "Recipe Essentials",
    structureessentials: "Structure Essentials",
    "structure essentials": "Structure Essentials",
    betterthirdperson: "Better Third Person",
    "better third person": "Better Third Person",
    afkcamera: "AFK Camera",
    "afk camera": "AFK Camera",
    cinematiccataclysm: "Cinematic Cataclysm",
    "cinematic cataclysm": "Cinematic Cataclysm",
    cinematiczoom: "Cinematic Zoom",
    "cinematic zoom": "Cinematic Zoom",
    cinematicrespawn: "Cinematic Respawn",
    "cinematic respawn": "Cinematic Respawn",
    immersiveui: "Immersive UI",
    "immersive ui": "Immersive UI",
    itemborders: "Item Borders",
    "item borders": "Item Borders",
    smoothswapping: "Smooth Swapping",
    "smooth swapping": "Smooth Swapping",
    uncraftingtable: "Uncrafting Table",
    "uncrafting table": "Uncrafting Table",
    modfixer: "ModFixer",
    chunky: "Chunky",
    fzzyconfig: "Fzzy Config",
    lithostitched: "Lithostitched",
    patchouli: "Patchouli",
    grandteleport: "Grand Teleport",
    simplevoicechat: "Simple Voice Chat",
    moogsstructures: "Moog's Structure Lib",
    "moogs structures": "Moog's Structure Lib",
    moogstructurelib: "Moog's Structure Lib",
    "moog structure lib": "Moog's Structure Lib",
    moogsvoyagerstructures: "Moog's Voyager Structures",
    "moogs voyager structures": "Moog's Voyager Structures",
  };

  const lower = name.toLowerCase().replace(/[-_]/g, " ").trim();
  const lowerNoSpace = lower.replace(/\s+/g, "");

  if (SPECIAL_QUERIES[lowerNoSpace]) {
    return SPECIAL_QUERIES[lowerNoSpace];
  }
  if (SPECIAL_QUERIES[lower]) {
    return SPECIAL_QUERIES[lower];
  }

  // If camelCase or PascalCase without spaces, split words
  if (!name.includes(" ") && /[a-z][A-Z]/.test(name)) {
    name = name.replace(/([a-z])([A-Z])/g, "$1 $2");
  }

  // If mod has a hyphenated clean_slug and name has no spaces
  if (!name.includes(" ") && mod.clean_slug && mod.clean_slug.includes("-")) {
    const fromSlug = mod.clean_slug
      .split("-")
      .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
      .join(" ");
    if (fromSlug.toLowerCase().replace(/\s+/g, "") === lowerNoSpace) {
      return fromSlug;
    }
  }

  return name;
}

async function handleSearchModrinth() {
  if (!state.selectedMod) return;
  const q = getCleanSearchQuery(state.selectedMod);
  const url = `https://modrinth.com/mods?q=${encodeURIComponent(q)}`;
  try {
    await invoke("open_browser", { url });
  } catch (e) {
    window.open(url, "_blank");
  }
}

async function handleSearchCurseForge() {
  if (!state.selectedMod) return;
  const q = getCleanSearchQuery(state.selectedMod);
  const url = `https://www.curseforge.com/minecraft/search?page=1&class=mc-mods&search=${encodeURIComponent(q)}`;
  try {
    await invoke("open_browser", { url });
  } catch (e) {
    window.open(url, "_blank");
  }
}

async function handleCopyAllMods() {
  let mods = [];
  if (state.currentView === "manager") {
    mods = getActiveManagerModsAndPath().mods || [];
  } else {
    mods = (state.mods1 && state.mods1.length > 0) ? state.mods1 : (state.mods2 || []);
  }

  if (!mods || mods.length === 0) {
    showToast("No hay mods cargados para copiar");
    return;
  }

  // Group by category respecting MANAGER_CATEGORY_ORDER
  const groups = new Map();
  MANAGER_CATEGORY_ORDER.forEach((cat) => groups.set(cat, []));

  mods.forEach((mod) => {
    const cat = mod.category || "General";
    if (!groups.has(cat)) {
      groups.set(cat, []);
    }
    const name = mod.display_name || mod.clean_slug || mod.filename;
    const fileInfo = mod.filename ? ` (${mod.filename})` : "";
    groups.get(cat).push(`${name}${fileInfo}`);
  });

  const sections = [];
  for (const [cat, list] of groups.entries()) {
    if (list.length > 0) {
      list.sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }));
      sections.push(`[${cat}]\n${list.join("\n")}`);
    }
  }

  const text = sections.join("\n\n");

  try {
    await navigator.clipboard.writeText(text);
    showToast(`Se copiaron ${mods.length} mods organizados por categoria`);
  } catch (err) {
    showToast("Error al copiar al portapapeles");
  }
}

async function handleCopyMissing() {
  const summaries = state.comparison.category_summaries || [];
  const missingMods = state.comparison.missing_in_2 || [];

  if (missingMods.length === 0) {
    if (!state.path1 || !state.path2) {
      showToast("Debes cargar ambas instancias primero");
    } else {
      showToast("No falta ningun mod en la Instancia 2");
    }
    return;
  }

  let text = `Mods faltantes en la nueva instancia (${missingMods.length}):\n\n`;

  summaries.forEach((summary) => {
    const activeMissing = summary.missing_mods;
    if (activeMissing.length > 0) {
      text += `[ ${summary.category} (${activeMissing.length}) ]\n`;
      activeMissing.forEach((m) => {
        text += `- ${m.display_name} (${m.filename})\n`;
      });
      text += "\n";
    }
  });

  try {
    await navigator.clipboard.writeText(text);
    showToast(`Se copiaron ${missingMods.length} mods faltantes organizados por categoria`);
  } catch (err) {
    showToast("Error al copiar al portapapeles");
  }
}

async function handleReset() {
  localStorage.removeItem("modcomparer_path1");
  localStorage.removeItem("modcomparer_path2");

  state.selectedCategory = "all";
  state.searchQuery = "";
  state.selectedMod = null;
  state.selectedModPaths.clear();
  state.lastSelectedMod = null;

  // Reset category pills
  el.categoryPills.querySelectorAll(".cat-pill").forEach((p, idx) => {
    p.classList.toggle("active", idx === 0);
  });

  el.globalSearch.value = "";
  el.clearGlobalSearch.classList.add("hidden");

  // Reset inspector dock & right panel
  if (el.inspectorDefaultMsg) el.inspectorDefaultMsg.classList.remove("hidden");
  if (el.inspectorDetails) el.inspectorDetails.classList.add("hidden");
  if (el.rightDefaultMsg) el.rightDefaultMsg.classList.remove("hidden");
  if (el.rightDetails) el.rightDetails.classList.add("hidden");

  const ok1 = await loadDirectory(1, DEFAULT_PATH_1);
  const ok2 = await loadDirectory(2, DEFAULT_PATH_2);
  if (ok1 && ok2) {
    await recompute();
  } else {
    renderCurrentView();
  }
  showToast("Restablecido a las instancias por defecto");
}

function showConfirmDialog({
  title = "ELIMINAR FONDO",
  message = "¿Estás seguro de que deseas eliminar este fondo permanentemente de tu disco y de Wallpaper Engine?",
  itemTitle = null,
  itemImage = null,
  itemDesc: itemDescText = "Se eliminará por completo del disco y de Wallpaper Engine.",
  confirmText = "Eliminar Definitivamente",
  cancelText = "Cancelar",
  warnText = "Esta acción no se puede deshacer. Se liberará el espacio en disco de inmediato.",
  tone = "danger", // "danger" (deletions) or "info" (optional improvements, violet, no trash icon)
} = {}) {
  return new Promise((resolve) => {
    const modal = document.getElementById("custom-confirm-modal");
    if (!modal) {
      resolve(true);
      return;
    }
    const iconEl = modal.querySelector(".custom-confirm-icon");
    const originalIcon = iconEl ? iconEl.innerHTML : "";
    modal.classList.toggle("is-info", tone === "info");
    if (tone === "info" && iconEl) {
      iconEl.innerHTML =
        '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#a78bfa" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/></svg>';
    }

    const titleEl = document.getElementById("custom-confirm-title");
    const msgEl = document.getElementById("custom-confirm-message");
    const itemBox = document.getElementById("custom-confirm-item-box");
    const itemImg = document.getElementById("custom-confirm-item-img");
    const itemName = document.getElementById("custom-confirm-item-name");
    const itemDesc = document.getElementById("custom-confirm-item-desc");
    const warnEl = document.getElementById("custom-confirm-warn-text");
    const btnConfirm = document.getElementById("custom-confirm-btn-confirm");
    const btnConfirmText = document.getElementById("custom-confirm-btn-confirm-text");
    const btnCancel = document.getElementById("custom-confirm-btn-cancel");
    const btnClose = document.getElementById("custom-confirm-close");

    if (titleEl) titleEl.textContent = title;
    if (msgEl) msgEl.textContent = message;
    if (warnEl) warnEl.textContent = warnText;
    if (btnConfirmText) btnConfirmText.textContent = confirmText;
    if (btnCancel) btnCancel.textContent = cancelText;

    if (itemTitle && itemBox) {
      itemBox.classList.remove("hidden");
      if (itemName) itemName.textContent = itemTitle;
      if (itemDesc) itemDesc.textContent = itemDescText;
      if (itemImage && itemImg) {
        itemImg.src = itemImage;
        itemImg.style.display = "block";
      } else if (itemImg) {
        itemImg.style.display = "none";
      }
    } else if (itemBox) {
      itemBox.classList.add("hidden");
    }

    modal.classList.remove("hidden");

    let isResolved = false;

    function cleanup(result) {
      if (isResolved) return;
      isResolved = true;
      modal.classList.add("hidden");
      modal.classList.remove("is-info");
      if (iconEl) iconEl.innerHTML = originalIcon;
      btnConfirm?.removeEventListener("click", onConfirm);
      btnCancel?.removeEventListener("click", onCancel);
      btnClose?.removeEventListener("click", onCancel);
      document.removeEventListener("keydown", onKeyDown);
      resolve(result);
    }

    function onConfirm(e) {
      if (e) {
        e.preventDefault();
        e.stopPropagation();
      }
      cleanup(true);
    }

    function onCancel(e) {
      if (e) {
        e.preventDefault();
        e.stopPropagation();
      }
      cleanup(false);
    }

    function onKeyDown(e) {
      if (e.key === "Escape") {
        onCancel(e);
      } else if (e.key === "Enter") {
        onConfirm(e);
      }
    }

    btnConfirm?.addEventListener("click", onConfirm);
    btnCancel?.addEventListener("click", onCancel);
    btnClose?.addEventListener("click", onCancel);
    document.addEventListener("keydown", onKeyDown);
  });
}

// =========================================================
// NOTIFICATION CENTER: bell in the title bar. It is only for requests from other players that
// wait for an answer: today, an instance someone wants to send (ikaShare). Everything else the
// launcher has to say (game ready or crashed, updates, downloads, results of a transfer) is
// quick feedback and stays in showToast. Kept in localStorage, newest first.
// =========================================================
const NOTIFY_KEY = "ika_notifications";
const NOTIFY_MAX = 60;
const NOTIFY_ICON = {
  success: '<path d="M5 12.5l4.5 4.5L19 7"/>',
  error: '<path d="M12 8v5M12 16.5h.01M10.3 3.9 2.4 17.5A2 2 0 0 0 4.1 20.5h15.8a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/>',
  update: '<path d="M20 11a8 8 0 0 0-14.6-4.5M4 4v4h4M4 13a8 8 0 0 0 14.6 4.5M20 20v-4h-4"/>',
  download: '<path d="M12 4v11M7.5 10.5 12 15l4.5-4.5M5 19h14"/>',
  info: '<path d="M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18zM12 11v5M12 7.5h.01"/>',
};
let notifications = [];
try {
  notifications = JSON.parse(localStorage.getItem(NOTIFY_KEY) || "[]");
  notifications = Array.isArray(notifications)
    ? notifications.filter((n) => n.shareId || n.type === "download")
    : [];
  // If app restarted while downloading, mark as completed so it does not stay spinning indefinitely
  notifications.forEach((n) => {
    if (n.type === "download" && n.status === "downloading") {
      n.status = "completed";
      n.progress = 100;
      if (!n.text || n.text.includes("...")) n.text = "Descarga completada";
    }
  });
} catch {
  notifications = [];
}

function saveNotifications() {
  try {
    localStorage.setItem(NOTIFY_KEY, JSON.stringify(notifications.slice(0, NOTIFY_MAX)));
  } catch {}
}

function ringNotifyBell() {
  const btn = document.getElementById("titlebar-btn-notify");
  if (btn) {
    btn.classList.remove("is-ringing");
    void btn.offsetWidth;
    btn.classList.add("is-ringing");
  }
}

function notify({ type = "info", title, text = "", shareId = null }) {
  if (!title) return;
  if (shareId && notifications.some((n) => n.shareId === shareId)) return;
  notifications.unshift({ id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, type, title, text, shareId, ts: Date.now(), read: false });
  notifications = notifications.slice(0, NOTIFY_MAX);
  saveNotifications();
  renderNotifications();
  ringNotifyBell();
}
window.ikaNotify = notify;

function startDownloadNotification({ id, title, text = "Iniciando descarga...", progress = null }) {
  const downloadId = id || `dl-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  let item = notifications.find((n) => n.id === downloadId);
  if (item) {
    item.title = title || item.title;
    item.text = text;
    item.progress = progress;
    item.status = "downloading";
    item.ts = Date.now();
    item.read = false;
  } else {
    item = {
      id: downloadId,
      type: "download",
      title: title || "Descarga",
      text,
      progress,
      status: "downloading",
      ts: Date.now(),
      read: false
    };
    notifications.unshift(item);
    notifications = notifications.slice(0, NOTIFY_MAX);
  }
  saveNotifications();
  renderNotifications();
  ringNotifyBell();

  return {
    id: downloadId,
    update: (p, t) => updateDownloadNotification(downloadId, p, t),
    finish: (t) => finishDownloadNotification(downloadId, t),
    error: (e) => failDownloadNotification(downloadId, e)
  };
}

function updateDownloadNotification(id, progress, text) {
  const item = notifications.find((n) => n.id === id);
  if (!item) return;
  if (typeof progress === "number") {
    item.progress = Math.min(100, Math.max(0, Math.round(progress)));
  }
  if (text) item.text = text;
  saveNotifications();
  renderNotifications();
}

function finishDownloadNotification(id, text = "Descarga completada") {
  const item = notifications.find((n) => n.id === id);
  if (!item) return;
  item.status = "completed";
  item.progress = 100;
  if (text) item.text = text;
  item.read = false;
  saveNotifications();
  renderNotifications();
  ringNotifyBell();
}

function failDownloadNotification(id, errorText = "Error en la descarga") {
  const item = notifications.find((n) => n.id === id);
  if (!item) return;
  item.status = "error";
  if (errorText) item.text = String(errorText);
  item.read = false;
  saveNotifications();
  renderNotifications();
  ringNotifyBell();
}

window.ikaDownloadNotify = {
  start: startDownloadNotification,
  update: updateDownloadNotification,
  finish: finishDownloadNotification,
  fail: failDownloadNotification,
};

// The invitation was answered (or withdrawn): its entry has nothing left to offer.
function dismissShareNotification(shareId) {
  if (!notifications.some((n) => n.shareId === shareId)) return;
  notifications = notifications.filter((n) => n.shareId !== shareId);
  saveNotifications();
  renderNotifications();
}

function formatNotifyTime(ts) {
  const s = Math.round((Date.now() - ts) / 1000);
  if (s < 60) return "ahora";
  if (s < 3600) return `hace ${Math.floor(s / 60)} min`;
  if (s < 86400) return `hace ${Math.floor(s / 3600)} h`;
  const d = Math.floor(s / 86400);
  return d === 1 ? "ayer" : `hace ${d} días`;
}

function renderNotifications() {
  const unread = notifications.filter((n) => !n.read).length;
  const badge = document.getElementById("titlebar-notify-badge");
  if (badge) {
    badge.hidden = unread === 0;
    badge.textContent = unread > 9 ? "9+" : String(unread);
  }
  const list = document.getElementById("notify-list");
  if (!list) return;
  list.innerHTML = notifications.length
    ? notifications
        .map(
          (n) => {
            const isDl = n.type === "download";
            let statusLabel = "";
            if (isDl) {
              if (n.status === "completed") statusLabel = "Completado";
              else if (n.status === "error") statusLabel = "Error";
              else statusLabel = "Descargando";
            }
            const iconSvg = n.status === "completed"
              ? NOTIFY_ICON.success
              : n.status === "error"
                ? NOTIFY_ICON.error
                : (NOTIFY_ICON[n.type] || NOTIFY_ICON.info);

            return `<div class="notify-item is-${n.type} ${n.read ? "" : "is-unread"} ${n.status ? `is-status-${n.status}` : ""}" data-id="${n.id}">
            <span class="notify-icon"><svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${iconSvg}</svg></span>
            <div class="notify-text">
              <div class="notify-item-head-row">
                <span class="notify-item-title">${escapeHtml(n.title)}</span>
                ${isDl ? `<span class="notify-tag notify-tag-dl ${n.status || 'downloading'}">${statusLabel}</span>` : ""}
              </div>
              ${n.text ? `<span class="notify-item-body">${escapeHtml(n.text)}</span>` : ""}
              ${isDl && n.status === "downloading" ? `
                <div class="notify-progress-wrap">
                  <div class="notify-progress-track">
                    <div class="notify-progress-fill ${n.progress == null ? 'is-indeterminate' : ''}" style="width: ${n.progress != null ? n.progress : 45}%;"></div>
                  </div>
                  ${n.progress != null ? `<span class="notify-progress-pct">${n.progress}%</span>` : ''}
                </div>
              ` : ""}
              ${
                n.shareId
                  ? `<div class="notify-actions-row">
                      <button type="button" class="notify-action notify-action-accept" data-share-accept="${escapeHtml(n.shareId)}">Aceptar</button>
                      <button type="button" class="notify-action notify-action-decline" data-share-decline="${escapeHtml(n.shareId)}">Rechazar</button>
                    </div>`
                  : ""
              }
              <span class="notify-time">${formatNotifyTime(n.ts)}</span>
            </div>
            <button type="button" class="notify-dismiss" data-dismiss="${n.id}" aria-label="Quitar notificación">✕</button>
          </div>`;
          }
        )
        .join("")
    : `<div class="notify-empty"><svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/></svg><span>No hay notificaciones ni descargas</span></div>`;
}

function setNotifyPanelOpen(open) {
  const panel = document.getElementById("notify-panel");
  const btn = document.getElementById("titlebar-btn-notify");
  if (!panel || !btn) return;
  panel.classList.toggle("hidden", !open);
  btn.classList.toggle("is-open", open);
  btn.setAttribute("aria-expanded", open ? "true" : "false");
  if (open) {
    window.ikaShare?.checkNow?.();
    renderNotifications();
  } else if (notifications.some((n) => !n.read)) {
    // what was on screen counts as seen once the panel closes
    notifications.forEach((n) => (n.read = true));
    saveNotifications();
    renderNotifications();
  }
}

function initNotificationCenter() {
  const btn = document.getElementById("titlebar-btn-notify");
  const panel = document.getElementById("notify-panel");
  if (!btn || !panel) return;
  renderNotifications();
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    setNotifyPanelOpen(panel.classList.contains("hidden"));
  });
  panel.addEventListener("click", (e) => {
    e.stopPropagation();
    const acceptBtn = e.target.closest("[data-share-accept]");
    if (acceptBtn) {
      setNotifyPanelOpen(false);
      window.ikaShare?.accept(acceptBtn.dataset.shareAccept);
      return;
    }
    const declineBtn = e.target.closest("[data-share-decline]");
    if (declineBtn) {
      window.ikaShare?.decline(declineBtn.dataset.shareDecline);
      return;
    }
    const share = e.target.closest("[data-share]");
    if (share) {
      setNotifyPanelOpen(false);
      window.ikaShare?.open(share.dataset.share);
      return;
    }
    const dismiss = e.target.closest("[data-dismiss]");
    if (dismiss) {
      const item = notifications.find((n) => n.id === dismiss.dataset.dismiss);
      if (item?.shareId) {
        window.ikaShare?.decline(item.shareId);
      }
      notifications = notifications.filter((n) => n.id !== dismiss.dataset.dismiss);
      saveNotifications();
      renderNotifications();
    }
  });
  document.getElementById("notify-read-all")?.addEventListener("click", () => {
    notifications.forEach((n) => (n.read = true));
    saveNotifications();
    renderNotifications();
  });
  document.getElementById("notify-clear")?.addEventListener("click", () => {
    notifications = [];
    saveNotifications();
    renderNotifications();
  });
  document.addEventListener("pointerdown", (e) => {
    if (panel.classList.contains("hidden") || e.target.closest("#notify-panel, #titlebar-btn-notify")) return;
    setNotifyPanelOpen(false);
  });
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && !panel.classList.contains("hidden")) setNotifyPanelOpen(false);
  });
  // relative times ("hace 3 min") stay current while the panel is open
  setInterval(() => !panel.classList.contains("hidden") && renderNotifications(), 30000);
}

function showToast(_msg) {
  if (el.toast) el.toast.classList.add("hidden");
}

function escapeHtml(str) {
  if (!str) return "";
  return str
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function parseCommandEntry(rawStr) {
  if (!rawStr) return null;
  const s = String(rawStr).trim();

  // 1. Format: "/command (description)" or "/command [description]"
  let match = s.match(/^(\/[a-zA-Z0-9_\-:]+(?:\s+[<\[][^>\]]+[>\]]|\s+--[a-zA-Z0-9_\-]+|\s+[a-zA-Z0-9_\-]+)*)\s*[\(\[]([^\)\]]+)[\)\]]$/);
  if (match) {
    return {
      command: match[1].trim(),
      description: match[2].trim(),
    };
  }

  // 2. Format: "/command (alias): description" or "/command: description" or "/command - description" or "/command – description"
  match = s.match(/^(\/[a-zA-Z0-9_\-:]+(?:\s+[<\[][^>\]]+[>\]]|\s+--[a-zA-Z0-9_\-]+|\s+[a-zA-Z0-9_\-]+)*)(?:\s*\(([^)]+)\))?\s*[:\-–]\s*(.+)$/);
  if (match) {
    let cmd = match[1].trim();
    let alias = match[2];
    let desc = match[3].trim();
    if (alias) {
      desc = `${desc} (${alias})`;
    }
    return {
      command: cmd,
      description: desc,
    };
  }

  // 3. Format: "description: /command"
  match = s.match(/^([^:]+)[:\-–]\s*(\/[a-zA-Z0-9_\-:]+.*)$/);
  if (match && !match[1].startsWith("/")) {
    return {
      command: match[2].trim(),
      description: match[1].trim(),
    };
  }

  // 4. Any string starting with slash: "/command something"
  if (s.startsWith("/")) {
    const delimMatch = s.match(/^(\/[^\-–:\(]+)[\-–:\(]\s*(.+)$/);
    if (delimMatch) {
      let desc = delimMatch[2].replace(/[\)\]]$/, "").trim();
      return {
        command: delimMatch[1].trim(),
        description: desc,
      };
    }
    return {
      command: s,
      description: "Ejecuta esta función en el juego",
    };
  }

  // 5. Keybinding format: "Tecla 'X': Description"
  match = s.match(/^(Tecla\s+['"]?[^'"]+['"]?)\s*[:\-–]\s*(.+)$/i);
  if (match) {
    return {
      command: match[1].trim(),
      description: match[2].trim(),
      isKeybind: true,
    };
  }

  // 6. Passive or generic text
  if (s.toLowerCase().includes("pasivo")) {
    return {
      command: "Mod Pasivo",
      description: s.replace(/^Mod\s+pasivo\s*[:\-–]?\s*/i, "") || "Funciona automáticamente en segundo plano.",
      isPassive: true,
    };
  }

  return {
    command: s,
    description: "Información",
  };
}

function renderCommandsHtml(commandsList) {
  if (!commandsList || commandsList.length === 0) return "";
  return commandsList
    .map((raw) => {
      const parsed = parseCommandEntry(raw);
      if (!parsed) return "";
      const descHtml = escapeHtml(parsed.description);
      const cmdHtml = escapeHtml(parsed.command);

      if (parsed.isPassive) {
        return `
          <div class="insp-cmd-card">
            <div class="insp-cmd-desc">${descHtml}</div>
            <div class="insp-cmd-row">
              <span class="insp-cmd-code" style="color: #94a3b8; font-style: italic;">${cmdHtml}</span>
            </div>
          </div>
        `;
      }

      return `
        <div class="insp-cmd-card">
          <div class="insp-cmd-desc">${descHtml}</div>
          <div class="insp-cmd-row">
            <code class="insp-cmd-code">${cmdHtml}</code>
            <button class="btn-copy-cmd" data-cmd="${cmdHtml}" title="Copiar comando">
              <svg class="cmd-copy-icon" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
                <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
              </svg>
              <span class="cmd-copy-label">Copiar</span>
            </button>
          </div>
        </div>
      `;
    })
    .join("");
}

// =========================================================
// GESTOR DE INSTANCIA
// =========================================================
function getInstanceNameFromPath(p) {
  if (!p) return "Instancia";
  const clean = p.replace(/\\/g, "/").replace(/\/+$/, "");
  const parts = clean.split("/");
  const last = parts[parts.length - 1];
  if (last.toLowerCase() === "mods" && parts.length >= 2) {
    const prev = parts[parts.length - 2];
    if ((prev.toLowerCase() === "minecraft" || prev.toLowerCase() === ".minecraft") && parts.length >= 3) {
      return parts[parts.length - 3];
    }
    return prev;
  }
  return last || "Instancia";
}

function switchManagerInstance(instId) {
  state.managerInstance = instId;
  state.selectedModPaths.clear();
  state.lastSelectedMod = null;
  renderViewManager();
}

async function handleManagerSelectCustom() {
  try {
    const selected = await invoke("pick_folder");
    if (!selected) return;
    const res = await invoke("scan_directory", { path: selected });
    state.managerCustomPath = res.resolved_dir;
    state.managerCustomMods = res.mods;
    state.managerInstance = "custom";
    state.selectedModPaths.clear();
    state.lastSelectedMod = null;
    renderViewManager();
  } catch (err) {
    showToast("Error al seleccionar carpeta");
  }
}

function getActiveManagerModsAndPath() {
  if (state.managerInstance === "custom") {
    return { path: state.managerCustomPath, mods: state.managerCustomMods };
  }
  return { path: state.path1, mods: state.mods1 };
}

function updateModInState(oldMod, updatedMod) {
  const replaceInList = (list) => {
    if (!list) return;
    const idx = list.findIndex(
      (m) => m.filepath === oldMod.filepath || m.filename === oldMod.filename
    );
    if (idx !== -1) {
      list[idx] = updatedMod;
    }
  };
  replaceInList(state.mods1);
  replaceInList(state.mods2);
  replaceInList(state.managerCustomMods);

  // Keep state.comparison in sync without expensive pairwise recomputation
  if (state.comparison) {
    if (state.comparison.matches_1_to_2 && state.comparison.matches_1_to_2[oldMod.filepath]) {
      const match = state.comparison.matches_1_to_2[oldMod.filepath];
      delete state.comparison.matches_1_to_2[oldMod.filepath];
      state.comparison.matches_1_to_2[updatedMod.filepath] = match;
    }
    if (state.comparison.matches_2_to_1 && state.comparison.matches_2_to_1[oldMod.filepath]) {
      const match = state.comparison.matches_2_to_1[oldMod.filepath];
      delete state.comparison.matches_2_to_1[oldMod.filepath];
      state.comparison.matches_2_to_1[updatedMod.filepath] = match;
    }
    replaceInList(state.comparison.missing_in_2);
    if (state.comparison.category_summaries) {
      for (const s of state.comparison.category_summaries) {
        replaceInList(s.missing_mods);
      }
    }
  }

  if (
    state.selectedMod &&
    (state.selectedMod.filepath === oldMod.filepath || state.selectedMod.filename === oldMod.filename)
  ) {
    state.selectedMod = updatedMod;
  }
}

function removeModFromState(mod) {
  const removeFromList = (list) => {
    const idx = list.findIndex(
      (m) => m.filepath === mod.filepath || m.filename === mod.filename
    );
    if (idx !== -1) {
      list.splice(idx, 1);
    }
  };
  removeFromList(state.mods1);
  removeFromList(state.mods2);
  removeFromList(state.managerCustomMods);
}

const MANAGER_CATEGORY_ORDER = [
  "Rendimiento",
  "Mundo y Generación",
  "Calidad de Vida",
  "Interfaz",
  "Gráficos, Cámara y Animaciones",
  "Combate",
  "Contenido",
  "Construcción y Decoración",
  "Audio y Comunicación",
  "APIs y Dependencias",
];

function renderViewManager() {
  // The Gestor de Instancia view is drawn by its own module (window.ikaManager).
  if (!el.mgrModsContainer) return;
  const { path, mods } = getActiveManagerModsAndPath();
  const instName = getInstanceNameFromPath(path);
  if (el.mgrActiveName) {
    el.mgrActiveName.textContent = instName;
    el.mgrActiveName.title = path || instName;
  }
  if (el.mgrCurrentPath) {
    el.mgrCurrentPath.textContent = path || "Ninguna instancia seleccionada";
    el.mgrCurrentPath.title = path || "Ninguna instancia seleccionada";
  }

  const total = mods.length;
  const activeCount = mods.filter((m) => !m.is_disabled).length;
  const disabledCount = mods.filter((m) => m.is_disabled).length;

  if (el.mgrCntAll) el.mgrCntAll.textContent = total;
  if (el.mgrCntActive) el.mgrCntActive.textContent = activeCount;
  if (el.mgrCntDisabled) el.mgrCntDisabled.textContent = disabledCount;

  if (!path || mods.length === 0) {
    if (el.mgrModsContainer) {
      el.mgrModsContainer.innerHTML = `
        <div class="empty-state-large">
          No hay mods cargados en esta instancia.
        </div>
      `;
    }
    updateBatchBarUI([]);
    return;
  }

  // Filter
  let filtered = mods.filter((mod) => {
    if (state.selectedCategory !== "all" && mod.category !== state.selectedCategory) return false;
    if (state.managerFilter === "active" && mod.is_disabled) return false;
    if (state.managerFilter === "disabled" && !mod.is_disabled) return false;

    if (state.managerSearch) {
      const q = state.managerSearch;
      const match =
        mod.display_name.toLowerCase().includes(q) ||
        mod.filename.toLowerCase().includes(q) ||
        mod.description.toLowerCase().includes(q) ||
        mod.category.toLowerCase().includes(q) ||
        mod.tags.some((t) => t.toLowerCase().includes(q));
      if (!match) return false;
    }
    return true;
  });

  // Sort
  if (state.managerSort === "name") {
    filtered.sort((a, b) =>
      a.display_name.toLowerCase().localeCompare(b.display_name.toLowerCase())
    );
  } else if (state.managerSort === "active-first") {
    filtered.sort((a, b) => (a.is_disabled === b.is_disabled ? 0 : a.is_disabled ? 1 : -1));
  } else if (state.managerSort === "disabled-first") {
    filtered.sort((a, b) => (a.is_disabled === b.is_disabled ? 0 : a.is_disabled ? -1 : 1));
  } else if (state.managerSort === "category") {
    filtered.sort((a, b) => a.category.localeCompare(b.category));
  } else if (state.managerSort === "size") {
    filtered.sort((a, b) => b.size_str.localeCompare(a.size_str));
  }

  if (filtered.length === 0) {
    if (el.mgrModsContainer) {
      el.mgrModsContainer.innerHTML = `
        <div class="empty-state-large">
          No se encontraron mods con los filtros seleccionados.
        </div>
      `;
    }
    updateBatchBarUI(filtered);
    return;
  }

  if (!el.mgrModsContainer) return;
  el.mgrModsContainer.innerHTML = "";

  // Group by category
  const groupsMap = new Map();
  filtered.forEach((mod) => {
    const cat = mod.category || "General";
    if (!groupsMap.has(cat)) groupsMap.set(cat, []);
    groupsMap.get(cat).push(mod);
  });

  const orderedCats = [];
  MANAGER_CATEGORY_ORDER.forEach((cat) => {
    if (groupsMap.has(cat)) orderedCats.push(cat);
  });
  for (const cat of groupsMap.keys()) {
    if (!orderedCats.includes(cat)) orderedCats.push(cat);
  }

  orderedCats.forEach((catName) => {
    const catMods = groupsMap.get(catName);
    if (!catMods || catMods.length === 0) return;

    const groupEl = document.createElement("div");
    groupEl.className = `category-group ${getCategoryClass(catName)}`;

    const activeMods = catMods.filter((m) => !m.is_disabled);
    const disabledMods = catMods.filter((m) => m.is_disabled);

    // Sort within subgroups
    const sortFn = (a, b) => {
      if (state.managerSort === "size") {
        return b.size_str.localeCompare(a.size_str);
      }
      return a.display_name.toLowerCase().localeCompare(b.display_name.toLowerCase());
    };

    activeMods.sort(sortFn);
    disabledMods.sort(sortFn);

    const headerEl = document.createElement("div");
    headerEl.className = "category-header";
    headerEl.innerHTML = `
      <div class="cat-title-left">
        <span class="cat-name">${escapeHtml(catName)}</span>
        <span class="cat-badge-count">${catMods.length} mods</span>
        ${
          activeMods.length > 0 && disabledMods.length > 0
            ? `<span class="cat-badge-breakdown">
                <span class="badge-act">${activeMods.length} activos</span>
                <span class="badge-sep">·</span>
                <span class="badge-dis">${disabledMods.length} desactivados</span>
              </span>`
            : ""
        }
      </div>
      <div class="cat-title-right">
        <button class="btn-copy-cat-icon" title="Copiar lista de mods" data-cat="${escapeHtml(catName)}">
          <svg viewBox="0 0 24 24" width="16" height="16" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round">
            <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
            <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
          </svg>
        </button>
      </div>
    `;

    headerEl.querySelector(".btn-copy-cat-icon").addEventListener("click", async (e) => {
      e.stopPropagation();
      const text = catMods.map((m) => m.display_name).join("\n");
      try {
        await navigator.clipboard.writeText(text);
        showToast(`Se copiaron los ${catMods.length} nombres de mods de ${catName}`);
      } catch (err) {
        showToast("Error al copiar al portapapeles");
      }
    });

    groupEl.appendChild(headerEl);

    // Sections order: active first by default, or disabled first if chosen
    const sections = state.managerSort === "disabled-first"
      ? [
          { type: "disabled", mods: disabledMods, label: "MODS DESACTIVADOS" },
          { type: "active", mods: activeMods, label: "MODS ACTIVOS" },
        ]
      : [
          { type: "active", mods: activeMods, label: "MODS ACTIVOS" },
          { type: "disabled", mods: disabledMods, label: "MODS DESACTIVADOS" },
        ];

    sections.forEach((sec) => {
      if (sec.mods.length === 0) return;

      const subHeader = document.createElement("div");
      subHeader.className = `mgr-subgroup-header ${sec.type}-mods`;
      subHeader.innerHTML = `
        <span class="subgroup-dot ${sec.type}"></span>
        <span class="subgroup-title">${escapeHtml(sec.label)}</span>
        <span class="subgroup-count">${sec.mods.length}</span>
      `;
      groupEl.appendChild(subHeader);

      const gridEl = document.createElement("div");
      gridEl.className = "category-items-grid";

      sec.mods.forEach((mod) => {
        const card = createManagerModCard(mod, filtered);
        gridEl.appendChild(card);
      });

      groupEl.appendChild(gridEl);
    });

    el.mgrModsContainer.appendChild(groupEl);
  });

  updateBatchBarUI(filtered);
}

function createManagerModCard(mod, allVisibleMods) {
  const card = document.createElement("div");
  const isSelected = state.selectedModPaths.has(mod.filepath);
  card.className = `mgr-mod-card ${getCategoryClass(mod.category)} ${mod.is_disabled ? "is-disabled" : ""} ${isSelected ? "selected" : ""}`;
  card.dataset.filepath = mod.filepath;
  card._mod = mod;

  const statusBadge = mod.is_disabled
    ? `<span class="mgr-status-tag disabled">DESACTIVADO</span>`
    : `<span class="mgr-status-tag active">ACTIVO</span>`;

  let servingTag = "";
  if (mod.is_api || mod.category === "APIs y Dependencias" || mod.category === "Dependencias" || mod.category === "API") {
    const { mods: allCurrentMods } = getActiveManagerModsAndPath();
    const served = getModsServedByApi(mod, allCurrentMods);
    if (served.length > 0) {
      servingTag = `<span class="mgr-serving-tag" title="Usado por ${served.length} mods instalados">Sirve a ${served.length} ${served.length === 1 ? "mod" : "mods"}</span>`;
    } else {
      servingTag = `<span class="mgr-serving-tag mgr-serving-tag-empty" title="Ningún mod instalado depende de esta dependencia">Sin dependientes</span>`;
    }
  }

  const toggleBtnText = mod.is_disabled ? "Activar" : "Desactivar";
  const toggleBtnClass = mod.is_disabled ? "btn-cyan" : "btn-secondary";

  const initials = getInitials(mod.display_name);

  card.innerHTML = `
    <div class="mgr-card-header">
      <div class="mod-icon-box ${getCategoryClass(mod.category)}">
        <img class="mod-icon-img hidden" alt="" />
        <span class="mod-icon-ph">${escapeHtml(initials)}</span>
      </div>
      <div class="mgr-card-title-group">
        <span class="mgr-card-title" title="${escapeHtml(mod.display_name)}">${escapeHtml(mod.display_name)}</span>
        <span class="mgr-card-filename" title="${escapeHtml(mod.filename)}">${escapeHtml(mod.filename)}</span>
      </div>
      <div class="mgr-card-badges">
        ${statusBadge}
        ${servingTag}
      </div>
    </div>
    <p class="mgr-card-desc">${escapeHtml(mod.description)}</p>
    <div class="mgr-card-footer">
      <span class="mgr-card-meta">${escapeHtml(mod.size_str)}</span>
      <span class="mgr-card-quick-hint">···</span>
    </div>
    <div class="mgr-action-dock">
      <button class="mgr-dock-btn dock-btn-wiki" title="Cambiar versión de este mod">
        <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <path d="M20.59 13.41l-7.17 7.17a2 2 0 0 1-2.83 0L2 12V2h10l8.59 8.59a2 2 0 0 1 0 2.82z"></path>
          <line x1="7" y1="7" x2="7.01" y2="7"></line>
        </svg>
        <span>Cambiar versión</span>
      </button>
      <button class="mgr-dock-btn dock-btn-toggle ${mod.is_disabled ? 'is-disabled-state' : 'is-active-state'}" title="${mod.is_disabled ? 'Habilitar este mod' : 'Deshabilitar este mod'}">
        <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <path d="M18.36 6.64a9 9 0 1 1-12.73 0"></path>
          <line x1="12" y1="2" x2="12" y2="12"></line>
        </svg>
        <span>${toggleBtnText}</span>
      </button>
      <button class="mgr-dock-btn dock-btn-delete" title="Eliminar archivo .jar del disco">
        <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <polyline points="3 6 5 6 21 6"></polyline>
          <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path>
        </svg>
        <span>Borrar</span>
      </button>
    </div>
  `;

  const imgEl = card.querySelector(".mod-icon-img");
  const phEl = card.querySelector(".mod-icon-ph");
  queueModIcon(mod, imgEl, phEl);

  card.querySelector(".dock-btn-wiki").addEventListener("click", (e) => {
    e.stopPropagation();
    handleModSelect(
      mod,
      card,
      mod.is_disabled ? "status-missing" : "status-covered",
      mod.is_disabled ? "Desactivado" : "Activo"
    );
  });

  card.querySelector(".dock-btn-toggle").addEventListener("click", async (e) => {
    e.stopPropagation();
    await handleToggleModDisabled(mod);
  });

  card.querySelector(".dock-btn-delete").addEventListener("click", (e) => {
    e.stopPropagation();
    handleDeleteMod(mod);
  });

  card.addEventListener("click", (e) => {
    handleModCardSelection(e, mod, card, allVisibleMods);
  });

  return card;
}

function handleModCardSelection(e, mod, card, allVisibleMods) {
  const sel = window.getSelection ? window.getSelection() : null;
  if (sel && sel.toString().trim().length > 0) {
    return;
  }

  if (e.shiftKey && state.lastSelectedMod) {
    const allCards = Array.from(document.querySelectorAll(".mgr-mod-card"));
    const idx1 = allCards.findIndex((c) => c.dataset.filepath === state.lastSelectedMod.filepath);
    const idx2 = allCards.findIndex((c) => c.dataset.filepath === mod.filepath);
    if (idx1 !== -1 && idx2 !== -1) {
      if (!e.ctrlKey && !e.metaKey) {
        state.selectedModPaths.clear();
      }
      const [start, end] = idx1 < idx2 ? [idx1, idx2] : [idx2, idx1];
      for (let i = start; i <= end; i++) {
        state.selectedModPaths.add(allCards[i].dataset.filepath);
      }
    }
  } else if (e.ctrlKey || e.metaKey) {
    if (state.selectedModPaths.has(mod.filepath)) {
      state.selectedModPaths.delete(mod.filepath);
    } else {
      state.selectedModPaths.add(mod.filepath);
      state.lastSelectedMod = mod;
    }
  } else {
    // Normal single click
    state.selectedModPaths.clear();
    state.selectedModPaths.add(mod.filepath);
    state.lastSelectedMod = mod;
  }

  // Update card selected visual states
  document.querySelectorAll(".mgr-mod-card").forEach((c) => {
    const p = c.dataset.filepath;
    c.classList.toggle("selected", state.selectedModPaths.has(p));
  });

  // If single mod selected, show in inspector and highlight reverse dependencies
  if (state.selectedModPaths.size === 1) {
    handleModSelect(
      mod,
      card,
      mod.is_disabled ? "status-missing" : "status-covered",
      mod.is_disabled ? "Desactivado" : "Activo"
    );
  } else {
    // Clear served highlights when multiple mods are selected
    document.querySelectorAll(".mgr-mod-card").forEach((c) => c.classList.remove("served-highlight"));
  }

  updateBatchBarUI(allVisibleMods);
}

function updateBatchBarUI(allVisibleMods) {
  if (!el.mgrBatchBar) return;
  const count = state.selectedModPaths.size;
  if (count > 0) {
    el.mgrBatchBar.classList.remove("hidden");
    if (el.mgrBatchCount) {
      el.mgrBatchCount.textContent = `${count} ${count === 1 ? "mod seleccionado" : "mods seleccionados"}`;
    }
  } else {
    el.mgrBatchBar.classList.add("hidden");
  }
}

async function handleBatchToggle(enable) {
  const { mods } = getActiveManagerModsAndPath();
  const targets = mods.filter(
    (m) => state.selectedModPaths.has(m.filepath) && m.is_disabled === enable
  );

  if (targets.length === 0) {
    showToast(
      enable
        ? "Ninguno de los mods seleccionados está desactivado."
        : "Ninguno de los mods seleccionados está activo."
    );
    return;
  }

  showToast(`${enable ? "Habilitando" : "Desactivando"} ${targets.length} mods...`);

  let count = 0;
  for (const mod of targets) {
    try {
      const updated = await invoke("toggle_mod_disabled", { filePath: mod.filepath });
      updateModInState(mod, updated);
      count++;
    } catch (err) {
      console.error("Error batch toggle:", err);
    }
  }

  renderCurrentView();

  showToast(
    enable
      ? `Se activaron ${count} mods correctamente`
      : `Se desactivaron ${count} mods correctamente`
  );
}

async function handleBatchCopy() {
  const { mods } = getActiveManagerModsAndPath();
  const selected = mods.filter((m) => state.selectedModPaths.has(m.filepath));
  if (selected.length === 0) {
    showToast("No hay mods seleccionados.");
    return;
  }

  const text = selected.map((m) => m.display_name).join("\n");
  try {
    await navigator.clipboard.writeText(text);
    showToast(`Se copiaron ${selected.length} nombres de mods al portapapeles`);
  } catch (err) {
    showToast("Error al copiar al portapapeles");
  }
}

function handleBatchClear() {
  state.selectedModPaths.clear();
  state.lastSelectedMod = null;
  document.querySelectorAll(".mgr-mod-card").forEach((c) => {
    c.classList.remove("selected", "served-highlight");
  });
  if (el.mgrBatchBar) el.mgrBatchBar.classList.add("hidden");
}

async function handleToggleModDisabled(mod) {
  try {
    const updated = await invoke("toggle_mod_disabled", { filePath: mod.filepath });
    updateModInState(mod, updated);
    renderCurrentView();
    showToast(
      updated.is_disabled
        ? `Mod desactivado: ${updated.display_name}`
        : `Mod activado: ${updated.display_name}`
    );
  } catch (err) {
    showToast(`Error: ${err}`);
  }
}

function handleDeleteMod(mod) {
  state.modToDelete = mod;
  if (el.deleteModalFilename) el.deleteModalFilename.textContent = mod.filename;
  if (el.deleteModalFilepath) el.deleteModalFilepath.textContent = mod.filepath;
  if (el.modalDelete) el.modalDelete.classList.remove("hidden");
}

function closeDeleteModal() {
  state.modToDelete = null;
  if (el.modalDelete) el.modalDelete.classList.add("hidden");
}

async function confirmDeleteMod() {
  if (!state.modToDelete) return;
  try {
    await invoke("delete_mod_file", { filePath: state.modToDelete.filepath });
    const name = state.modToDelete.display_name;
    removeModFromState(state.modToDelete);
    closeDeleteModal();
    if (state.mods1.length > 0 && state.mods2.length > 0) {
      await recompute();
    } else {
      renderCurrentView();
    }
    showToast(`Mod eliminado del disco: ${name}`);
  } catch (err) {
    showToast(`Error al eliminar mod: ${err}`);
  }
}

async function openModDetails(mod) {
  state.modForDetails = mod;
  try {
    if (el.detIconBox) {
      el.detIconBox.className = `mod-icon-box mod-icon-box-lg ${getCategoryClass(mod.category)}`;
    }
    if (el.detIconImg && el.detIconPh) {
      el.detIconImg.classList.add("hidden");
      el.detIconPh.classList.remove("hidden");
      el.detIconPh.textContent = getInitials(mod.display_name);
      queueModIcon(mod, el.detIconImg, el.detIconPh);
    }

    const details = await invoke("get_mod_details", {
      modId: mod.mod_id || "",
      slug: mod.clean_slug || "",
      name: mod.display_name || "",
      rawDesc: mod.description || "",
      category: mod.category || "General",
    });

    if (el.detModName) el.detModName.textContent = details.name;
    if (el.detCatBadge) {
      el.detCatBadge.textContent = details.category;
      el.detCatBadge.className = `cat-badge ${getCategoryClass(details.category)}`;
    }
    if (el.detStatusBadge) {
      el.detStatusBadge.textContent = mod.is_disabled ? "Desactivado" : "Activo";
      el.detStatusBadge.className = `status-badge ${mod.is_disabled ? "missing" : "covered"}`;
    }

    if (el.detDesc) el.detDesc.textContent = details.description_es;
    if (el.detFeaturesList) {
      el.detFeaturesList.innerHTML = details.features
        .map((f) => `<li>${escapeHtml(f)}</li>`)
        .join("");
    }
    if (el.detCommandsBox) {
      el.detCommandsBox.innerHTML = renderCommandsHtml(details.commands);
    }
    if (el.detConfigTip) el.detConfigTip.textContent = details.config_tip;

    const searchQuery = getCleanSearchQuery(mod);
    if (el.detBtnWiki) el.detBtnWiki.dataset.url = details.wiki_url;
    if (el.detBtnModrinth)
      el.detBtnModrinth.dataset.url = `https://modrinth.com/mods?q=${encodeURIComponent(searchQuery)}`;
    if (el.detBtnCurseforge)
      el.detBtnCurseforge.dataset.url = `https://www.curseforge.com/minecraft/search?page=1&class=mc-mods&search=${encodeURIComponent(searchQuery)}`;
    if (el.detBtnSource) el.detBtnSource.dataset.url = details.source_url;

    if (el.modalDetails) el.modalDetails.classList.remove("hidden");
  } catch (err) {
    showToast(`Error al obtener detalles: ${err}`);
  }
}

function closeDetailsModal() {
  state.modForDetails = null;
  if (el.modalDetails) el.modalDetails.classList.add("hidden");
}

async function openExternalUrl(url) {
  if (!url) return;
  try {
    await invoke("open_browser", { url });
  } catch (e) {
    window.open(url, "_blank");
  }
}

// Skin assigned in the profile, as PNG base64 for the launcher's local skin server.
// Custom skin: the uploaded image. Official: the account's skin (Pinecone/Prism accounts)
// or the public skin of that username.
const skinCacheByUser = new Map();

async function getActiveSkinForGame() {
  const user = state.activeUser;
  if (!user || !user.username) return null;
  const slim = user.skinModelType === "slim";
  const cacheKey = `${user.username.toLowerCase()}::${user.activeSkinId || "default"}`;
  let dataUrl = user.activeSkinId && user.customSkinData ? user.customSkinData : null;
  if (!dataUrl && skinCacheByUser.has(cacheKey)) {
    const cached = skinCacheByUser.get(cacheKey);
    return cached ? { pngBase64: cached, slim } : null;
  }
  if (!dataUrl) {
    try {
      const acc = await invoke("get_account_skin", { username: user.username });
      if (acc && acc.skin_data_url) dataUrl = acc.skin_data_url;
    } catch {}
  }
  if (!dataUrl) {
    try {
      const lsKey = `ika_minotar_skin_${user.username.toLowerCase()}`;
      const fromLs = localStorage.getItem(lsKey);
      if (fromLs) {
        dataUrl = fromLs === "NONE" ? null : fromLs;
      } else {
        const res = await fetch(`https://minotar.net/skin/${encodeURIComponent(user.username)}`, {
          signal: AbortSignal.timeout(1200),
        });
        if (res.ok) {
          const blob = await res.blob();
          dataUrl = await new Promise((resolve) => {
            const r = new FileReader();
            r.onload = () => resolve(r.result);
            r.onerror = () => resolve(null);
            r.readAsDataURL(blob);
          });
          if (dataUrl) {
            try { localStorage.setItem(lsKey, dataUrl); } catch {}
          }
        } else {
          try { localStorage.setItem(lsKey, "NONE"); } catch {}
        }
      }
    } catch {}
  }
  const b64 = typeof dataUrl === "string" && dataUrl.startsWith("data:image/png") ? dataUrl.split(",")[1] : null;
  skinCacheByUser.set(cacheKey, b64 || null);
  return b64 ? { pngBase64: b64, slim } : null;
}

// `instOverride`: launch that instance (Gestor de Instancia); otherwise the one selected in Inicio.
async function handlePlayGame(instOverride) {
  const forced = instOverride && instOverride.path ? instOverride : null;
  const { path } = getActiveManagerModsAndPath();
  const targetPath = forced ? forced.path : path || state.path1 || DEFAULT_PATH_1;
  const instanceName = forced ? getCustomInstanceNamesMap()[forced.path] || forced.name : getInstanceNameFromPath(targetPath);

  // 1. Mark as launched so the console dock opens and remains active
  hasUserTriggeredLaunch = true;
  if (el.homeConsolePreviewDock) {
    el.homeConsolePreviewDock.classList.remove("hidden");
  }

  // 2. Track in recentInstances ONLY when actually launched
  const currentInst = forced || (homeInstancesList && homeInstancesList[homeCurrentInstanceIndex]) ||
                      (homeInstancesAll && homeInstancesAll.find(i => i.path === targetPath || i.mods_path === targetPath));
  const realPath = currentInst ? currentInst.path : targetPath;
  if (isInstanceGameActive(realPath || targetPath)) {
    showToast(`${instanceName} ya se está ejecutando`);
    return;
  }
  if (realPath) {
    recentInstances.add(realPath);
    try {
      localStorage.setItem("modcomparer_launched_recents", JSON.stringify([...recentInstances].slice(-15)));
    } catch {}
  }

  // Offline account: the in-game name is the username of the active profile
  const username = (state.activeUser?.username || "").trim();
  if (!username) {
    showToast("Agrega un usuario en tu perfil para poder jugar");
    return;
  }

  showToast(`Iniciando ${instanceName}...`);
  updateHomeConsolePreview();
  showLaunchProgress(instanceName, "Preparando...", 0, 0);
  logToConsole("SYS", `Iniciando ${instanceName} como ${username}...`, "sys");
  gameMilestoneState.delete(normInstancePath(realPath || targetPath));
  setGameState(realPath || targetPath, "preparing");
  pushGameLog(realPath || targetPath, [{ level: "INFO", text: `[Launcher] Iniciando ${instanceName} como ${username}...`, ts: Date.now() }]);

  try {
    const skin = await getActiveSkinForGame();
    const res = await invoke("launch_game", {
      instancePath: realPath || targetPath,
      username,
      skin,
    });
    showToast(res);
    updateHomeConsolePreview();
    if (typeof recordRecentActivity === "function") {
      recordRecentActivity("launch", "Juego iniciado", `Lanzada instancia ${instanceName} con éxito`);
    }
  } catch (err) {
    showToast(`Error al iniciar juego: ${String(err).split("\n")[0]}`);
    showLaunchProgress(instanceName, String(err), 0, 0, true);
    String(err).split("\n").filter(Boolean).forEach((l) => logToConsole("ERROR", l, "error"));
    setGameState(realPath || targetPath, String(err).includes("código") ? "crashed" : "failed");
  }
}

// --- Launch progress card (downloads of Minecraft files, Java, natives...) ---
let launchProgressHideTimer = null;

function showLaunchProgress(instanceName, message, done, total, isError = false) {
  let card = document.getElementById("launch-progress-card");
  if (!card) {
    card = document.createElement("div");
    card.id = "launch-progress-card";
    card.className = "launch-progress-card";
    card.innerHTML = `
      <div class="launch-progress-head">
        <span class="launch-progress-title"></span>
        <button type="button" class="launch-progress-close" aria-label="Cerrar">✕</button>
      </div>
      <div class="launch-progress-msg"></div>
      <div class="launch-progress-bar"><div class="launch-progress-fill"></div></div>
      <div class="launch-progress-count"></div>`;
    card.querySelector(".launch-progress-close").addEventListener("click", () => card.classList.add("hidden"));
    document.body.appendChild(card);
  }
  clearTimeout(launchProgressHideTimer);
  card.classList.remove("hidden");
  card.classList.toggle("is-error", isError);
  card.querySelector(".launch-progress-title").textContent = isError ? `No se pudo iniciar ${instanceName}` : instanceName;
  card.querySelector(".launch-progress-msg").textContent = message;
  const fill = card.querySelector(".launch-progress-fill");
  const determinate = total > 0;
  card.classList.toggle("is-indeterminate", !determinate && !isError);
  fill.style.width = determinate ? `${Math.round((done / total) * 100)}%` : "100%";
  card.querySelector(".launch-progress-count").textContent = determinate ? `${done} / ${total}` : "";
}

let lastLaunchStageLogged = "";
let mcLaunchDlTracker = new Map();
listen("mc-launch-progress", (event) => {
  const p = event.payload || {};
  const name = getInstanceNameFromPath(p.instance || "") || "Minecraft";
  const instKey = normInstancePath(p.instance || "");
  const isDownload = p.stage === "libraries" || p.stage === "assets" || p.stage === "java" || (p.message && /descarg/i.test(p.message));

  if (p.stage === "error") {
    showLaunchProgress(name, p.message || "Error", 0, 0, true);
    lastLaunchStageLogged = "";
    const tracker = mcLaunchDlTracker.get(instKey);
    if (tracker) {
      tracker.error(p.message || "Error al descargar recursos");
      mcLaunchDlTracker.delete(instKey);
    }
    return;
  }
  if (p.stage === "done") {
    setGameState(p.instance, "running");
    const tracker = mcLaunchDlTracker.get(instKey);
    if (tracker) {
      tracker.finish("Recursos descargados correctamente");
      mcLaunchDlTracker.delete(instKey);
    }
  } else if (p.message) {
    setGameState(p.instance, "preparing", p.message.replace(/\.\.\.$/, ""));
  }

  if (isDownload) {
    const pct = p.total > 0 ? Math.round((p.done / p.total) * 100) : null;
    let tracker = mcLaunchDlTracker.get(instKey);
    const textDesc = p.total > 0 ? `${p.message || "Descargando"} (${p.done}/${p.total})` : (p.message || "Descargando recursos...");
    if (!tracker) {
      tracker = startDownloadNotification({
        id: `mc-dl-${instKey}`,
        title: `${name} · Recursos`,
        text: textDesc,
        progress: pct
      });
      mcLaunchDlTracker.set(instKey, tracker);
    } else {
      tracker.update(pct, textDesc);
    }
  }

  const stageKey = `${p.instance}|${p.stage}|${p.message}`;
  if (p.message && stageKey !== lastLaunchStageLogged) {
    lastLaunchStageLogged = stageKey;
    const stageText = p.total > 0 ? `${p.message} (${p.total} archivos)` : p.message;
    logToConsole("SYS", stageText, "sys");
    pushGameLog(p.instance, [{ level: "INFO", text: `[Launcher] ${stageText}`, ts: Date.now() }]);
  }
  showLaunchProgress(name, p.message || "", p.done || 0, p.total || 0);
  if (p.stage === "done") {
    launchProgressHideTimer = setTimeout(() => document.getElementById("launch-progress-card")?.classList.add("hidden"), 2500);
  }
});

// --- Live game console (output of the running Minecraft, sent by mc.rs) ---
const CONSOLE_MAX_LINES = 3000;

function normInstancePath(p) {
  return String(p || "").replace(/\//g, "\\").replace(/\\+$/, "").toLowerCase();
}

function pushGameLog(instance, lines) {
  const key = normInstancePath(instance);
  const buf = gameLogBuffers.get(key) || [];
  buf.push(...lines);
  if (buf.length > GAME_LOG_BUFFER_LINES) buf.splice(0, buf.length - GAME_LOG_BUFFER_LINES);
  gameLogBuffers.set(key, buf);
  gameLogTotals.set(key, (gameLogTotals.get(key) || 0) + lines.length);
  const inst = currentHomeInstance();
  if (inst && normInstancePath(inst.path) === key) renderHcpTerminal(inst, null);
}

const GAME_LEVEL_TAG = { ERROR: "error", FATAL: "error", WARN: "warn", DEBUG: "info", TRACE: "info", MILESTONE: "sys" };

function appendGameLinesToConsole(lines) {
  if (!el.consoleOutput || !lines.length) return;
  const frag = document.createDocumentFragment();
  for (const l of lines) {
    const level = String(l.level || "INFO").toUpperCase();
    const line = document.createElement("div");
    line.className = "console-line";
    const time = document.createElement("span");
    time.className = "console-line-time";
    time.textContent = `[${(l.ts ? new Date(l.ts) : new Date()).toTimeString().split(" ")[0]}]`;
    const tag = document.createElement("span");
    tag.className = `console-line-tag tag-${GAME_LEVEL_TAG[level] || "mc"}`;
    tag.textContent = level === "MILESTONE" ? "LISTO" : level;
    const msg = document.createElement("span");
    msg.className = "console-line-msg";
    msg.textContent = l.text;
    line.append(time, tag, msg);
    frag.appendChild(line);
  }
  el.consoleOutput.appendChild(frag);
  // Keep the console from growing without limit during long sessions.
  const extra = el.consoleOutput.childElementCount - CONSOLE_MAX_LINES;
  for (let i = 0; i < extra; i++) el.consoleOutput.firstElementChild?.remove();
  if (el.consoleAutoscrollChk && el.consoleAutoscrollChk.checked) {
    el.consoleOutput.scrollTop = el.consoleOutput.scrollHeight;
  }
}

listen("mc-game-log", (event) => {
  const p = event.payload || {};
  const lines = Array.isArray(p.lines) ? p.lines : [];
  if (!lines.length) return;
  pushGameLog(p.instance, lines);
  appendGameLinesToConsole(lines);
  detectGameMilestones(p.instance, lines);
});

listen("mc-game-exit", (event) => {
  const p = event.payload || {};
  const name = getInstanceNameFromPath(p.instance || "") || "Minecraft";
  const now = Date.now();
  const lines = [];
  if (p.crashed) {
    lines.push({ level: "ERROR", text: `Minecraft se cerró inesperadamente (código ${p.code}).`, ts: now });
    String(p.summary || "").split("\n").filter(Boolean).forEach((t) => lines.push({ level: "ERROR", text: t, ts: now }));
    if (p.crashReport) lines.push({ level: "WARN", text: `Reporte de crash: ${p.crashReport}`, ts: now });
    const cause = String(p.summary || "").split("\n").find((t) => !t.startsWith("Description:")) || "";
    showToast(`${name} crasheó: ${cause.slice(0, 120)}`);
    showLaunchProgress(name, `Código ${p.code}\n${p.summary || ""}`, 0, 0, true);
  } else {
    lines.push({ level: "INFO", text: p.stopped ? "Juego detenido desde el launcher." : "Minecraft se cerró correctamente.", ts: now });
  }
  const ms = gameMilestoneState.get(normInstancePath(p.instance));
  if (ms) {
    clearTimeout(ms.timer);
    ms.ready = true;
  }
  setGameState(p.instance, p.crashed ? "crashed" : "closed", p.crashed ? `código ${p.code}` : "");
  pushGameLog(p.instance, lines);
  appendGameLinesToConsole(lines);
  updateHomeConsolePreview();
});

// =========================================================
// SMOOTH INERTIA MOMENTUM SCROLL ENGINE
// =========================================================
const smoothScrollStates = new WeakMap();

function findScrollableParent(element) {
  let cur = element;
  while (cur && cur !== document.body && cur !== document.documentElement) {
    if (cur.nodeType === 1) {
      const style = window.getComputedStyle(cur);
      const overflowY = style.overflowY;
      if (
        (overflowY === "auto" || overflowY === "scroll") &&
        cur.scrollHeight > cur.clientHeight + 1
      ) {
        return cur;
      }
    }
    cur = cur.parentElement;
  }
  return null;
}

function getScrollState(container) {
  if (!smoothScrollStates.has(container)) {
    smoothScrollStates.set(container, {
      current: container.scrollTop,
      target: container.scrollTop,
      animId: null,
    });
  }
  return smoothScrollStates.get(container);
}

function setupSmoothScrolling() {
  window.addEventListener(
    "wheel",
    (e) => {
      // Don't intercept browser shortcuts or scrolling inside the context menu
      if (e.ctrlKey || e.shiftKey) return;
      if (e.target && e.target.closest && e.target.closest("#mod-context-menu")) return;

      let container = findScrollableParent(e.target);
      if (!container && e.target && e.target.closest) {
        const modalBox = e.target.closest(".modal-wallpapers-box");
        if (modalBox) {
          const activePanel = modalBox.querySelector(".mbg-tab-panel:not(.hidden)");
          if (activePanel) {
            const body = activePanel.querySelector(".wallpapers-modal-body");
            if (body && body.scrollHeight > body.clientHeight + 1) {
              container = body;
            }
          }
        }
      }
      if (!container) return;

      const maxScroll = container.scrollHeight - container.clientHeight;
      if (maxScroll <= 0) return;

      let delta = e.deltaY;
      if (e.deltaMode === 1) delta *= 36;
      else if (e.deltaMode === 2) delta *= 100;

      // Don't block if already at boundaries trying to scroll outside
      if (delta < 0 && container.scrollTop <= 0) return;
      if (delta > 0 && container.scrollTop >= maxScroll) return;

      e.preventDefault();

      const state = getScrollState(container);

      // Sync if user moved scrollbar manually or layout changed
      if (Math.abs(container.scrollTop - state.current) > 4) {
        state.current = container.scrollTop;
        state.target = container.scrollTop;
      }

      // Smooth impulse with natural inertia momentum
      const impulse = delta * 1.05;
      const maxLead = 480;
      state.target = Math.max(0, Math.min(maxScroll, state.target + impulse));
      state.target = Math.max(state.current - maxLead, Math.min(state.current + maxLead, state.target));

      if (!state.animId) {
        const step = () => {
          const diff = state.target - state.current;
          if (Math.abs(diff) < 0.5) {
            state.current = state.target;
            container.scrollTop = state.current;
            state.animId = null;
          } else {
            // Easing factor of 0.11 provides that silky, cushioned gliding deceleration
            state.current += diff * 0.11;
            container.scrollTop = state.current;
            state.animId = requestAnimationFrame(step);
          }
        };
        state.animId = requestAnimationFrame(step);
      }
    },
    { passive: false }
  );

  // Instantly cancel momentum when clicking or dragging the scrollbar thumb
  window.addEventListener(
    "pointerdown",
    (e) => {
      const container = findScrollableParent(e.target);
      if (container && smoothScrollStates.has(container)) {
        const state = smoothScrollStates.get(container);
        state.current = container.scrollTop;
        state.target = container.scrollTop;
        if (state.animId) {
          cancelAnimationFrame(state.animId);
          state.animId = null;
        }
      }
    },
    { passive: true }
  );
}

function findModByFilepath(filepath) {
  if (!filepath) return null;
  if (state.currentView === "manager") {
    const { mods } = getActiveManagerModsAndPath();
    const found = mods.find((m) => m.filepath === filepath);
    if (found) return found;
  }
  return (
    state.mods1.find((m) => m.filepath === filepath) ||
    state.mods2.find((m) => m.filepath === filepath) ||
    state.managerCustomMods.find((m) => m.filepath === filepath) ||
    null
  );
}

function openContextMenu(mod, x, y) {
  if (!el.modContextMenu) return;
  state.contextMenuMod = mod;
  if (el.ctxModName) el.ctxModName.textContent = mod.display_name;

  const normModCat = (mod.category || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");

  el.modContextMenu.querySelectorAll(".context-menu-item[data-cat]").forEach((item) => {
    const cat = item.dataset.cat;
    const normItemCat = (cat || "").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    item.classList.toggle("active", normModCat === normItemCat);
  });

  el.modContextMenu.classList.remove("hidden");

  // Adjust for viewport boundaries
  const rect = el.modContextMenu.getBoundingClientRect();
  const winWidth = window.innerWidth;
  const winHeight = window.innerHeight;

  let left = x;
  let top = y;

  if (left + rect.width > winWidth - 10) {
    left = Math.max(10, x - rect.width);
  }
  if (top + rect.height > winHeight - 10) {
    top = Math.max(10, winHeight - rect.height - 10);
  }

  el.modContextMenu.style.left = `${left}px`;
  el.modContextMenu.style.top = `${top}px`;

  const listEl = el.modContextMenu.querySelector(".context-menu-list");
  if (listEl) listEl.scrollTop = 0;
}

function closeContextMenu() {
  if (el.modContextMenu && !el.modContextMenu.classList.contains("hidden")) {
    el.modContextMenu.classList.add("hidden");
    state.contextMenuMod = null;
  }
}

const GENERIC_KEYS = new Set([
  "",
  "minecraft",
  "forge",
  "fabric",
  "neoforge",
  "quilt",
  "liteloader",
  "rift",
  "mod",
  "mods",
  "core",
  "api",
  "library",
  "lib",
  "client",
  "server",
  "java",
]);

function isGenericKey(key) {
  if (!key) return true;
  const k = key.trim().toLowerCase();
  return k.length < 3 || GENERIC_KEYS.has(k);
}

function rebuildCategorySummaries() {
  if (!state.comparison || !state.mods1) return;
  const matches = state.comparison.matches_1_to_2 || {};
  const missingIn2 = state.comparison.missing_in_2 || [];
  const missingSet = new Set(missingIn2.map((m) => m.filepath));

  const catMap = new Map();
  for (const cat of MANAGER_CATEGORY_ORDER) {
    catMap.set(cat, { category: cat, missing_mods: [], covered_count: 0, missing_count: 0 });
  }

  for (const m of state.mods1) {
    const cat = m.category || "General";
    if (!catMap.has(cat)) {
      catMap.set(cat, { category: cat, missing_mods: [], covered_count: 0, missing_count: 0 });
    }
    const entry = catMap.get(cat);
    if (missingSet.has(m.filepath)) {
      entry.missing_mods.push(m);
    } else if (matches[m.filepath]) {
      entry.covered_count++;
    }
  }

  const summaries = [];
  for (const entry of catMap.values()) {
    entry.missing_count = entry.missing_mods.length;
    if (entry.missing_count > 0 || entry.covered_count > 0) {
      summaries.push(entry);
    }
  }

  state.comparison.category_summaries = summaries;
}

function updateModCategoryInMemory(mod, newCat) {
  if (!mod || !newCat) return;
  const oldCat = mod.category;
  if (oldCat === newCat) return;

  const targetPath = mod.filepath;
  const targetId = (mod.mod_id || "").toLowerCase().trim();
  const targetSlug = (mod.clean_slug || "").toLowerCase().trim();
  const targetCanon = (mod.canonical_id || "").toLowerCase().trim();
  const targetFile = (mod.filename || "").toLowerCase().trim();

  const matchesMod = (m) => {
    if (!m) return false;
    // 1. Primary match: exact same file path
    if (targetPath && m.filepath === targetPath) return true;

    // 2. Cross-instance match: NEVER match via generic identifiers!
    const id = (m.mod_id || "").toLowerCase().trim();
    const slug = (m.clean_slug || "").toLowerCase().trim();
    const canon = (m.canonical_id || "").toLowerCase().trim();
    const fn = (m.filename || "").toLowerCase().trim();

    if (!isGenericKey(targetId) && id && id === targetId) return true;
    if (!isGenericKey(targetSlug) && slug && slug === targetSlug) return true;
    if (!isGenericKey(targetCanon) && canon && canon === targetCanon) return true;
    if (targetFile && fn && targetFile === fn) return true;

    return false;
  };

  const updateInList = (list) => {
    if (!list) return;
    for (const m of list) {
      if (matchesMod(m)) {
        m.category = newCat;
        if (newCat === "APIs y Dependencias" || newCat === "Dependencias") {
          m.is_api = true;
        }
      }
    }
  };

  updateInList(state.mods1);
  updateInList(state.mods2);
  updateInList(state.managerCustomMods);

  // Recalculate category summaries cleanly and accurately
  rebuildCategorySummaries();

  // Update selected mod if currently inspected
  if (state.selectedMod && matchesMod(state.selectedMod)) {
    state.selectedMod.category = newCat;
    if (newCat === "APIs y Dependencias" || newCat === "Dependencias") state.selectedMod.is_api = true;
    if (el.inspCatBadge) {
      el.inspCatBadge.textContent = newCat;
      el.inspCatBadge.className = `cat-badge ${getCategoryClass(newCat)}`;
    }
    if (el.rightCatBadge) {
      el.rightCatBadge.textContent = newCat;
      el.rightCatBadge.className = `cat-badge ${getCategoryClass(newCat)}`;
    }
    if (el.inspIconBox) {
      el.inspIconBox.className = `mod-icon-box mod-icon-box-lg ${getCategoryClass(newCat)}`;
    }
    if (el.rightIconBox) {
      el.rightIconBox.className = `mod-icon-box mod-icon-box-giant ${getCategoryClass(newCat)}`;
    }
  }
}

// WebView2's own right-click menu (Inspect, Back, Reload, Save as...) has no place in the
// launcher. Text fields keep it so copy/paste still work there; our own menus call
// preventDefault themselves, so they are unaffected.
function initNativeContextMenuBlock() {
  document.addEventListener("contextmenu", (e) => {
    if (e.target instanceof Element && e.target.closest("input, textarea, [contenteditable='true']")) return;
    e.preventDefault();
  });
  // Middle-clicking a link would open it in a bare WebView2 popup window.
  document.addEventListener("auxclick", (e) => {
    if (e.target instanceof Element && e.target.closest("a[href]")) e.preventDefault();
  });
}

function isEditableTarget(node) {
  return node instanceof Element && !!node.closest("input, textarea, select, [contenteditable='true']");
}

// Escape in any section goes back to Inicio, but only when nothing else used that key press
// (a modal, a menu, a picker, a detail panel...). Instead of listing every overlay, it watches
// the DOM while the key event is dispatched: if any handler opened/closed something, the
// press was already consumed.
function initEscapeToHome() {
  let observer = null;
  window.addEventListener(
    "keydown",
    (e) => {
      if (e.key !== "Escape") return;
      observer?.disconnect();
      observer = new MutationObserver(() => {});
      observer.observe(document.body, {
        subtree: true,
        childList: true,
        attributes: true,
        attributeOldValue: true,
        attributeFilter: ["class", "style", "hidden", "open"],
      });
    },
    true
  );
  window.addEventListener("keydown", (e) => {
    if (e.key !== "Escape" || !observer) return;
    const records = observer.takeRecords();
    observer.disconnect();
    observer = null;
    if (e.defaultPrevented || e.repeat || state.currentView === "inicio") return;
    if (isEditableTarget(e.target)) return;
    if (document.querySelector(".modal-overlay:not(.hidden)")) return;
    // classList.add/remove write the attribute even when nothing changes, so only count an
    // attribute whose final value differs from the value it had before the key press.
    const firstOld = new Map();
    for (const r of records) {
      if (r.type !== "attributes") return; // nodes added/removed: something reacted
      const key = r.target;
      if (!firstOld.has(key)) firstOld.set(key, new Map());
      const attrs = firstOld.get(key);
      if (!attrs.has(r.attributeName)) attrs.set(r.attributeName, r.oldValue);
    }
    for (const [target, attrs] of firstOld) {
      for (const [name, oldValue] of attrs) {
        if (target.getAttribute(name) !== oldValue) return;
      }
    }
    switchView("inicio");
  });
}

function initContextMenu() {
  if (!el.modContextMenu) return;

  // Right-click delegation on mod cards
  document.addEventListener("contextmenu", (e) => {
    const card = e.target.closest(".func-card, .mgr-mod-card");
    if (!card) {
      closeContextMenu();
      return;
    }

    const filepath = card.dataset.filepath;
    const mod = card._mod || findModByFilepath(filepath);
    if (!mod) return;

    e.preventDefault();
    openContextMenu(mod, e.clientX, e.clientY);
  });

  // Close on outside click
  document.addEventListener("click", (e) => {
    if (!e.target.closest("#mod-context-menu")) {
      closeContextMenu();
    }
  });

  // Close on Escape
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      closeContextMenu();
    }
  });

  // Close on scroll outside the context menu
  window.addEventListener(
    "scroll",
    (e) => {
      if (e.target instanceof Element && e.target.closest("#mod-context-menu")) {
        return;
      }
      closeContextMenu();
    },
    true
  );

  // Category item click (Instant zero-lag synchronous UI update)
  el.modContextMenu.querySelectorAll(".context-menu-item[data-cat]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const targetCat = btn.dataset.cat;
      const mod = state.contextMenuMod;
      if (!mod || !targetCat) return;
      closeContextMenu();

      if (mod.category === targetCat) return;

      let keys = [mod.mod_id, mod.clean_slug, mod.canonical_id]
        .map((k) => (k || "").trim().toLowerCase())
        .filter((k) => !isGenericKey(k));

      if (keys.length === 0 && mod.filename) {
        keys = [mod.filename.replace(/\.jar(\.disabled)?$/i, "").toLowerCase()];
      }

      // 1. Instant synchronous in-memory update
      updateModCategoryInMemory(mod, targetCat);

      // 2. Instant synchronous view update (0ms delay)
      if (state.currentView === "columns") {
        try {
          const cards = document.querySelectorAll(`.func-card[data-filepath="${CSS.escape(mod.filepath)}"]`);
          cards.forEach((card) => {
            card.className = `func-card ${getCategoryClass(targetCat)}`;
            const catBadge = card.querySelector(".cat-badge");
            if (catBadge) {
              catBadge.textContent = targetCat;
              catBadge.className = `cat-badge ${getCategoryClass(targetCat)}`;
            }
          });
        } catch {
          renderCurrentView();
        }
      } else {
        renderCurrentView();
      }

      showToast(`Mod "${mod.display_name}" movido a ${targetCat}`);

      // 3. Persist to disk in background asynchronously without blocking UI
      invoke("set_mod_user_category", { modKeys: keys, category: targetCat }).catch((err) => {
        console.error("Error guardando categoría en disco:", err);
      });
    });
  });

  // Reset item click (Instant zero-lag lookup & update)
  if (el.ctxBtnReset) {
    el.ctxBtnReset.addEventListener("click", async () => {
      const mod = state.contextMenuMod;
      if (!mod) return;
      closeContextMenu();

      let keys = [mod.mod_id, mod.clean_slug, mod.canonical_id]
        .map((k) => (k || "").trim().toLowerCase())
        .filter((k) => !isGenericKey(k));

      if (keys.length === 0 && mod.filename) {
        keys = [mod.filename.replace(/\.jar(\.disabled)?$/i, "").toLowerCase()];
      }

      try {
        // Fast in-memory lookup from Rust knowledge base (~0.2ms)
        const defaultCat = await invoke("infer_mod_default_category", {
          name: mod.display_name || "",
          slug: mod.clean_slug || "",
          rawDesc: mod.description || "",
        });

        // 1. Instant in-memory update
        updateModCategoryInMemory(mod, defaultCat);

        // 2. Instant view update
        if (state.currentView === "columns") {
          try {
            const cards = document.querySelectorAll(`.func-card[data-filepath="${CSS.escape(mod.filepath)}"]`);
            cards.forEach((card) => {
              card.className = `func-card ${getCategoryClass(defaultCat)}`;
              const catBadge = card.querySelector(".cat-badge");
              if (catBadge) {
                catBadge.textContent = defaultCat;
                catBadge.className = `cat-badge ${getCategoryClass(defaultCat)}`;
              }
            });
          } catch {
            renderCurrentView();
          }
        } else {
          renderCurrentView();
        }

        showToast(`Categoría restablecida para "${mod.display_name}"`);

        // 3. Persist reset in background without blocking UI
        invoke("reset_mod_user_category", { modKeys: keys }).catch((err) => {
          console.error("Error restableciendo categoría en disco:", err);
        });
      } catch (err) {
        console.error("Error al restablecer:", err);
        showToast("Error al restablecer categoría");
      }
    });
  }
}

